    private static Rectangle[] createRectangleArray(int count) {
        Rectangle[] rectangles = new Rectangle[count];
        for (int i = 0; i < rectangles.length; i++) {
            rectangles[i] = new Rectangle();
        }
        return rectangles;
    }

