    private final Comparator<CarTemplate> leaderboardComparator = new Comparator<CarTemplate>() {
        @Override
        public int compare(CarTemplate left, CarTemplate right) {
            if (isLiveLapRaceMode()) {
                return compareRaceStanding(left, right);
            }
            if (left.totalPoints != right.totalPoints) {
                return right.totalPoints - left.totalPoints;
            }
            if (left.roundFinishPosition != right.roundFinishPosition) {
                return compareFinishPosition(left.roundFinishPosition, right.roundFinishPosition);
            }
            if (left.playerControlled != right.playerControlled) {
                return left.playerControlled ? -1 : 1;
            }
            return left.name.compareTo(right.name);
        }
    };
    private final Comparator<CarTemplate> projectedChampionshipComparator =
            new Comparator<CarTemplate>() {
                @Override
                public int compare(CarTemplate left, CarTemplate right) {
                    int pointsCompare =
                            Integer.compare(
                                    getProjectedChampionshipPoints(right),
                                    getProjectedChampionshipPoints(left));
                    if (pointsCompare != 0) {
                        return pointsCompare;
                    }
                    int racePositionCompare =
                            Integer.compare(
                                    getCurrentRacePosition(left),
                                    getCurrentRacePosition(right));
                    if (racePositionCompare != 0) {
                        return racePositionCompare;
                    }
                    return Integer.compare(left.vehicleId, right.vehicleId);
                }
            };

