    @Override
    public void create() {
        Box2D.init();

        worldCamera = new OrthographicCamera();
        worldViewport = new ExtendViewport(WORLD_WIDTH, WORLD_HEIGHT, worldCamera);

        hudCamera = new OrthographicCamera();
        hudViewport = new ScreenViewport(hudCamera);

        shapeRenderer = new ShapeRenderer();
        spriteBatch = new SpriteBatch();
        raceIncidentPopup = new RaceIncidentPopup();
        eventCameraDirector = new EventCameraDirector();
        sidebarTablesDragGesture = new DragScrollGesture();
        customMenuDragGesture = new DragScrollGesture();
        inGamePanelsButtonBounds = new Rectangle();

        hudFont = new WeightedBitmapFont(0.65f);
        hudFont.setUseIntegerPositions(true);
        hudFont.getData().setScale(HUD_FONT_SCALE);

        titleFont = new WeightedBitmapFont(0.75f);
        titleFont.setUseIntegerPositions(true);
        titleFont.getData().setScale(TITLE_FONT_SCALE);

        leaderboardFont = new WeightedBitmapFont(0.65f);
        leaderboardFont.setUseIntegerPositions(true);
        leaderboardFont.getData().setScale(LEADERBOARD_FONT_SCALE);

        labelFont = new WeightedBitmapFont(0.65f);
        labelFont.setUseIntegerPositions(true);
        labelFont.getData().setScale(LABEL_FONT_SCALE);

        Gdx.input.setCatchKey(Input.Keys.BACK, true);
        Gdx.input.setInputProcessor(new InputAdapter() {
            @Override
            public boolean keyDown(int keycode) {
                if (pendingDrivingKeyBinding != null) {
                    if (keycode == Input.Keys.ESCAPE || keycode == Input.Keys.BACK) {
                        pendingDrivingKeyBinding = null;
                    } else {
                        drivingKeyBindings.rebind(pendingDrivingKeyBinding, keycode);
                        pendingDrivingKeyBinding = null;
                        saveMenuSettings();
                    }
                    optionsInputSuppressionFrames = 2;
                    return true;
                }
                if (!playerNameEditor.isEditing()) {
                    return false;
                }
                if (keycode == Input.Keys.ESCAPE || keycode == Input.Keys.BACK) {
                    playerNameCancelRequested = true;
                }
                return true;
            }

            @Override
            public boolean keyTyped(char character) {
                if (!playerNameEditor.isEditing()) {
                    return false;
                }
                if (character == '\n' || character == '\r') {
                    playerNameCommitRequested = true;
                } else {
                    playerNameEditor.type(character);
                }
                return true;
            }

            @Override
            public boolean scrolled(float amountX, float amountY) {
                return handleHudScrolled(amountY);
            }
        });
        rogueliteSaveRepository =
                new RogueliteSaveRepository(
                        new GdxPreferencesRogueliteSaveStore(
                                Gdx.app.getPreferences(ROGUELITE_SAVE_PREFS_NAME)));
        resize(Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
        loadingScreenPresented = false;
        loadingCompletionPresented = false;
        loadingStage = STARTUP_LOADING_SETTINGS_STAGE;
        loadingProgress = 0f;
        loadingDisplayedProgress = 0f;
        loadingStatus = "Loading settings";
        gameMode = GameMode.STARTUP_LOADING;
    }

    private void startNewGame() {
        startNewGame(false, selectedStartingTier, selectedCompetitionMode);
    }

    private void startSandboxGame() {
        startNewGame(true, 1, RogueliteCompetitionMode.CHAMPIONSHIP);
    }

    private void startNewGame(
            boolean sandbox,
            int startingTier,
            RogueliteCompetitionMode selectedMode) {
        if (!sandbox) {
            deleteRogueliteSave();
        }
        beginGameLoading(sandbox, null, startingTier, false, selectedMode);
    }

    private void continueSavedGame() {
        if (rogueliteSaveRepository == null) {
            continueAvailable = false;
            return;
        }
        RogueliteSaveData save = rogueliteSaveRepository.load();
        if (save == null) {
            deleteRogueliteSave();
            return;
        }

        selectedCompetitionMode =
                RogueliteCompetitionMode.fromId(save.competitionMode);
        if (selectedCompetitionMode.isCustom()) {
            refreshCustomGameMenuMaps();
            if (!customGameRules.restore(
                    save.customRules,
                    getCustomGameAvailableMapIds())) {
                deleteRogueliteSave();
                return;
            }
            customGameRulesInitialized = true;
            rogueliteRun.configureGameRules(customGameRules);
        } else {
            rogueliteRun.configureGameRules(new CustomGameRules());
        }
        if (!rogueliteRun.restore(save.run)) {
            deleteRogueliteSave();
            return;
        }

        selectedThemeIndex = findThemeIndex(save.themeName);
        configuredThemeName = getCurrentTheme().name;
        selectedPlayerCarIndex = Math.max(0, save.playerCarIndex);
        selectedStartingTier = rogueliteRun.getStartingTier();
        ownedRogueliteCardTypes = rogueliteRun.getPlayerCards();
        beginGameLoading(
                false,
                save,
                rogueliteRun.getStartingTier(),
                false,
                selectedCompetitionMode);
    }

    private void beginGameLoading(
            boolean sandbox,
            RogueliteSaveData save,
            int startingTier,
            boolean preserveSandboxConfiguration,
            RogueliteCompetitionMode selectedMode) {
        clearPlayerInput();
        stopVehicleSounds();
        competitionMode =
                selectedMode == null
                        ? RogueliteCompetitionMode.CHAMPIONSHIP
                        : selectedMode;
        rogueliteRun.configureGameRules(
                competitionMode.isCustom()
                        ? customGameRules
                        : new CustomGameRules());
        rogueliteRewardChoices = Collections.emptyList();
        roguelitePendingOffer = null;
        if (save == null) {
            ownedRogueliteCardTypes = Collections.emptyList();
        }
        rogueliteRewardSelection = 0;
        sandboxCollectionTargetVehicleId = -1;
        championshipTransitionPending = false;
        rogueliteRunEnded = false;
        playerWonRogueliteRun = false;
        rogueliteCollectionPage = 0;
        rogueliteCollectionReturnMode = GameMode.PLAYING;
        eventCameraSelected =
                !sandbox || sandboxLoadoutConfiguration.isAutomatic();
        cameraViewMode = CameraViewMode.TOP_DOWN;
        stopCameraGestures();
        freeCameraReturnHintTimer = 0f;
        lastAutoFollowedRaceIncidentSequence = -1L;
        eventCameraDirector.reset();
        pendingContinueSave = save;
        loadingCompletionMode = GameMode.PLAYING;
        stopAllMusic();
        loadingSandboxMode = sandbox;
        loadingStartingTier = startingTier;
        loadingPreserveSandboxConfiguration = sandbox && preserveSandboxConfiguration;
        loadingMapTransition = false;
        loadingScreenPresented = false;
        loadingCompletionPresented = false;
        loadingStage = LOADING_PREPARE_STAGE;
        loadingProgress = 0f;
        loadingDisplayedProgress = 0f;
        loadingStatus = "Preparing " + getCurrentTheme().displayName;
        gameMode = GameMode.LOADING;
    }

    private void beginMapTransitionLoading() {
        clearPlayerInput();
        stopVehicleSounds();
        stopCircuitMusic();
        loadingMapTransition = true;
        loadingCompletionMode = GameMode.PLAYING;
        loadingScreenPresented = false;
        loadingCompletionPresented = false;
        loadingStage = MAP_LOADING_PREPARE_STAGE;
        loadingProgress = 0f;
        loadingDisplayedProgress = 0f;
        loadingStatus = CircuitLoadingTransition.status(
                mapProgression.getCurrentMapNumber(),
                mapProgression.getMapCount());
        gameMode = GameMode.LOADING;
    }

    private void advancePendingMapTransitionLoading() {
        switch (loadingStage) {
            case MAP_LOADING_PREPARE_STAGE:
                disposeArenaSurfaceTextures();
                currentMap = null;
                completeLoadingStage(
                        0.25f,
                        CircuitLoadingTransition.status(
                                mapProgression.getCurrentMapNumber(),
                                mapProgression.getMapCount()));
                break;
            case MAP_LOADING_WORLD_STAGE:
                resetRound(true);
                persistRogueliteRun(RogueliteSaveData.PHASE_RACE);
                completeLoadingStage(0.92f, "Starting engines");
                break;
            case MAP_LOADING_READY_STAGE:
                completeLoadingStage(1f, "Ready");
                break;
            default:
                return;
        }
        loadingStage++;
    }

    private void advancePendingGameLoading() {
        switch (loadingStage) {
            case LOADING_PREPARE_STAGE:
                sandboxMode = loadingSandboxMode;
                disposeRaceSounds();
                disposeRosterSpriteTextures();
                disposeArenaSurfaceTextures();
                releaseSandboxMenuPreview();
                disposeMenuPresentationTextures();
                loadThemeEnemyNames();
                loadThemeTextures();
                int clampedPlayerCarIndex =
                        clampPlayerCarIndex(
                                selectedPlayerCarIndex,
                                getAvailableCarVisualCount());
                if (clampedPlayerCarIndex != selectedPlayerCarIndex) {
                    selectedPlayerCarIndex = clampedPlayerCarIndex;
                    saveMenuSettings();
                }
                completeLoadingStage(0.15f, "Loading drivers");
                break;
            case LOADING_DRIVERS_STAGE:
                rlEnemyPolicy = loadRlEnemyPolicy();
                rogueliteRun.configureCardStrategies(CardStrategyAssets.loadInternal());
                rlRecoveryPolicy = loadRlPolicy(
                        RL_RECOVERY_POLICY_PATH,
                        "shared-recovery",
                        RL_OBSERVATION_SIZE,
                        RL_ACTION_SIZE);
                rlOvertakingPolicy = RL_OVERTAKING_RUNTIME_ENABLED
                        ? loadRlPolicy(
                                RL_OVERTAKING_POLICY_PATH,
                                "shared-overtaking",
                                RL_OVERTAKING_OBSERVATION_SIZE,
                                RL_OVERTAKING_ACTION_SIZE)
                        : null;
                if (pendingContinueSave == null) {
                    rogueliteRun.reset(loadingStartingTier);
                }
                if (sandboxMode && !loadingPreserveSandboxConfiguration) {
                    sandboxLoadoutConfiguration.reset(
                            driverProfileCatalog,
                            rogueliteRun
                                    .getPlayerLoadout()
                                    .getDriverProfileId());
                }
                createRoster();
                if (pendingContinueSave != null) {
                    restoreSavedRoster(pendingContinueSave);
                }
                loadCarSprites();
                completeLoadingStage(0.40f, "Loading circuits");
                break;
            case LOADING_MAP_STAGE:
                releaseGameplayMaps();
                mapProgression = createGameplayMapProgression(loadingSandboxMode);
                if (pendingContinueSave != null
                        && !mapProgression.restoreOrder(
                                pendingContinueSave.mapOrder,
                                pendingContinueSave.mapId)) {
                    deleteRogueliteSave();
                    pendingContinueSave = null;
                    rogueliteRun.reset();
                    ownedRogueliteCardTypes = Collections.emptyList();
                    clearSavedRosterProgress();
                }
                completeLoadingStage(0.70f, "Building starting grid");
                break;
            case LOADING_WORLD_STAGE:
                RogueliteSaveData restoredSave = pendingContinueSave;
                roundNumber =
                        restoredSave == null
                                ? 0
                                : Math.max(0, restoredSave.roundNumber - 1);
                playerWins = restoredSave == null ? 0 : restoredSave.playerWins;
                championshipTransitionPending =
                        restoredSave != null
                                && restoredSave.championshipTransitionPending;
                rogueliteRunEnded = restoredSave != null && restoredSave.runEnded;
                playerWonRogueliteRun =
                        restoredSave != null && restoredSave.playerWonRun;
                accumulator = 0f;
                roundOverTimer = 0f;
                effectClock = 0f;
                cameraInitialized = false;
                resize(Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
                resetRound(false);
                if (restoredSave == null) {
                    persistRogueliteRun(RogueliteSaveData.PHASE_RACE);
                } else {
                    roundNumber = restoredSave.roundNumber;
                    restoreSavedRunPhase(restoredSave);
                }
                pendingContinueSave = null;
                completeLoadingStage(0.95f, "Starting engines");
                break;
            case LOADING_AUDIO_STAGE:
                loadRaceSounds();
                completeLoadingStage(1f, "Ready");
                break;
            default:
                return;
        }
        loadingStage++;
    }

    private void completeLoadingStage(float progress, String nextStatus) {
        loadingProgress = MathUtils.clamp(progress, loadingProgress, 1f);
        loadingStatus = nextStatus;
    }

    private void advancePendingStartupLoading() {
        switch (loadingStage) {
            case STARTUP_LOADING_SETTINGS_STAGE:
                loadMenuSettings();
                applyConfiguredDisplayMode();
                refreshContinueAvailability();
                loadMenuMusic();
                completeLoadingStage(0.85f, "Preparing menu");
                break;
            case STARTUP_LOADING_LAYOUT_STAGE:
                resize(Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
                ensureMenuHeroCarLoaded();
                completeLoadingStage(1f, "Ready");
                break;
            default:
                return;
        }
        loadingStage++;
    }

    private MapProgression createGameplayMapProgression(boolean sandbox) {
        Array<ArenaMapCatalogEntry> entries = new Array<ArenaMapCatalogEntry>();
        if (sandbox) {
            ArenaMapCatalogEntry selected = getSelectedSandboxMenuEntry();
            if (selected != null) {
                entries.add(selected);
            }
        } else {
            Array<ArenaMapCatalogEntry> defaultEntries =
                    ArenaMaps.createDefaultCatalog();
            for (int i = 0; i < defaultEntries.size; i++) {
                ArenaMapCatalogEntry entry = defaultEntries.get(i);
                if (!competitionMode.isCustom()
                        || customGameRules.isMapAllowed(entry.getId())) {
                    entries.add(entry);
                }
            }
        }

        if (entries.size == 0) {
            throw new IllegalStateException("No maps are available for gameplay.");
        }

        final LinkedHashMap<String, ArenaMapCatalogEntry> entriesById =
                new LinkedHashMap<String, ArenaMapCatalogEntry>();
        Array<String> mapIds = new Array<String>();
        for (int i = 0; i < entries.size; i++) {
            ArenaMapCatalogEntry entry = entries.get(i);
            entriesById.put(entry.getId(), entry);
            mapIds.add(entry.getId());
        }
        final float progressionMapScale = mapScale;
        return MapProgression.lazy(
                mapIds,
                new MapProgression.MapLoader() {
                    @Override
                    public ArenaMap load(String mapId) {
                        ArenaMapCatalogEntry entry = entriesById.get(mapId);
                        if (entry == null) {
                            throw new IllegalArgumentException("Unknown gameplay map: " + mapId);
                        }
                        return ArenaMaps.loadCatalogMap(entry, progressionMapScale);
                    }
                });
    }

    private void releaseGameplayMaps() {
        if (mapProgression != null) {
            mapProgression.releaseLoadedMaps();
        }
        mapProgression = null;
        currentMap = null;
    }

    private void refreshSandboxMenuMaps() {
        releaseSandboxMenuPreview();
        sandboxMenuMaps.clear();
        try {
            sandboxMenuMaps.addAll(ArenaMaps.createSandboxCatalog());
        } catch (RuntimeException exception) {
            if (Gdx.app != null) {
                Gdx.app.error("RatassGame", "Could not load sandbox map catalog.", exception);
            }
        }
        selectedSandboxMapIndex = clampSandboxMapIndex(selectedSandboxMapIndex);
    }

    private int clampSandboxMapIndex(int index) {
        return clampSandboxMapIndex(index, sandboxMenuMaps.size);
    }

    private int clampSandboxMapIndex(int index, int mapCount) {
        if (mapCount <= 0) {
            return 0;
        }
        return MathUtils.clamp(index, 0, mapCount - 1);
    }

    private ArenaMapCatalogEntry getSelectedSandboxMenuEntry() {
        if (sandboxMenuMaps.size == 0) {
            refreshSandboxMenuMaps();
        }
        if (sandboxMenuMaps.size == 0) {
            return null;
        }
        selectedSandboxMapIndex = clampSandboxMapIndex(selectedSandboxMapIndex);
        return sandboxMenuMaps.get(selectedSandboxMapIndex);
    }

    private ArenaMap getSelectedSandboxMenuMap() {
        ArenaMapCatalogEntry entry = getSelectedSandboxMenuEntry();
        if (entry == null) {
            releaseSandboxMenuPreview();
            return null;
        }
        if (entry.getId().equals(sandboxMenuPreviewMapId)) {
            return sandboxMenuPreviewMap;
        }

        releaseSandboxMenuPreview();
        sandboxMenuPreviewMapId = entry.getId();
        try {
            sandboxMenuPreviewMap = ArenaMaps.loadCatalogMap(entry, mapScale);
        } catch (RuntimeException exception) {
            if (Gdx.app != null) {
                Gdx.app.error(
                        "RatassGame",
                        "Could not load sandbox map preview " + entry.getId() + ".",
                        exception);
            }
        }
        return sandboxMenuPreviewMap;
    }

    private void releaseSandboxMenuPreview() {
        sandboxMenuPreviewMap = null;
        sandboxMenuPreviewMapId = "";
        disposeMapDebugMaskTextures();
    }

    private void changeSandboxMapSelection(int direction) {
        if (sandboxMenuMaps.size == 0) {
            refreshSandboxMenuMaps();
        }
        if (sandboxMenuMaps.size == 0) {
            selectedSandboxMapIndex = 0;
            return;
        }
        releaseSandboxMenuPreview();
        selectedSandboxMapIndex =
                (selectedSandboxMapIndex + direction + sandboxMenuMaps.size) % sandboxMenuMaps.size;
        saveMenuSettings();
    }

    private RlPolicy loadRlEnemyPolicy() {
        rlPolicies.clear();
        RlPolicy legacyPolicy = loadRlPolicy(RL_ENEMY_POLICY_PATH, RL_LEGACY_POLICY_ID);
        RlPolicy firstProfilePolicy = null;
        List<DriverProfileMetadata> driverMetadata =
                new ArrayList<DriverProfileMetadata>();

        for (int i = 0; i < DRIVER_POLICY_IDS.length; i++) {
            String policyId = DRIVER_POLICY_IDS[i];
            RlPolicy policy = loadRlPolicy(buildRlPolicyPath(policyId), policyId);
            if (policy != null) {
                rlPolicies.put(policyId, policy);
                driverMetadata.add(loadDriverProfileMetadata(policyId, i));
                if (firstProfilePolicy == null) {
                    firstProfilePolicy = policy;
                }
            }
        }
        if (!driverMetadata.isEmpty()) {
            driverProfileCatalog = new DriverProfileCatalog(driverMetadata);
            rogueliteRun.configureDriverCatalog(driverProfileCatalog);
        }
        return legacyPolicy == null ? firstProfilePolicy : legacyPolicy;
    }

    private String buildRlPolicyPath(String policyId) {
        return RL_POLICY_DIRECTORY + "/" + policyId + "/" + RL_POLICY_FILE_NAME;
    }

    private String buildDriverMetadataPath(String policyId) {
        return RL_POLICY_DIRECTORY
                + "/"
                + policyId
                + "/"
                + DRIVER_METADATA_FILE_NAME;
    }

    private DriverProfileMetadata loadDriverProfileMetadata(
            String policyId,
            int fallbackOrder) {
        if (Gdx.files != null) {
            try {
                FileHandle metadataFile =
                        Gdx.files.internal(buildDriverMetadataPath(policyId));
                if (metadataFile.exists()) {
                    DriverProfileMetadata.Data data =
                            new Json().fromJson(
                                    DriverProfileMetadata.Data.class,
                                    metadataFile.readString("UTF-8"));
                    DriverProfileMetadata metadata =
                            DriverProfileMetadata.fromData(data, policyId);
                    if (metadata != null) {
                        return metadata;
                    }
                }
            } catch (RuntimeException exception) {
                if (Gdx.app != null) {
                    Gdx.app.error(
                            "RatassGame",
                            "Could not load benchmark metadata for " + policyId + ".",
                            exception);
                }
            }
        }
        return new DriverProfileMetadata(
                policyId,
                "",
                "unrated",
                Math.max(1f, Math.min(99f, 5f + fallbackOrder * 8f)),
                0f,
                0f,
                0f,
                0f,
                0f,
                0f);
    }

    private RlPolicy getRlPolicyById(String policyId) {
        RlPolicy policy = rlPolicies.get(policyId);
        return policy == null ? rlEnemyPolicy : policy;
    }

    private RlPolicy loadRlPolicy(String path, String policyId) {
        return loadRlPolicy(path, policyId, RL_OBSERVATION_SIZE, RL_ACTION_SIZE);
    }

    private RlPolicy loadRlPolicy(
            String path,
            String policyId,
            int expectedObservationSize,
            int expectedActionSize) {
        if (Gdx.files == null) {
            return null;
        }
        try {
            FileHandle policyFile = Gdx.files.internal(path);
            if (!policyFile.exists()) {
                return null;
            }
            RlPolicy policy = RlPolicy.fromJson(policyFile.readString("UTF-8"));
            if (policy.getObservationSize() != expectedObservationSize
                    || policy.getActionSize() != expectedActionSize) {
                Gdx.app.log(
                        "RatassGame",
                        "Ignoring RL policy "
                                + policyId
                                + " with observation/action size "
                                + policy.getObservationSize()
                                + "/"
                                + policy.getActionSize()
                                + "; expected "
                                + expectedObservationSize
                                + "/"
                                + expectedActionSize
                                + ". Retrain the policy for the current observation contract.");
                return null;
            }
            return policy;
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load RL policy " + policyId + " from " + path + ".", exception);
            return null;
        }
    }

    private void loadThemeChoices() {
        themeChoices.clear();
        addFallbackThemeChoices();
        addThemeChoicesFromManifest();
        addThemeChoicesFromDirectory();
        if (themeChoices.size == 0) {
            for (int i = 0; i < FALLBACK_THEME_CHOICES.length; i++) {
                addThemeChoiceIfMissing(FALLBACK_THEME_CHOICES[i]);
            }
        }
    }

    private void addFallbackThemeChoices() {
        for (int i = 0; i < FALLBACK_THEME_CHOICES.length; i++) {
            addThemeChoiceIfUsable(FALLBACK_THEME_CHOICES[i]);
        }
    }

    private void addThemeChoicesFromManifest() {
        if (Gdx.files == null) {
            return;
        }
        FileHandle manifest =
                Gdx.files.internal(THEME_DIRECTORY + "/" + THEME_MANIFEST_PATH);
        if (!manifest.exists()) {
            return;
        }
        try {
            String[] lines = manifest.readString("UTF-8").split("\\r?\\n");
            for (int i = 0; i < lines.length; i++) {
                addThemeChoiceIfUsable(parseThemeChoice(lines[i]));
            }
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load theme manifest " + manifest.path(), exception);
        }
    }

    private void addThemeChoicesFromDirectory() {
        if (Gdx.files == null) {
            return;
        }
        try {
            FileHandle root = Gdx.files.internal(THEME_DIRECTORY);
            if (!root.exists()) {
                return;
            }
            FileHandle[] listedChildren = root.list();
            Array<FileHandle> directories = new Array<FileHandle>(listedChildren.length);
            for (int i = 0; i < listedChildren.length; i++) {
                FileHandle child = listedChildren[i];
                if (child.isDirectory()) {
                    directories.add(child);
                }
            }
            directories.sort(
                    new Comparator<FileHandle>() {
                        @Override
                        public int compare(FileHandle left, FileHandle right) {
                            return left.name().compareTo(right.name());
                        }
                    });
            for (int i = 0; i < directories.size; i++) {
                FileHandle directory = directories.get(i);
                addThemeChoiceIfUsable(
                        new ThemeChoice(directory.name(), buildThemeDisplayName(directory.name())));
            }
        } catch (RuntimeException exception) {
            Gdx.app.debug("RatassGame", "Could not list theme directory for auto-discovery.", exception);
        }
    }

    private ThemeChoice parseThemeChoice(String line) {
        String trimmed = line.trim();
        if (trimmed.length() == 0 || trimmed.startsWith("#")) {
            return null;
        }
        int separator = trimmed.indexOf('|');
        if (separator < 0) {
            separator = trimmed.indexOf('=');
        }
        String name = separator < 0 ? trimmed : trimmed.substring(0, separator).trim();
        if (name.length() == 0) {
            return null;
        }
        String displayName =
                separator < 0 ? "" : trimmed.substring(separator + 1).trim();
        if (displayName.length() == 0) {
            displayName = buildThemeDisplayName(name);
        }
        return new ThemeChoice(name, displayName);
    }

    private void addThemeChoiceIfUsable(ThemeChoice choice) {
        if (choice == null || !themeHasCars(choice.name)) {
            return;
        }
        addThemeChoiceIfMissing(choice);
    }

    private void addThemeChoiceIfMissing(ThemeChoice choice) {
        if (choice == null || choice.name.length() == 0) {
            return;
        }
        if (findThemeChoiceIndex(choice.name) >= 0) {
            return;
        }
        themeChoices.add(choice);
    }

    private boolean themeHasCars(String themeName) {
        return themeAssetExists(themeName, THEME_CAR_SHEET_PATH)
                || themeAssetExists(themeName, THEME_FLAT_CAR_SHEET_PATH)
                || themeHasStandaloneCars(themeName);
    }

    private boolean themeHasStandaloneCars(String themeName) {
        for (int i = 0; i < MAX_CAR_VISUAL_COUNT; i++) {
            if (themeAssetExists(themeName, buildThemeCarFilePath(i))) {
                return true;
            }
        }
        return false;
    }

    private boolean themeAssetExists(String themeName, String relativePath) {
        if (Gdx.files == null || themeName == null || themeName.trim().length() == 0) {
            return false;
        }
        FileHandle handle =
                Gdx.files.internal(THEME_DIRECTORY + "/" + themeName.trim() + "/" + relativePath);
        return handle.exists();
    }

    private void loadMenuSettings() {
        loadThemeChoices();
        configuredThemeName = normalizeThemeName(loadConfiguredThemeName());
        gameLanguage =
                GameLanguage.fromConfiguredValue(
                        loadConfiguredProperty(LANGUAGE_PROPERTY));
        cameraViewMode = CameraViewMode.TOP_DOWN;
        cameraZoom = loadConfiguredFloatProperty(CAMERA_ZOOM_PROPERTY, DEFAULT_CAMERA_ZOOM);
        mapScale = DEFAULT_MAP_SCALE;
        selectedSandboxCarCount = DEFAULT_CAR_COUNT;
        selectedPlayerCarIndex =
                loadConfiguredIntProperty(PLAYER_CAR_PROPERTY, DEFAULT_PLAYER_CAR_INDEX);
        playerName =
                PlayerDisplayName.sanitize(
                        loadConfiguredProperty(PLAYER_NAME_PROPERTY));
        musicVolume =
                loadConfiguredFloatProperty(MUSIC_VOLUME_PROPERTY, DEFAULT_MUSIC_VOLUME);
        soundEffectsVolume =
                loadConfiguredFloatProperty(
                        SOUND_EFFECTS_VOLUME_PROPERTY,
                        DEFAULT_SOUND_EFFECTS_VOLUME);
        windowedMode = loadConfiguredBooleanProperty(DISPLAY_WINDOWED_PROPERTY, false);
        selectedSandboxMapIndex = 0;
        sandboxDebugGuidesVisible = true;

        Preferences preferences = loadPreferences();
        if (preferences != null) {
            configuredThemeName =
                    normalizeThemeName(preferences.getString(THEME_PREF_KEY, configuredThemeName));
            gameLanguage =
                    GameLanguage.fromStoredValue(
                            preferences.getString(
                                    LANGUAGE_PREF_KEY,
                                    gameLanguage.getStoredValue()));
            cameraZoom = preferences.getFloat(CAMERA_ZOOM_PREF_KEY, cameraZoom);
            selectedPlayerCarIndex =
                    preferences.getInteger(PLAYER_CAR_PREF_KEY, selectedPlayerCarIndex);
            playerName =
                    PlayerDisplayName.sanitize(
                            preferences.getString(PLAYER_NAME_PREF_KEY, playerName));
            musicVolume = preferences.getFloat(MUSIC_VOLUME_PREF_KEY, musicVolume);
            soundEffectsVolume =
                    preferences.getFloat(
                            SOUND_EFFECTS_VOLUME_PREF_KEY,
                            soundEffectsVolume);
            windowedMode =
                    preferences.getBoolean(DISPLAY_WINDOWED_PREF_KEY, windowedMode);
            drivingKeyBindings.set(
                    Action.FORWARD,
                    preferences.getInteger(
                            CONTROL_FORWARD_PREF_KEY,
                            drivingKeyBindings.get(Action.FORWARD)));
            drivingKeyBindings.set(
                    Action.BACKWARD,
                    preferences.getInteger(
                            CONTROL_BACKWARD_PREF_KEY,
                            drivingKeyBindings.get(Action.BACKWARD)));
            drivingKeyBindings.set(
                    Action.LEFT,
                    preferences.getInteger(
                            CONTROL_LEFT_PREF_KEY,
                            drivingKeyBindings.get(Action.LEFT)));
            drivingKeyBindings.set(
                    Action.RIGHT,
                    preferences.getInteger(
                            CONTROL_RIGHT_PREF_KEY,
                            drivingKeyBindings.get(Action.RIGHT)));
            selectedSandboxMapIndex =
                    preferences.getInteger(SANDBOX_MAP_PREF_KEY, selectedSandboxMapIndex);
            selectedSandboxCarCount =
                    preferences.getInteger(
                            SANDBOX_CAR_COUNT_PREF_KEY,
                            selectedSandboxCarCount);
            sandboxDebugGuidesVisible =
                    preferences.getBoolean(
                            SANDBOX_DEBUG_GUIDES_PREF_KEY,
                            sandboxDebugGuidesVisible);
        }

        refreshSandboxMenuMaps();
        selectedThemeIndex = findThemeIndex(configuredThemeName);
        configuredThemeName = getCurrentTheme().name;
        cameraZoom = clampCameraZoom(cameraZoom);
        selectedSandboxCarCount = clampCarCount(selectedSandboxCarCount);
        selectedPlayerCarIndex = Math.max(0, selectedPlayerCarIndex);
        musicVolume = clampAudioVolume(musicVolume);
        soundEffectsVolume = clampAudioVolume(soundEffectsVolume);
        selectedSandboxMapIndex = clampSandboxMapIndex(selectedSandboxMapIndex);
    }

    private Preferences loadPreferences() {
        if (Gdx.app == null) {
            return null;
        }
        try {
            return Gdx.app.getPreferences(SETTINGS_PREFS_NAME);
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load game preferences.", exception);
            return null;
        }
    }

    private void saveMenuSettings() {
        Preferences preferences = loadPreferences();
        if (preferences == null) {
            return;
        }

        preferences.putString(THEME_PREF_KEY, configuredThemeName);
        preferences.putString(LANGUAGE_PREF_KEY, gameLanguage.getStoredValue());
        preferences.putFloat(CAMERA_ZOOM_PREF_KEY, cameraZoom);
        preferences.putInteger(PLAYER_CAR_PREF_KEY, selectedPlayerCarIndex);
        preferences.putString(PLAYER_NAME_PREF_KEY, playerName);
        preferences.putFloat(MUSIC_VOLUME_PREF_KEY, musicVolume);
        preferences.putFloat(SOUND_EFFECTS_VOLUME_PREF_KEY, soundEffectsVolume);
        preferences.putBoolean(DISPLAY_WINDOWED_PREF_KEY, windowedMode);
        preferences.putInteger(
                CONTROL_FORWARD_PREF_KEY,
                drivingKeyBindings.get(Action.FORWARD));
        preferences.putInteger(
                CONTROL_BACKWARD_PREF_KEY,
                drivingKeyBindings.get(Action.BACKWARD));
        preferences.putInteger(
                CONTROL_LEFT_PREF_KEY,
                drivingKeyBindings.get(Action.LEFT));
        preferences.putInteger(
                CONTROL_RIGHT_PREF_KEY,
                drivingKeyBindings.get(Action.RIGHT));
        preferences.putInteger(SANDBOX_MAP_PREF_KEY, selectedSandboxMapIndex);
        preferences.putInteger(SANDBOX_CAR_COUNT_PREF_KEY, selectedSandboxCarCount);
        preferences.putBoolean(
                SANDBOX_DEBUG_GUIDES_PREF_KEY,
                sandboxDebugGuidesVisible);
        preferences.flush();
    }

    private void createRoster() {
        roster.clear();
        int playerVisualIndex =
                clampPlayerCarIndex(selectedPlayerCarIndex, getAvailableCarVisualCount());
        CarVisual playerVisual = getCarVisual(playerVisualIndex);
        RlPolicy playerPolicy =
                sandboxMode
                        ? (sandboxLoadoutConfiguration.isAutomatic()
                                ? getSandboxDriverPolicy(0)
                                : null)
                        : getRlPolicyById(
                                rogueliteRun
                                        .getPlayerLoadout()
                                        .getDriverProfileId());
        boolean playerAutopilot = playerPolicy != null;
        addRosterTemplate(
                playerName,
                true,
                new Color(playerVisual.color),
                playerVisual,
                "player",
                false,
                playerAutopilot,
                playerPolicy,
                getCarPerformance(playerVisualIndex).physics);

        int enemyCount = getConfiguredEnemyCount();
        if (!rlTrainingMode && !sandboxMode) {
            List<Integer> rivalVehicleIds = new ArrayList<Integer>(enemyCount);
            for (int vehicleId = 1; vehicleId <= enemyCount; vehicleId++) {
                rivalVehicleIds.add(Integer.valueOf(vehicleId));
            }
            rogueliteRun.assignRivalStrategiesForRace(rivalVehicleIds);
        }
        for (int enemyIndex = 0; enemyIndex < enemyCount; enemyIndex++) {
            int visualIndex = getEnemyCarVisualIndex(enemyIndex);
            CarVisual visual = getCarVisual(visualIndex);
            int vehicleId = roster.size;
            RlPolicy enemyPolicy =
                    sandboxMode
                            ? getSandboxDriverPolicy(vehicleId)
                            : getRlPolicyById(
                                    rogueliteRun
                                            .getRivalLoadout(vehicleId)
                                            .getDriverProfileId());
            boolean modelControlledEnemy = enemyPolicy != null;
            addRosterTemplate(
                    getEnemyName(enemyIndex),
                    false,
                    new Color(visual.color),
                    visual,
                    "rl-" + enemyIndex,
                    !modelControlledEnemy,
                    modelControlledEnemy,
                    enemyPolicy,
                    getCarPerformance(visualIndex).physics);
        }
        invalidateLeaderboard();
    }

    private int getConfiguredEnemyCount() {
        int carCount = sandboxMode ? selectedSandboxCarCount : DEFAULT_CAR_COUNT;
        return Math.max(0, carCount - 1);
    }

    private int getRaceLapsToWin() {
        return competitionMode.isCustom() && !sandboxMode
                ? customGameRules.getLaps()
                : DEFAULT_RACE_LAPS;
    }

    private int getChampionshipsToWin() {
        return RogueliteTournament.CHAMPIONSHIP_COUNT;
    }

    private int getDisplayedRaceLapCount() {
        if (!sandboxMode || roster.size == 0) {
            return getRaceLapsToWin();
        }
        CarTemplate player = roster.first();
        return Math.max(1, player.roundRaceLapTimes.size + 1);
    }

    private String getEnemyName(int enemyIndex) {
        if (enemyIndex >= 0 && enemyIndex < themeEnemyNames.size) {
            return themeEnemyNames.get(enemyIndex);
        }
        if (enemyIndex >= 0 && enemyIndex < DEFAULT_ENEMY_NAMES.length) {
            return DEFAULT_ENEMY_NAMES[enemyIndex];
        }
        return "Rival " + (enemyIndex + 1);
    }

    private int getEnemyCarVisualIndex(int enemyIndex) {
        ensureSessionEnemyVisualIndices(enemyIndex + 1);
        if (enemyIndex >= 0 && enemyIndex < sessionEnemyVisualIndices.size) {
            return sessionEnemyVisualIndices.get(enemyIndex).intValue();
        }
        return enemyIndex + 1;
    }

    private void ensureSessionEnemyVisualIndices(int requiredCount) {
        int carVisualCount = getAvailableCarVisualCount();
        int playerCarIndex = clampPlayerCarIndex(selectedPlayerCarIndex, carVisualCount);
        if (!CarVisualAssignment.remainsValid(
                sessionEnemyVisualPaletteSize,
                sessionEnemyVisualPlayerIndex,
                carVisualCount,
                playerCarIndex)) {
            sessionEnemyVisualPaletteSize = carVisualCount;
            sessionEnemyVisualPlayerIndex = playerCarIndex;
            sessionEnemyVisualIndices.clear();
            sessionEnemyVisualPool.clear();
        }

        while (sessionEnemyVisualIndices.size < requiredCount) {
            if (sessionEnemyVisualPool.size == 0) {
                refillSessionEnemyVisualPool(carVisualCount);
            }
            sessionEnemyVisualIndices.add(sessionEnemyVisualPool.pop());
        }
    }

    private void refillSessionEnemyVisualPool(int carVisualCount) {
        sessionEnemyVisualPool.clear();
        int playerCarIndex = clampPlayerCarIndex(selectedPlayerCarIndex, carVisualCount);
        int[] candidates = CarVisualAssignment.enemyCandidates(carVisualCount, playerCarIndex);
        for (int i = 0; i < candidates.length; i++) {
            sessionEnemyVisualPool.add(Integer.valueOf(candidates[i]));
        }

        for (int i = sessionEnemyVisualPool.size - 1; i > 0; i--) {
            sessionEnemyVisualPool.swap(i, sessionEnemyVisualRandom.nextInt(i + 1));
        }
    }

    private void randomizeRoundDriverPolicies() {
        if (rlTrainingMode) {
            return;
        }
        if (sandboxMode) {
            applySandboxDriverControl();
            return;
        }

        applyRogueliteDriverProfiles();
    }

    private void applyRogueliteDriverProfiles() {
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            RogueliteLoadout loadout =
                    template.playerControlled
                            ? rogueliteRun.getPlayerLoadout()
                            : rogueliteRun.getRivalLoadout(template.vehicleId);
            RlPolicy policy = getRlPolicyById(loadout.getDriverProfileId());
            setTemplateDriverPolicy(template, policy != null, policy);
        }
    }

    private RlPolicy getSandboxDriverPolicy(int vehicleId) {
        return getRlPolicyById(
                sandboxLoadoutConfiguration
                        .getLoadout(vehicleId)
                        .getDriverProfileId());
    }

    private void applySandboxDriverControl() {
        if (!sandboxMode) {
            return;
        }
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            RlPolicy policy = getSandboxDriverPolicy(template.vehicleId);
            boolean modelControlled =
                    policy != null
                            && (!template.playerControlled
                                    || sandboxLoadoutConfiguration.isAutomatic());
            setTemplateDriverPolicy(
                    template,
                    modelControlled,
                    modelControlled ? policy : null);
        }
    }

    private void applySandboxConfigurationToCar(int vehicleId) {
        if (!sandboxMode) {
            return;
        }
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            if (template.vehicleId != vehicleId) {
                continue;
            }
            RlPolicy policy = getSandboxDriverPolicy(vehicleId);
            boolean modelControlled =
                    policy != null
                            && (!template.playerControlled
                                    || sandboxLoadoutConfiguration.isAutomatic());
            setTemplateDriverPolicy(
                    template,
                    modelControlled,
                    modelControlled ? policy : null);
            if (template.currentCar != null) {
                template.currentCar.configureRogueliteCards(
                        sandboxLoadoutConfiguration.getLoadout(vehicleId),
                        isPresentationEnabled());
            }
            return;
        }
    }

    private void applySandboxConfigurationToCars() {
        if (!sandboxMode) {
            return;
        }
        applySandboxDriverControl();
        for (int i = 0; i < cars.size; i++) {
            Car car = cars.get(i);
            car.configureRogueliteCards(
                    sandboxLoadoutConfiguration.getLoadout(car.template.vehicleId),
                    isPresentationEnabled());
        }
    }

    private void setTemplateDriverPolicy(
            CarTemplate template,
            boolean modelControlled,
            RlPolicy policy) {
        template.modelControlled = modelControlled;
        template.rlPolicy = policy;
        if (template.currentCar != null) {
            template.currentCar.modelControlled = modelControlled;
        }
    }

