    private CarVisual getCarVisual(int rosterIndex) {
        if (themeCarVisuals.size > 0) {
            int carVisualCount = Math.min(themeCarVisuals.size, MAX_CAR_VISUAL_COUNT);
            return themeCarVisuals.get(rosterIndex % carVisualCount);
        }
        return NORMAL_CAR_VISUALS[rosterIndex % NORMAL_CAR_VISUALS.length];
    }

    private CarVisual getPlayerCarVisual() {
        return getCarVisual(selectedPlayerCarIndex);
    }

    private CarPerformance getCarPerformance(int visualIndex) {
        ensureThemeCarPerformancesLoaded();
        int index = visualIndex % DEFAULT_CAR_PERFORMANCES.length;
        if (index < 0) {
            index += DEFAULT_CAR_PERFORMANCES.length;
        }
        CarPerformance performance = themeCarPerformances[index];
        return performance == null ? DEFAULT_CAR_PERFORMANCES[index] : performance;
    }

    public static int getCarPerformanceCount() {
        return DEFAULT_CAR_PERFORMANCES.length;
    }

    private void ensureThemeCarPerformancesLoaded() {
        if (Gdx.files == null || configuredThemeName.equals(carPerformanceThemeName)) {
            return;
        }

        for (int i = 0; i < themeCarPerformances.length; i++) {
            themeCarPerformances[i] = loadThemeCarPerformance(i, DEFAULT_CAR_PERFORMANCES[i]);
        }
        carPerformanceThemeName = configuredThemeName;
    }

    private CarPerformance loadThemeCarPerformance(int index, CarPerformance fallback) {
        String fileName = TextFormat.twoDigits(index) + ".properties";
        FileHandle handle = resolveThemeCarPerformanceHandle(fileName);
        if (handle == null || !handle.exists()) {
            return fallback;
        }

        try {
            Map<String, String> properties = new LinkedHashMap<String, String>();
            parseProperties(properties, handle.readString("UTF-8"));
            return new CarPerformance(
                    readNonBlankString(properties, "name", fallback.name),
                    readNonNegativeInt(properties, "horsepower", fallback.horsePower),
                    readPositiveInt(properties, "weight.kg", fallback.weightKg),
                    readPositiveInt(properties, "top.speed.kph", fallback.topSpeedKph),
                    readNonNegativeFloat(properties, "brake.force", fallback.brakeForce),
                    readNonNegativeFloat(
                            properties, "steering.torque", fallback.steeringTorque),
                    readNonNegativeFloat(properties, "wheel.grip", fallback.wheelGrip),
                    readNonNegativeFloat(properties, "aero.drag", fallback.aeroDrag));
        } catch (RuntimeException exception) {
            if (Gdx.app != null) {
                Gdx.app.error(
                        "RatassGame",
                        "Could not load car performance from " + handle.path(),
                        exception);
            }
            return fallback;
        }
    }

    private FileHandle resolveThemeCarPerformanceHandle(String fileName) {
        String relativePath = THEME_CAR_DIRECTORY_PATH + "/" + fileName;
        FileHandle localOverride =
                Gdx.files.local("assets/" + buildThemeAssetPath(relativePath));
        if (localOverride != null && localOverride.exists()) {
            return localOverride;
        }
        return resolveThemedAssetHandle(relativePath);
    }

    private static int readPositiveInt(
            Map<String, String> properties, String key, int fallback) {
        int value = readInt(properties, key, fallback);
        return value > 0 ? value : fallback;
    }

    private static String readNonBlankString(
            Map<String, String> properties, String key, String fallback) {
        String value = properties.get(key);
        if (value == null || value.trim().length() == 0) {
            return fallback;
        }
        return value.trim();
    }

    private static int readNonNegativeInt(
            Map<String, String> properties, String key, int fallback) {
        int value = readInt(properties, key, fallback);
        return value >= 0 ? value : fallback;
    }

    private static int readInt(Map<String, String> properties, String key, int fallback) {
        String value = properties.get(key);
        if (value == null) {
            return fallback;
        }
        try {
            return Integer.parseInt(value.trim());
        } catch (NumberFormatException exception) {
            return fallback;
        }
    }

    private static float readNonNegativeFloat(
            Map<String, String> properties, String key, float fallback) {
        String value = properties.get(key);
        if (value == null) {
            return fallback;
        }
        try {
            float parsed = Float.parseFloat(value.trim());
            return parsed >= 0f && !Float.isInfinite(parsed) && !Float.isNaN(parsed)
                    ? parsed
                    : fallback;
        } catch (NumberFormatException exception) {
            return fallback;
        }
    }

    private int getAvailableCarVisualCount() {
        return themeCarVisuals.size > 0
                ? Math.min(themeCarVisuals.size, MAX_CAR_VISUAL_COUNT)
                : NORMAL_CAR_VISUALS.length;
    }

    private void disposeRosterSpriteTextures() {
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            if (template.ownsSpriteTexture) {
                disposeTexture(template.spriteTexture);
            }
            template.spriteTexture = null;
            template.ownsSpriteTexture = false;
        }
    }

    private void loadCarSprites() {
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            if (template.ownsSpriteTexture) {
                disposeTexture(template.spriteTexture);
            }
            template.spriteTexture = null;
            template.ownsSpriteTexture = false;
            template.spriteSourceX = 0;
            template.spriteSourceY = 0;
            template.spriteSourceWidth = 0;
            template.spriteSourceHeight = 0;

            if (template.visual == null) {
                continue;
            }

            if (template.visual.sharedTexture) {
                template.spriteTexture = themeCarsTexture;
            } else {
                template.spriteTexture = loadTexture(template.visual.spritePath);
                template.ownsSpriteTexture = template.spriteTexture != null;
            }

            if (template.spriteTexture == null) {
                continue;
            }

            if (template.visual.hasSourceRegion()) {
                template.spriteSourceX = template.visual.spriteSourceX;
                template.spriteSourceY = template.visual.spriteSourceY;
                template.spriteSourceWidth = template.visual.spriteSourceWidth;
                template.spriteSourceHeight = template.visual.spriteSourceHeight;
            } else {
                template.spriteSourceWidth = template.spriteTexture.getWidth();
                template.spriteSourceHeight = template.spriteTexture.getHeight();
            }
        }
    }

    private void loadRaceSounds() {
        disposeRaceSounds();
        impactSound = loadSound("audio/impact.wav");
        pickupSound = loadSound("audio/pickup.wav");
        destructionSound = loadSound("audio/destroy.wav");
        revengeSound = loadSound("audio/revenge_bell.wav");
        countdownSound = loadSound("audio/countdown.wav");
        roundStartSound = loadSound("audio/start.wav");
        engineSound = loadSound("audio/engine.wav");
        slipSound = loadSound("audio/slip.wav");
        circuitMusic = loadMusic("audio/music.ogg");
        victoryMusic = loadMusic("audio/victory_music.ogg");
        defeatMusic = loadMusic("audio/defeat_music.ogg");
        applyMusicVolume();
    }

    private void disposeGameSounds() {
        disposeMenuMusic();
        disposeRaceSounds();
    }

    private void disposeMenuMusic() {
        disposeMusic(menuMusic);
        menuMusic = null;
        menuMusicThemeName = "";
    }

    private void disposeRaceSounds() {
        stopVehicleSounds();
        disposeMusic(circuitMusic);
        disposeMusic(victoryMusic);
        disposeMusic(defeatMusic);
        disposeSound(impactSound);
        disposeSound(pickupSound);
        disposeSound(destructionSound);
        disposeSound(revengeSound);
        disposeSound(countdownSound);
        disposeSound(roundStartSound);
        disposeSound(engineSound);
        disposeSound(slipSound);
        circuitMusic = null;
        victoryMusic = null;
        defeatMusic = null;
        impactSound = null;
        pickupSound = null;
        destructionSound = null;
        revengeSound = null;
        countdownSound = null;
        roundStartSound = null;
        engineSound = null;
        slipSound = null;
    }

    private void loadMenuMusic() {
        if (!isPresentationEnabled()) {
            return;
        }
        if (menuMusic == null || !configuredThemeName.equals(menuMusicThemeName)) {
            disposeMenuMusic();
            menuMusic = loadMusic(MENU_MUSIC_PATH);
            menuMusicThemeName = configuredThemeName;
        }
        playMenuMusic();
    }

    private void playMenuMusic() {
        if (!isPresentationEnabled() || menuMusic == null) {
            return;
        }
        stopCircuitMusic();
        stopOutcomeMusic();
        menuMusic.setLooping(true);
        applyMusicVolume();
        if (!menuMusic.isPlaying()) {
            menuMusic.play();
        }
    }

    private void playCircuitMusic() {
        if (!isPresentationEnabled() || circuitMusic == null) {
            return;
        }
        if (menuMusic != null) {
            menuMusic.stop();
        }
        stopOutcomeMusic();
        circuitMusic.setLooping(true);
        applyMusicVolume();
        if (!circuitMusic.isPlaying()) {
            circuitMusic.play();
        }
    }

    private void stopCircuitMusic() {
        if (circuitMusic != null) {
            circuitMusic.stop();
        }
    }

    private void stopOutcomeMusic() {
        if (victoryMusic != null) {
            victoryMusic.stop();
        }
        if (defeatMusic != null) {
            defeatMusic.stop();
        }
    }

    private void stopAllMusic() {
        if (menuMusic != null) {
            menuMusic.stop();
        }
        stopCircuitMusic();
        stopOutcomeMusic();
    }

    private void applyMusicVolume() {
        if (menuMusic != null) {
            menuMusic.setVolume(THEME_MUSIC_BASE_VOLUME * musicVolume);
        }
        if (circuitMusic != null) {
            circuitMusic.setVolume(THEME_MUSIC_BASE_VOLUME * musicVolume);
        }
        if (victoryMusic != null) {
            victoryMusic.setVolume(THEME_MUSIC_BASE_VOLUME * musicVolume);
        }
        if (defeatMusic != null) {
            defeatMusic.setVolume(THEME_MUSIC_BASE_VOLUME * musicVolume);
        }
    }

    private Sound loadSound(String path) {
        FileHandle handle = resolveAssetHandle(path);
        if (handle == null || !handle.exists()) {
            return null;
        }
        try {
            return Gdx.audio.newSound(handle);
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load sound " + handle.path(), exception);
            return null;
        }
    }

    private Music loadMusic(String path) {
        FileHandle handle = resolveAssetHandle(path);
        if (handle == null || !handle.exists()) {
            return null;
        }
        try {
            return Gdx.audio.newMusic(handle);
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load music " + handle.path(), exception);
            return null;
        }
    }

    private void loadThemeEnemyNames() {
        themeEnemyNames.clear();
        FileHandle handle = resolveThemedAssetHandle(THEME_ENEMY_NAMES_PATH);
        if (handle == null || !handle.exists()) {
            return;
        }

        try {
            String[] lines = handle.readString("UTF-8").split("\\r?\\n");
            for (int i = 0; i < lines.length; i++) {
                String name = lines[i].trim();
                if (name.length() == 0 || name.startsWith("#")) {
                    continue;
                }
                themeEnemyNames.add(PlayerDisplayName.sanitize(name));
                if (themeEnemyNames.size >= MAX_CAR_COUNT) {
                    break;
                }
            }
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load enemy names from " + handle.path(), exception);
            themeEnemyNames.clear();
        }
    }

    private void loadThemeTextures() {
        disposeTexture(themeCarsTexture);
        themeCarsTexture = null;
        themeCarVisuals.clear();

        if (loadStandaloneThemeCarVisuals()) {
            return;
        }

        FileHandle carSheetHandle = resolveThemeCarSheetHandle();
        if (carSheetHandle == null || !carSheetHandle.exists()) {
            return;
        }

        Pixmap source = null;
        try {
            source = new Pixmap(carSheetHandle);
            themeCarsTexture = new Texture(carSheetHandle);
            themeCarsTexture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
            themeCarVisuals.addAll(createThemeCarVisualsFromFixedGrid(source));
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load themed car sheet " + carSheetHandle.path(), exception);
            themeCarVisuals.clear();
            disposeTexture(themeCarsTexture);
            themeCarsTexture = null;
        } finally {
            if (source != null) {
                source.dispose();
            }
        }
    }

    private boolean loadStandaloneThemeCarVisuals() {
        Array<FileHandle> carHandles = resolveStandaloneThemeCarHandles();
        if (carHandles.size == 0) {
            return false;
        }

        for (int i = 0; i < carHandles.size; i++) {
            FileHandle handle = carHandles.get(i);
            Pixmap source = null;
            try {
                source = new Pixmap(handle);
                themeCarVisuals.add(
                        new CarVisual(
                                THEME_CAR_DIRECTORY_PATH + "/" + handle.name(),
                                sampleSpriteColor(
                                        source,
                                        new Rectangle(
                                                0f,
                                                0f,
                                                source.getWidth(),
                                                source.getHeight()))));
            } catch (RuntimeException exception) {
                Gdx.app.error("RatassGame", "Could not load themed car " + handle.path(), exception);
            } finally {
                if (source != null) {
                    source.dispose();
                }
            }
        }
        return themeCarVisuals.size > 0;
    }

    private void ensureMenuCarPreviewLoaded() {
        if (configuredThemeName.equals(menuCarSheetThemeName)) {
            return;
        }

        disposeMenuCarPreview();
        menuCarSheetThemeName = configuredThemeName;

        if (loadStandaloneMenuCarPreview()) {
            return;
        }

        FileHandle carSheetHandle = resolveThemeCarSheetHandle();
        if (carSheetHandle == null || !carSheetHandle.exists()) {
            return;
        }

        try {
            menuCarSheetTexture = new Texture(carSheetHandle);
            menuCarSheetTexture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
            addThemeCarGridBounds(
                    menuCarSheetTexture.getWidth(),
                    menuCarSheetTexture.getHeight(),
                    menuCarSheetSourceBounds);
            clampSelectedPlayerCarToMenuPreview();
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load menu car sheet " + carSheetHandle.path(), exception);
            disposeTexture(menuCarSheetTexture);
            menuCarSheetTexture = null;
            menuCarSheetSourceBounds.clear();
        }
    }

    private boolean loadStandaloneMenuCarPreview() {
        Array<FileHandle> carHandles = resolveStandaloneThemeCarHandles();
        if (carHandles.size == 0) {
            return false;
        }

        int columnCount = Math.min(STANDALONE_CAR_PREVIEW_COLUMNS, carHandles.size);
        int rowCount = MathUtils.ceil(carHandles.size / (float) columnCount);
        Pixmap sheet = new Pixmap(
                columnCount * STANDALONE_CAR_PREVIEW_CELL_WIDTH,
                rowCount * STANDALONE_CAR_PREVIEW_CELL_HEIGHT,
                Pixmap.Format.RGBA8888);
        sheet.setColor(0f, 0f, 0f, 0f);
        sheet.fill();

        try {
            for (int i = 0; i < carHandles.size; i++) {
                FileHandle handle = carHandles.get(i);
                Pixmap car = null;
                try {
                    car = new Pixmap(handle);
                    int column = i % columnCount;
                    int row = i / columnCount;
                    sheet.drawPixmap(
                            car,
                            0,
                            0,
                            car.getWidth(),
                            car.getHeight(),
                            column * STANDALONE_CAR_PREVIEW_CELL_WIDTH,
                            row * STANDALONE_CAR_PREVIEW_CELL_HEIGHT,
                            STANDALONE_CAR_PREVIEW_CELL_WIDTH,
                            STANDALONE_CAR_PREVIEW_CELL_HEIGHT);
                    menuCarSheetSourceBounds.add(new Rectangle(
                            column * STANDALONE_CAR_PREVIEW_CELL_WIDTH,
                            row * STANDALONE_CAR_PREVIEW_CELL_HEIGHT,
                            STANDALONE_CAR_PREVIEW_CELL_WIDTH,
                            STANDALONE_CAR_PREVIEW_CELL_HEIGHT));
                } catch (RuntimeException exception) {
                    Gdx.app.error("RatassGame", "Could not load menu car " + handle.path(), exception);
                } finally {
                    if (car != null) {
                        car.dispose();
                    }
                }
            }

            if (menuCarSheetSourceBounds.size == 0) {
                return false;
            }
            menuCarSheetTexture = new Texture(sheet);
            menuCarSheetTexture.setFilter(Texture.TextureFilter.Linear, Texture.TextureFilter.Linear);
            clampSelectedPlayerCarToMenuPreview();
            return true;
        } finally {
            sheet.dispose();
        }
    }

    private void disposeMenuCarPreview() {
        disposeTexture(menuCarSheetTexture);
        menuCarSheetTexture = null;
        menuCarSheetThemeName = "";
        menuCarSheetSourceBounds.clear();
    }

    private void clampSelectedPlayerCarToMenuPreview() {
        int carCount = getMenuSelectableCarCount();
        int clampedPlayerCarIndex = clampPlayerCarIndex(selectedPlayerCarIndex, carCount);
        if (clampedPlayerCarIndex != selectedPlayerCarIndex) {
            selectedPlayerCarIndex = clampedPlayerCarIndex;
            saveMenuSettings();
        }
    }

    private int getMenuSelectableCarCount() {
        if (menuCarSheetSourceBounds.size > 0) {
            return menuCarSheetSourceBounds.size;
        }
        return getAvailableCarVisualCount();
    }

    private float getMenuCarSheetAspect() {
        if (menuCarSheetTexture != null && menuCarSheetTexture.getHeight() > 0) {
            return menuCarSheetTexture.getWidth() / (float) menuCarSheetTexture.getHeight();
        }
        return MENU_CAR_SHEET_ASPECT;
    }

    private Array<CarVisual> createThemeCarVisualsFromFixedGrid(Pixmap source) {
        Array<CarVisual> visuals = new Array<CarVisual>();
        for (int i = 0; i < MAX_CAR_VISUAL_COUNT; i++) {
            Rectangle sourceBounds = getThemeCarCellBounds(i, source.getWidth(), source.getHeight());
            visuals.add(
                    new CarVisual(
                            null,
                            Math.round(sourceBounds.x),
                            Math.round(sourceBounds.y),
                            Math.round(sourceBounds.width),
                            Math.round(sourceBounds.height),
                            true,
                            CAR_SPRITE_ROTATION_OFFSET_DEG,
                            sampleSpriteColor(source, sourceBounds)));
        }
        return visuals;
    }

    private void addThemeCarGridBounds(
            int sheetWidth, int sheetHeight, Array<Rectangle> targetBounds) {
        for (int i = 0; i < MAX_CAR_VISUAL_COUNT; i++) {
            targetBounds.add(getThemeCarCellBounds(i, sheetWidth, sheetHeight));
        }
    }

    private Rectangle getThemeCarCellBounds(int index, int sheetWidth, int sheetHeight) {
        int column = index % THEME_CAR_COLUMNS;
        int row = index / THEME_CAR_COLUMNS;
        int x0 = Math.round(column * sheetWidth / (float) THEME_CAR_COLUMNS);
        int x1 = Math.round((column + 1) * sheetWidth / (float) THEME_CAR_COLUMNS);
        int y0 = Math.round(row * sheetHeight / (float) THEME_CAR_SHEET_ROWS);
        int y1 = Math.round((row + 1) * sheetHeight / (float) THEME_CAR_SHEET_ROWS);
        return new Rectangle(x0, y0, x1 - x0, y1 - y0);
    }

    private Texture loadTexture(String path) {
        FileHandle handle = resolveAssetHandle(path);
        if (handle == null || !handle.exists()) {
            return null;
        }
        try {
            Texture texture = new Texture(handle);
            texture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
            return texture;
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load texture " + handle.path(), exception);
            return null;
        }
    }

    private String buildThemeAssetPath(String relativePath) {
        return THEME_DIRECTORY + "/" + configuredThemeName + "/" + relativePath;
    }

    private String buildThemeCarFilePath(int index) {
        return THEME_CAR_DIRECTORY_PATH + "/" + TextFormat.twoDigits(index) + ".png";
    }

    private Array<FileHandle> resolveStandaloneThemeCarHandles() {
        Array<FileHandle> handles = new Array<FileHandle>();
        for (int i = 0; i < MAX_CAR_VISUAL_COUNT; i++) {
            FileHandle handle = resolveThemedAssetHandle(buildThemeCarFilePath(i));
            if (handle != null && handle.exists()) {
                handles.add(handle);
            }
        }
        return handles;
    }

    private FileHandle resolveThemeCarSheetHandle() {
        FileHandle nested = resolveThemedAssetHandle(THEME_CAR_SHEET_PATH);
        if (nested != null) {
            return nested;
        }
        return resolveThemedAssetHandle(THEME_FLAT_CAR_SHEET_PATH);
    }

    private FileHandle resolveThemedAssetHandle(String relativePath) {
        FileHandle handle = Gdx.files.internal(buildThemeAssetPath(relativePath));
        return handle.exists() ? handle : null;
    }

    private FileHandle resolveAssetHandle(String relativePath) {
        FileHandle themed = resolveThemedAssetHandle(relativePath);
        if (themed != null) {
            return themed;
        }
        if (!DEFAULT_THEME_NAME.equals(configuredThemeName)) {
            FileHandle defaultThemed =
                    Gdx.files.internal(THEME_DIRECTORY + "/" + DEFAULT_THEME_NAME + "/" + relativePath);
            if (defaultThemed.exists()) {
                return defaultThemed;
            }
        }
        FileHandle fallback = Gdx.files.internal(relativePath);
        return fallback.exists() ? fallback : null;
    }

    private Color sampleSpriteColor(Pixmap masked, Rectangle bounds) {
        long red = 0L;
        long green = 0L;
        long blue = 0L;
        long samples = 0L;

        int minX = Math.round(bounds.x);
        int minY = Math.round(bounds.y);
        int maxX = minX + Math.round(bounds.width) - 1;
        int maxY = minY + Math.round(bounds.height) - 1;
        for (int y = minY; y <= maxY; y++) {
            for (int x = minX; x <= maxX; x++) {
                int pixel = masked.getPixel(x, y);
                int alpha = pixel & 0xff;
                if (alpha < 64) {
                    continue;
                }
                red += (pixel >>> 24) & 0xff;
                green += (pixel >>> 16) & 0xff;
                blue += (pixel >>> 8) & 0xff;
                samples++;
            }
        }

        if (samples == 0L) {
            return new Color(0.82f, 0.82f, 0.82f, 1f);
        }

        float divisor = 255f * (float) samples;
        return new Color(red / divisor, green / divisor, blue / divisor, 1f);
    }

    private int calculateSidebarWidth(int width) {
        float preferred = MathUtils.clamp(
                width * HUD_SIDEBAR_RATIO,
                HUD_SIDEBAR_PREFERRED_MIN_WIDTH,
                HUD_SIDEBAR_MAX_WIDTH);
        float sidebarWidth = Math.min(preferred, width - HUD_MIN_PLAYFIELD_WIDTH);
        if (sidebarWidth < HUD_SIDEBAR_MIN_WIDTH) {
            sidebarWidth = Math.min(HUD_SIDEBAR_MIN_WIDTH, width * 0.32f);
        }
        return Math.max(0, Math.round(MathUtils.clamp(sidebarWidth, 0f, HUD_SIDEBAR_MAX_WIDTH)));
    }

    private void updateAudioState(float delta) {
        impactSoundCooldown = Math.max(0f, impactSoundCooldown - delta);
        destructionSoundCooldown = Math.max(0f, destructionSoundCooldown - delta);

        if (roundOver) {
            return;
        }

        if (preRoundCountdownTimer > 0f) {
            int countdownSecond = MathUtils.ceil(preRoundCountdownTimer);
            if (countdownSecond < countdownCueSecond) {
                playSound(countdownSound, countdownSecond == 1 ? 0.62f : 0.48f);
                countdownCueSecond = countdownSecond;
            }
            return;
        }

        if (!roundStartSoundPlayed) {
            playSound(roundStartSound, 0.78f);
            roundStartSoundPlayed = true;
        }
    }

    private void playImpactSound(float impactStrength) {
        if (!isPresentationEnabled()) {
            return;
        }
        if (impactSoundCooldown > 0f) {
            return;
        }

        float normalizedStrength = MathUtils.clamp(
                (impactStrength - Car.MIN_COLLISION_RESPONSE_IMPULSE) / 24f,
                0f,
                1f);
        float volume = MathUtils.lerp(0.18f, 0.86f, normalizedStrength);
        float pitch = MathUtils.lerp(1.08f, 0.82f, normalizedStrength);
        float adjustedVolume = volume * soundEffectsVolume;
        if (impactSound != null && adjustedVolume > 0f) {
            impactSound.play(adjustedVolume, pitch, 0f);
        }
        impactSoundCooldown = IMPACT_SOUND_COOLDOWN;
    }

    private void updateVehicleSounds(float delta) {
        if (rlTrainingMode
                || gameMode != GameMode.PLAYING
                || isInGameMenuOpen()
                || soundEffectsVolume <= 0f) {
            stopVehicleSounds();
            return;
        }

        Car audibleCar = getCameraTargetCar();
        if (!isCameraFollowable(audibleCar)) {
            stopVehicleSounds();
            return;
        }

        float speed = audibleCar.body.getLinearVelocity().len();
        if (!StableCarMotion.isFinite(speed)) {
            stopVehicleSounds();
            return;
        }
        float speedRatio = MathUtils.clamp(
                speed / Math.max(0.001f, audibleCar.getBaseForwardMaxSpeed()),
                0f,
                1f);
        float throttle = StableCarMotion.isFinite(audibleCar.lastThrottleCommand)
                ? MathUtils.clamp(Math.abs(audibleCar.lastThrottleCommand), 0f, 1f)
                : 0f;
        float revRatio = MathUtils.clamp(speedRatio * 0.78f + throttle * 0.22f, 0f, 1f);
        float targetPitch = MathUtils.lerp(ENGINE_SOUND_IDLE_PITCH, ENGINE_SOUND_MAX_PITCH, revRatio);
        float targetVolume = MathUtils.lerp(
                ENGINE_SOUND_IDLE_VOLUME,
                ENGINE_SOUND_MAX_VOLUME,
                Math.max(speedRatio, throttle * 0.72f));
        float response = 1f - (float) Math.exp(-ENGINE_SOUND_RESPONSE * Math.max(0f, delta));
        if (!StableCarMotion.isFinite(engineSoundPitch)) {
            engineSoundPitch = ENGINE_SOUND_IDLE_PITCH;
        }
        if (!StableCarMotion.isFinite(engineSoundVolume)) {
            engineSoundVolume = ENGINE_SOUND_IDLE_VOLUME;
        }
        engineSoundPitch = MathUtils.lerp(engineSoundPitch, targetPitch, response);
        engineSoundVolume = MathUtils.lerp(engineSoundVolume, targetVolume, response);

        if (engineSound != null) {
            float adjustedEngineVolume = engineSoundVolume * soundEffectsVolume;
            if (engineSoundId < 0L) {
                engineSoundId = engineSound.loop(adjustedEngineVolume, engineSoundPitch, 0f);
            } else {
                engineSound.setVolume(engineSoundId, adjustedEngineVolume);
                engineSound.setPitch(engineSoundId, engineSoundPitch);
            }
        }

        float slip = audibleCar.getLateralSlipSignal();
        float slipThreshold = slipSoundId >= 0L
                ? SLIP_SOUND_STOP_THRESHOLD
                : SLIP_SOUND_START_THRESHOLD;
        if (speedRatio < SLIP_SOUND_MIN_SPEED_RATIO || slip < slipThreshold) {
            stopSlipSound();
            return;
        }

        float slipSeverity = MathUtils.clamp(
                (slip - SLIP_SOUND_STOP_THRESHOLD) / (0.75f - SLIP_SOUND_STOP_THRESHOLD),
                0f,
                1f);
        float slipVolume = MathUtils.lerp(0.12f, SLIP_SOUND_MAX_VOLUME, slipSeverity);
        float slipPitch = MathUtils.lerp(0.88f, 1.12f, slipSeverity);
        if (slipSound != null) {
            float adjustedSlipVolume = slipVolume * soundEffectsVolume;
            if (slipSoundId < 0L) {
                slipSoundId = slipSound.loop(adjustedSlipVolume, slipPitch, 0f);
            } else {
                slipSound.setVolume(slipSoundId, adjustedSlipVolume);
                slipSound.setPitch(slipSoundId, slipPitch);
            }
        }
    }

    private void stopVehicleSounds() {
        if (engineSound != null && engineSoundId >= 0L) {
            engineSound.stop(engineSoundId);
        }
        engineSoundId = -1L;
        engineSoundPitch = ENGINE_SOUND_IDLE_PITCH;
        engineSoundVolume = 0f;
        stopSlipSound();
    }

    private void stopSlipSound() {
        if (slipSound != null && slipSoundId >= 0L) {
            slipSound.stop(slipSoundId);
        }
        slipSoundId = -1L;
    }

    private void playDestructionSound(float volume) {
        if (destructionSoundCooldown > 0f) {
            return;
        }

        playSound(destructionSound, volume);
        destructionSoundCooldown = DESTRUCTION_SOUND_COOLDOWN;
    }

    private void updatePresentationState(float delta) {
        if (!isPresentationEnabled()) {
            return;
        }
        freeCameraReturnHintTimer =
                Math.max(0f, freeCameraReturnHintTimer - Math.max(0f, delta));
        if (raceIncidentPopup != null) {
            raceIncidentPopup.update(delta);
            updateEventCamera(delta);
        }
        for (int i = 0; i < cars.size; i++) {
            Car car = cars.get(i);
            car.updateAbilityPresentation(delta);
            playRevengeActivationSound(car);
        }
        for (int i = 0; i < mirrorCars.size; i++) {
            mirrorCars.get(i).updateAbilityPresentation(delta);
        }
    }

    private void playRevengeActivationSound(Car car) {
        if (isPresentationEnabled()
                && car != null
                && car.consumeRevengeActivationSound()) {
            playSound(revengeSound, 1f);
        }
    }

    private void updateEventCamera(float delta) {
        if (!eventCameraSelected
                || raceIncidentPopup == null
                || eventCameraDirector == null
                || gameMode != GameMode.PLAYING
                || roundOver
                || isFinishWinnerCameraActive()) {
            return;
        }

        boolean wasLocked = eventCameraDirector.isLocked();
        eventCameraDirector.update(delta);
        for (int i = 0; i < cars.size; i++) {
            Car car = cars.get(i);
            if (car.template == null) {
                continue;
            }
            eventCameraDirector.observeRevengeArmed(
                    car.template.vehicleId,
                    car.active
                            && car.effectiveRogueliteUpgrades().isRevengeArmed());
        }

        int requestedVehicleId = eventCameraDirector.consumeRequestedVehicleId();
        if (requestedVehicleId >= 0) {
            setCameraTargetTemplate(
                    findTemplateByVehicleId(requestedVehicleId),
                    true);
        }
        if (wasLocked || eventCameraDirector.isLocked()) {
            if (raceIncidentPopup.isVisible()) {
                long displaySequence = raceIncidentPopup.getDisplaySequence();
                if (displaySequence != lastAutoFollowedRaceIncidentSequence) {
                    lastAutoFollowedRaceIncidentSequence = displaySequence;
                    eventCameraDirector.observeIncident();
                }
            }
        }
        if (eventCameraDirector.isLocked()) {
            return;
        }
        if (raceIncidentPopup.isVisible()) {
            long displaySequence = raceIncidentPopup.getDisplaySequence();
            if (displaySequence != lastAutoFollowedRaceIncidentSequence) {
                lastAutoFollowedRaceIncidentSequence = displaySequence;
                eventCameraDirector.observeIncident(
                        raceIncidentPopup.getPrimaryVehicleId());
                return;
            }
        }
        if (eventCameraDirector.consumePlayerFallbackRequested()) {
            resetCameraTargetToPlayer(true);
        }
    }

    private void resetWeatherForCircuit() {
        currentWeather = chooseWeatherFromSunny();
        weatherGripMultiplier = currentWeather.gripMultiplier;
        weatherTimeRemaining = randomWeatherDuration(currentWeather);
    }

    private void forceSunnyWeather() {
        currentWeather = Weather.SUNNY;
        weatherGripMultiplier = Weather.SUNNY.gripMultiplier;
        weatherTimeRemaining = Float.POSITIVE_INFINITY;
    }

    private void updateWeather(float delta) {
        if (rlTrainingMode) {
            forceSunnyWeather();
            return;
        }

        float response =
                1f
                        - (float)
                                Math.exp(
                                        -WEATHER_GRIP_TRANSITION_SPEED
                                                * Math.max(0f, delta));
        weatherGripMultiplier =
                MathUtils.lerp(
                        weatherGripMultiplier,
                        currentWeather.gripMultiplier,
                        MathUtils.clamp(response, 0f, 1f));

        if (sandboxMode || roundOver || preRoundCountdownTimer > 0f) {
            return;
        }

        weatherTimeRemaining -= Math.max(0f, delta);
        if (weatherTimeRemaining > 0f) {
            return;
        }
        setWeather(chooseNextWeather());
    }

    private Weather chooseNextWeather() {
        if (competitionMode.isCustom()) {
            if (currentWeather != Weather.SUNNY
                    && customGameRules.isWeatherAllowed(WeatherType.SUNNY)) {
                return Weather.SUNNY;
            }
            return chooseCustomWeather(currentWeather);
        }
        if (currentWeather != Weather.SUNNY) {
            return Weather.SUNNY;
        }
        return chooseWeatherFromSunny();
    }

    private Weather chooseWeatherFromSunny() {
        if (competitionMode.isCustom()) {
            return chooseCustomWeather(null);
        }
        float roll = weatherRandom.nextFloat();
        if (roll < WEATHER_SUNNY_REPEAT_CHANCE) {
            return Weather.SUNNY;
        }
        if (roll < WEATHER_SUNNY_REPEAT_CHANCE + WEATHER_RAIN_CHANCE) {
            return Weather.RAIN;
        }
        return Weather.SNOW;
    }

    private Weather chooseCustomWeather(Weather excluded) {
        if (customGameRules.getWeatherCount() == WeatherType.values().length
                && (excluded == null || excluded == Weather.SUNNY)) {
            float roll = weatherRandom.nextFloat();
            if (roll < WEATHER_SUNNY_REPEAT_CHANCE) {
                return Weather.SUNNY;
            }
            if (roll < WEATHER_SUNNY_REPEAT_CHANCE + WEATHER_RAIN_CHANCE) {
                return Weather.RAIN;
            }
            return Weather.SNOW;
        }

        Array<Weather> allowed = new Array<Weather>();
        for (Weather candidate : Weather.values()) {
            if (customGameRules.isWeatherAllowed(toCustomWeather(candidate))
                    && (candidate != excluded
                            || customGameRules.getWeatherCount() == 1)) {
                allowed.add(candidate);
            }
        }
        if (allowed.size == 0) {
            return Weather.SUNNY;
        }
        return allowed.get(weatherRandom.nextInt(allowed.size));
    }

    private WeatherType toCustomWeather(Weather weather) {
        if (weather == Weather.RAIN) {
            return WeatherType.RAIN;
        }
        if (weather == Weather.SNOW) {
            return WeatherType.SNOW;
        }
        return WeatherType.SUNNY;
    }

    private float randomWeatherDuration(Weather weather) {
        float minimum;
        float maximum;
        if (weather == Weather.RAIN) {
            minimum = WEATHER_RAIN_MIN_DURATION;
            maximum = WEATHER_RAIN_MAX_DURATION;
        } else if (weather == Weather.SNOW) {
            minimum = WEATHER_SNOW_MIN_DURATION;
            maximum = WEATHER_SNOW_MAX_DURATION;
        } else {
            minimum = WEATHER_SUNNY_MIN_DURATION;
            maximum = WEATHER_SUNNY_MAX_DURATION;
        }
        return minimum + weatherRandom.nextFloat() * (maximum - minimum);
    }

    private void setWeather(Weather weather) {
        Weather nextWeather = weather == null ? Weather.SUNNY : weather;
        currentWeather = nextWeather;
        weatherTimeRemaining = randomWeatherDuration(nextWeather);
    }

    private void cycleSandboxWeather(int direction) {
        if (!sandboxMode || direction == 0) {
            return;
        }
        Weather[] weatherValues = Weather.values();
        int nextIndex = (currentWeather.ordinal() + direction) % weatherValues.length;
        if (nextIndex < 0) {
            nextIndex += weatherValues.length;
        }
        setWeather(weatherValues[nextIndex]);
    }

    private float getWeatherGripMultiplierForSimulation() {
        return rlTrainingMode
                ? Weather.SUNNY.gripMultiplier
                : MathUtils.clamp(weatherGripMultiplier, WEATHER_SNOW_GRIP_MULTIPLIER, 1f);
    }

    private Car findActiveRamChargeCar() {
        for (int i = 0; i < cars.size; i++) {
            Car car = cars.get(i);
            if (car.active && car.body != null && car.hasRamCharge()) {
                return car;
            }
        }
        return null;
    }

    private CarTemplate findTemplateByVehicleId(int vehicleId) {
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            if (template.vehicleId == vehicleId) {
                return template;
            }
        }
        return null;
    }

    private void playSound(Sound sound, float volume) {
        float adjustedVolume = MathUtils.clamp(volume, 0f, 1f) * soundEffectsVolume;
        if (sound == null || adjustedVolume <= 0f) {
            return;
        }
        sound.play(adjustedVolume);
    }

    @Override
    public void resize(int width, int height) {
        PresentationViewportLayout.Layout presentationLayout =
                PresentationViewportLayout.fit(width, height, usesAndroidPresentationScale());
        hudViewport.update(
                presentationLayout.screenWidth,
                presentationLayout.screenHeight,
                false);
        hudViewport.setWorldSize(
                presentationLayout.logicalWidth,
                presentationLayout.logicalHeight);
        hudViewport.setScreenBounds(
                presentationLayout.screenX,
                presentationLayout.screenY,
                presentationLayout.screenWidth,
                presentationLayout.screenHeight);
        hudViewport.apply(true);

        int hudWidth = Math.max(1, Math.round(presentationLayout.logicalWidth));
        int hudHeight = Math.max(1, Math.round(presentationLayout.logicalHeight));
        sidebarHudWidth = hudPanelVisibility.isRightPanelVisible()
                ? RacingHudLayout.standingsPanelWidth(
                        hudWidth,
                        calculateSidebarWidth(hudWidth))
                : 0f;
        carPanelHudHeight = hudPanelVisibility.isBottomPanelVisible()
                ? RacingHudLayout.bottomPanelHeight(hudHeight)
                : 0f;
        playfieldHudX = 0f;
        playfieldHudY = carPanelHudHeight;
        playfieldHudWidth = Math.max(1f, hudWidth - sidebarHudWidth);
        playfieldHudHeight = Math.max(1f, hudHeight - carPanelHudHeight);

        float screenScaleX = presentationLayout.screenWidth / presentationLayout.logicalWidth;
        float screenScaleY = presentationLayout.screenHeight / presentationLayout.logicalHeight;
        int playfieldScreenLeft =
                presentationLayout.screenX + Math.round(playfieldHudX * screenScaleX);
        int playfieldScreenBottom =
                presentationLayout.screenY + Math.round(playfieldHudY * screenScaleY);
        int playfieldScreenRight =
                presentationLayout.screenX
                        + Math.round((playfieldHudX + playfieldHudWidth) * screenScaleX);
        int playfieldScreenTop =
                presentationLayout.screenY
                        + Math.round((playfieldHudY + playfieldHudHeight) * screenScaleY);
        int playfieldScreenWidth = Math.max(1, playfieldScreenRight - playfieldScreenLeft);
        int playfieldScreenHeight = Math.max(1, playfieldScreenTop - playfieldScreenBottom);
        worldViewport.update(
                playfieldScreenWidth,
                playfieldScreenHeight,
                true);
        worldViewport.setScreenBounds(
                playfieldScreenLeft,
                playfieldScreenBottom,
                playfieldScreenWidth,
                playfieldScreenHeight);
        updateWorldCamera();
        hudViewport.apply(true);
    }

    private boolean usesAndroidPresentationScale() {
        return Gdx.app != null && Gdx.app.getType() == ApplicationType.Android;
    }

    private void clearPresentationArea(float red, float green, float blue, float alpha) {
        ScreenUtils.clear(0f, 0f, 0f, 1f);
        Gdx.gl.glEnable(GL20.GL_SCISSOR_TEST);
        Gdx.gl.glScissor(
                hudViewport.getScreenX(),
                hudViewport.getScreenY(),
                hudViewport.getScreenWidth(),
                hudViewport.getScreenHeight());
        Gdx.gl.glClearColor(red, green, blue, alpha);
        Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);
        Gdx.gl.glDisable(GL20.GL_SCISSOR_TEST);
    }

    @Override
    public void render() {
        float delta = Math.min(Gdx.graphics.getDeltaTime(), 1f / 30f);

        if (gameMode == GameMode.STARTUP_LOADING) {
            effectClock += delta;
            renderStartupLoadingState(delta);
            return;
        }

        updateVehicleSounds(delta);

        if (gameMode == GameMode.LOADING) {
            effectClock += delta;
            renderLoadingState(delta);
            return;
        }

        if (gameMode == GameMode.ROGUELITE_REWARD
                || gameMode == GameMode.ROGUELITE_COLLECTION
                || gameMode == GameMode.ROGUELITE_END) {
            effectClock += delta;
            if (gameMode == GameMode.ROGUELITE_END) {
                updateRogueliteEndPresentation(delta);
            }
            handleRogueliteOverlayInput();
            if (gameMode == GameMode.ROGUELITE_REWARD
                    && rogueliteRewardInactivityTimer.update(delta)) {
                skipRogueliteReward();
            }
            if (gameMode != GameMode.ROGUELITE_REWARD
                    && gameMode != GameMode.ROGUELITE_COLLECTION
                    && gameMode != GameMode.ROGUELITE_END) {
                return;
            }
            renderWorld();
            renderHud();
            if (gameMode == GameMode.ROGUELITE_REWARD) {
                renderRogueliteRewardOverlay();
            } else if (gameMode == GameMode.ROGUELITE_COLLECTION) {
                renderRogueliteCollectionOverlay();
            } else if (gameMode == GameMode.ROGUELITE_END) {
                renderRogueliteEndOverlay();
            } else if (isInGameMenuOpen()) {
                renderInGameMenuOverlay();
            }
            return;
        }

        if (isInGameMenuOpen()) {
            effectClock += delta;
            updateMenuLayout(hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            handleMenuInput();
            if (!isInGameMenuOpen()) {
                if (gameMode == GameMode.PLAYING) {
                    renderWorld();
                    renderHud();
                } else if (gameMode == GameMode.LOADING) {
                    renderLoadingScreen();
                    loadingScreenPresented = true;
                } else if (gameMode == GameMode.ROGUELITE_COLLECTION) {
                    renderWorld();
                    renderHud();
                    renderRogueliteCollectionOverlay();
                } else {
                    updateMenuLayout(hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
                    renderMenu();
                }
                return;
            }
            renderWorld();
            renderHud();
            renderInGameMenuOverlay();
            return;
        }

        if (gameMode != GameMode.PLAYING) {
            effectClock += delta;
            updateMenuLayout(hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            handleMenuInput();
            if (gameMode == GameMode.LOADING) {
                renderLoadingScreen();
                loadingScreenPresented = true;
            } else {
                renderMenu();
            }
            return;
        }

        if (Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)
                || Gdx.input.isKeyJustPressed(Input.Keys.BACK)) {
            openPauseMenu();
            updateMenuLayout(hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            renderWorld();
            renderHud();
            renderInGameMenuOverlay();
            return;
        }

        if (handleInGameMenuButtonInput()) {
            renderWorld();
            renderHud();
            if (isInGameMenuOpen()) {
                updateMenuLayout(hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
                renderInGameMenuOverlay();
            }
            return;
        }

        if (handleRogueliteCollectionAccess()) {
            renderWorld();
            renderHud();
            renderRogueliteCollectionOverlay();
            return;
        }

        if (handleRaceResultsContinueInput()) {
            renderWorld();
            renderHud();
            if (gameMode == GameMode.ROGUELITE_REWARD) {
                renderRogueliteRewardOverlay();
            } else if (gameMode == GameMode.ROGUELITE_END) {
                renderRogueliteEndOverlay();
            }
            return;
        }

        updateTouchState();
        handleSidebarTablesPointerInput();
        handleSandboxSettingsPointerInput();
        boolean minimapPointerConsumed = handleMinimapCameraInput();
        handleInteractiveCameraInput(minimapPointerConsumed);
        handleCameraTargetInput();
        frameThrottleInput = readPlayerThrottle();
        frameTurnInput = readPlayerTurn();
        frameTurnOverrideActive = isPlayerTurnOverrideActive();
        frameLeftInputActive = isPlayerLeftInputActive();
        frameRightInputActive = isPlayerRightInputActive();

        update(delta);
        followPlayerCarAfterSteeringTakeover();
        renderWorld();
        renderHud();
        if (shouldOfferLiveRogueliteReward()) {
            openRogueliteRewardChoice(true);
            renderRogueliteRewardOverlay();
        }
    }

    private void renderStartupLoadingState(float delta) {
        loadingDisplayedProgress = Math.min(
                loadingProgress,
                loadingDisplayedProgress
                        + Math.max(0f, delta) * LOADING_PROGRESS_DISPLAY_SPEED);
        if (!loadingScreenPresented) {
            renderLoadingScreen();
            loadingScreenPresented = true;
            return;
        }

        if (loadingDisplayedProgress + 0.001f < loadingProgress) {
            renderLoadingScreen();
            return;
        }

        if (loadingStage < STARTUP_LOADING_STAGE_COUNT) {
            advancePendingStartupLoading();
            renderLoadingScreen();
            return;
        }

        if (!loadingCompletionPresented) {
            renderLoadingScreen();
            loadingCompletionPresented = true;
            return;
        }

        gameMode = GameMode.MAIN_MENU;
        renderMenu();
    }

    private void renderLoadingState(float delta) {
        loadingDisplayedProgress = Math.min(
                loadingProgress,
                loadingDisplayedProgress
                        + Math.max(0f, delta) * LOADING_PROGRESS_DISPLAY_SPEED);
        if (!loadingScreenPresented) {
            renderLoadingScreen();
            loadingScreenPresented = true;
            return;
        }

        if (loadingDisplayedProgress + 0.001f < loadingProgress) {
            renderLoadingScreen();
            return;
        }

        int loadingStageCount = loadingMapTransition
                ? MAP_LOADING_STAGE_COUNT
                : LOADING_STAGE_COUNT;
        if (loadingStage < loadingStageCount) {
            if (loadingMapTransition) {
                advancePendingMapTransitionLoading();
            } else {
                advancePendingGameLoading();
            }
            renderLoadingScreen();
            return;
        }

        if (!loadingCompletionPresented) {
            renderLoadingScreen();
            loadingCompletionPresented = true;
            return;
        }

        loadingPreserveSandboxConfiguration = false;
        loadingMapTransition = false;
        gameMode = loadingCompletionMode;
        if (gameMode == GameMode.ROGUELITE_END) {
            startRogueliteEndPresentation();
        } else {
            playCircuitMusic();
        }
        renderWorld();
        renderHud();
        if (gameMode == GameMode.ROGUELITE_REWARD) {
            renderRogueliteRewardOverlay();
        }
    }

    private boolean isInGameMenuOpen() {
        return gameMode == GameMode.PAUSE_MENU
                || (gameMode == GameMode.OPTIONS_MENU && optionsOpenedFromPause);
    }

    private boolean handleRogueliteCollectionAccess() {
        updateRogueliteCardsButtonLayout(
                hudViewport.getWorldWidth(),
                hudViewport.getWorldHeight());
        boolean shortcutPressed = Gdx.input.isKeyJustPressed(Input.Keys.C);
        boolean buttonPressed = false;
        int clickedSlotIndex = -1;
        RogueliteCardId clickedDebuffCardId = null;
        if (hudPanelVisibility.isBottomPanelVisible() && Gdx.input.justTouched()) {
            hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
            hudViewport.unproject(hudTouchPoint);
            buttonPressed =
                    rogueliteCardsButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y);
            if (!buttonPressed) {
                for (int i = 0; i < carPanelSlotBounds.length; i++) {
                    if (carPanelSlotBounds[i].contains(
                            hudTouchPoint.x,
                            hudTouchPoint.y)) {
                        clickedSlotIndex = i;
                        break;
                    }
                }
                Car target = getCameraTargetCar();
                if (clickedSlotIndex < 0
                        && carPanelDebuffBounds.contains(
                                hudTouchPoint.x,
                                hudTouchPoint.y)
                        && isDebuffTargetActive(target)) {
                    clickedDebuffCardId =
                            target.debuffTargetVisual.getActiveCardId();
                }
            }
        }
        if (clickedDebuffCardId != null) {
            openRogueliteCardInspection(GameMode.PLAYING, clickedDebuffCardId);
            return true;
        }
        if (clickedSlotIndex >= 0) {
            openRogueliteCardInspection(GameMode.PLAYING, clickedSlotIndex);
            return true;
        }
        if (!shortcutPressed && !buttonPressed) {
            return false;
        }
        openRogueliteCollection(GameMode.PLAYING);
        return true;
    }

    private boolean handleInGameMenuButtonInput() {
        if (!isPresentationEnabled()
                || gameMode != GameMode.PLAYING
                || !Gdx.input.justTouched()) {
            return false;
        }
        updateInGameMenuButtonLayout(
                hudViewport.getWorldWidth(),
                hudViewport.getWorldHeight());
        hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
        hudViewport.unproject(hudTouchPoint);
        if (inGamePanelsButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            toggleHudPanels();
            return true;
        }
        if (inGameTvCameraButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            selectEventCamera();
            return true;
        }
        if (inGamePreviousCarButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeCameraTarget(1);
            return true;
        }
        if (inGameNextCarButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeCameraTarget(-1);
            return true;
        }
        if (inGameMenuButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            openPauseMenu();
            return true;
        }
        return false;
    }

    private void toggleHudPanels() {
        hudPanelVisibility = hudPanelVisibility.next();
        cancelSidebarTablesPointerInput();
        resize(Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
    }

    private boolean handleRaceResultsContinueInput() {
        if (!roundOver || !isPresentationEnabled()) {
            return false;
        }

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        float playfieldWidth = playfieldHudWidth > 0f ? playfieldHudWidth : hudWidth;
        updateRaceResultsContinueLayout(playfieldWidth, hudHeight);

        boolean continueRequested =
                Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                        || Gdx.input.isKeyJustPressed(Input.Keys.SPACE);
        if (!continueRequested && Gdx.input.justTouched()) {
            hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
            hudViewport.unproject(hudTouchPoint);
            continueRequested =
                    raceResultsContinueBounds.contains(
                            hudTouchPoint.x,
                            hudTouchPoint.y);
        }
        if (!continueRequested) {
            return false;
        }

        continueAfterRoundResults();
        return true;
    }

    private void handleRogueliteOverlayInput() {
        if (gameMode == GameMode.ROGUELITE_REWARD) {
            rogueliteCardsButtonBounds.set(0f, 0f, 0f, 0f);
            updateRogueliteRewardLayout(
                    hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            handleRogueliteRewardInput();
        } else if (gameMode == GameMode.ROGUELITE_END) {
            rogueliteCardsButtonBounds.set(0f, 0f, 0f, 0f);
            handleRogueliteEndInput();
        } else {
            rogueliteCardsButtonBounds.set(0f, 0f, 0f, 0f);
            if (rogueliteSingleCardInspection) {
                updateRogueliteCardInspectionLayout(
                        hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            } else if (sandboxMode) {
                updateSandboxCardConfigurationLayout(
                        hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            } else {
                updateRogueliteCollectionLayout(
                        hudViewport.getWorldWidth(), hudViewport.getWorldHeight());
            }
            handleRogueliteCollectionInput();
        }
    }

    private void handleRogueliteRewardInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)
                || Gdx.input.isKeyJustPressed(Input.Keys.BACK)) {
            if (roguelitePendingOffer != null) {
                cancelRogueliteRewardPreview();
            } else {
                skipRogueliteReward();
            }
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.C)) {
            rogueliteRewardInactivityTimer.reset();
            openRogueliteCollection(GameMode.ROGUELITE_REWARD);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
            changeRogueliteRewardSelection(-1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
            changeRogueliteRewardSelection(1);
        }
        for (int i = 0; i < getRogueliteRewardInputCount(); i++) {
            if (Gdx.input.isKeyJustPressed(Input.Keys.NUM_1 + i)) {
                chooseRogueliteRewardInput(i);
                return;
            }
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            if (roguelitePendingOffer == null) {
                previewRogueliteReward(rogueliteRewardSelection);
            } else {
                acceptRogueliteReward();
            }
            return;
        }
        if (!Gdx.input.justTouched()) {
            return;
        }
        hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
        hudViewport.unproject(hudTouchPoint);
        if (rogueliteCardsButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            openRogueliteCollection(GameMode.ROGUELITE_REWARD);
            return;
        }
        if (rogueliteRewardSkipBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            skipRogueliteReward();
            return;
        }
        if (rogueliteRewardAcceptBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            acceptRogueliteReward();
            return;
        }
        if (rogueliteRewardCancelBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            cancelRogueliteRewardPreview();
            return;
        }
        for (int i = 0; i < getRogueliteRewardInputCount(); i++) {
            if (rogueliteRewardCardBounds[i].contains(hudTouchPoint.x, hudTouchPoint.y)) {
                previewRogueliteReward(i);
                return;
            }
        }
    }

    private void changeRogueliteRewardSelection(int direction) {
        int count = getRogueliteRewardInputCount();
        if (count <= 0 || direction == 0) {
            return;
        }
        rogueliteRewardSelection =
                Math.floorMod(rogueliteRewardSelection + direction, count);
        rogueliteRewardInactivityTimer.reset();
        if (roguelitePendingOffer != null) {
            previewRogueliteReward(rogueliteRewardSelection);
        }
    }

    private int getRogueliteRewardInputCount() {
        return Math.min(
                ROGUELITE_REWARD_CARD_COUNT,
                rogueliteRewardChoices.size());
    }

    private void chooseRogueliteRewardInput(int selection) {
        previewRogueliteReward(selection);
    }

    private void handleRogueliteEndInput() {
        updateRogueliteEndLayout(
                hudViewport.getWorldWidth(),
                hudViewport.getWorldHeight());
        boolean continueRequested =
                Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                        || Gdx.input.isKeyJustPressed(Input.Keys.SPACE);
        boolean returnRequested =
                Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)
                        || Gdx.input.isKeyJustPressed(Input.Keys.BACK);
        if (!continueRequested && !returnRequested && Gdx.input.justTouched()) {
            hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
            hudViewport.unproject(hudTouchPoint);
            continueRequested =
                    rogueliteEndContinueBounds.contains(
                            hudTouchPoint.x,
                            hudTouchPoint.y);
            returnRequested =
                    rogueliteEndMainMenuBounds.contains(
                            hudTouchPoint.x,
                            hudTouchPoint.y);
        }
        if (continueRequested) {
            continueCompletedChampionship();
            return;
        }
        if (!returnRequested) {
            return;
        }
        returnToMainMenu();
        deleteRogueliteSave();
    }

    private void handleRogueliteCollectionInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)
                || Gdx.input.isKeyJustPressed(Input.Keys.BACK)
                || Gdx.input.isKeyJustPressed(Input.Keys.C)) {
            closeRogueliteCollection();
            return;
        }
        if (rogueliteSingleCardInspection) {
            if (!Gdx.input.justTouched()) {
                return;
            }
            closeRogueliteCollection();
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
            changeRogueliteCollectionPage(-1);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
            changeRogueliteCollectionPage(1);
            return;
        }
        if (sandboxMode) {
            for (int i = 0; i < getRogueliteCollectionVisibleCount(); i++) {
                if (Gdx.input.isKeyJustPressed(Input.Keys.NUM_1 + i)) {
                    toggleSandboxCollectionChoice(i);
                    return;
                }
            }
        }
        if (!Gdx.input.justTouched()) {
            return;
        }
        hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
        hudViewport.unproject(hudTouchPoint);
        if (rogueliteCollectionCloseBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            closeRogueliteCollection();
            return;
        }
        if (sandboxMode
                && sandboxPropagateLoadoutBounds.contains(
                        hudTouchPoint.x,
                        hudTouchPoint.y)) {
            propagateSandboxLoadout();
            return;
        }
        if (rogueliteCollectionPreviousBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeRogueliteCollectionPage(-1);
        } else if (rogueliteCollectionNextBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeRogueliteCollectionPage(1);
        } else if (sandboxMode) {
            for (int i = 0; i < getRogueliteCollectionVisibleCount(); i++) {
                if (rogueliteCollectionCardBounds[i].contains(
                        hudTouchPoint.x,
                        hudTouchPoint.y)) {
                    toggleSandboxCollectionChoice(i);
                    return;
                }
            }
        } else {
            for (int i = 0; i < getRogueliteCollectionVisibleCount(); i++) {
                if (rogueliteCollectionCardBounds[i].contains(
                        hudTouchPoint.x,
                        hudTouchPoint.y)) {
                    rogueliteCollectionInspectedIndex =
                            getRogueliteCollectionPageStart() + i;
                    return;
                }
            }
        }
    }

    private boolean handleHudScrolled(float amountY) {
        if (gameMode == GameMode.CUSTOM_GAME_MENU
                && Math.abs(amountY) > 0.0001f) {
            scrollCustomGameMenu(amountY * 120f);
            return true;
        }
        if (gameMode == GameMode.ROGUELITE_COLLECTION
                && sandboxMode
                && Math.abs(amountY) > 0.0001f) {
            changeRogueliteCollectionPage(amountY > 0f ? 1 : -1);
            return true;
        }
        if (gameMode != GameMode.PLAYING || Math.abs(amountY) <= 0.0001f) {
            return false;
        }

        hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
        hudViewport.unproject(hudTouchPoint);
        if (isPointInPlayfield(hudTouchPoint.x, hudTouchPoint.y)) {
            changeCameraZoom(-amountY);
            return true;
        }
        if (!hudPanelVisibility.isRightPanelVisible()) {
            return false;
        }

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        float sidebarX = hudWidth - sidebarHudWidth;
        float sidebarWidth = Math.max(0f, sidebarHudWidth);
        if (!getSidebarTablesViewportBounds(sidebarX, sidebarWidth, hudHeight, sidebarTablesViewportBounds)) {
            return false;
        }

        if (!sidebarTablesViewportBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            return false;
        }

        scrollSidebarTables(
                amountY * getSidebarCompactLeaderboardRowStep() * 3f,
                sidebarX,
                sidebarWidth,
                hudHeight);
        return true;
    }

    private void handleSidebarTablesPointerInput() {
        if (!hudPanelVisibility.isRightPanelVisible()) {
            cancelSidebarTablesPointerInput();
            return;
        }
        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        float sidebarX = hudWidth - sidebarHudWidth;
        float sidebarWidth = Math.max(0f, sidebarHudWidth);

        updateSidebarTablesScrollbarBounds(sidebarX, sidebarWidth, hudHeight);
        boolean hasScrollbar = sidebarTablesScrollbarBounds.width > 0f;

        if (Gdx.input.justTouched()
                && !sidebarTablesScrollbarDragging
                && !sidebarTablesDragGesture.isActive()) {
            int pointer = findTouchedPointer(sidebarTablesViewportBounds);
            if (pointer < 0) {
                return;
            }
            hudTouchPoint.set(
                    Gdx.input.getX(pointer),
                    Gdx.input.getY(pointer),
                    0f);
            hudViewport.unproject(hudTouchPoint);
            if (hasScrollbar && sidebarTablesScrollbarBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
                sidebarTablesScrollbarDragging = true;
                sidebarTablesScrollbarPointer = pointer;
                sidebarTablesScrollbarGrabOffsetY = hudTouchPoint.y - sidebarTablesScrollbarBounds.y;
                return;
            }
            sidebarTablesDragGesture.begin(pointer, hudTouchPoint.x, hudTouchPoint.y);
            return;
        }

        if (sidebarTablesScrollbarDragging) {
            if (sidebarTablesScrollbarPointer < 0
                    || !Gdx.input.isTouched(sidebarTablesScrollbarPointer)) {
                sidebarTablesScrollbarDragging = false;
                sidebarTablesScrollbarPointer = -1;
                return;
            }
            hudTouchPoint.set(
                    Gdx.input.getX(sidebarTablesScrollbarPointer),
                    Gdx.input.getY(sidebarTablesScrollbarPointer),
                    0f);
            hudViewport.unproject(hudTouchPoint);
            setSidebarTablesScrollFromThumb(
                    hudTouchPoint.y - sidebarTablesScrollbarGrabOffsetY,
                    sidebarX,
                    sidebarWidth,
                    hudHeight);
            return;
        }

        if (!sidebarTablesDragGesture.isActive()) {
            return;
        }

        int pointer = sidebarTablesDragGesture.getPointer();
        if (!Gdx.input.isTouched(pointer)) {
            float tapX = sidebarTablesDragGesture.getStartX();
            float tapY = sidebarTablesDragGesture.getStartY();
            boolean tap = sidebarTablesDragGesture.end(pointer);
            if (tap) {
                selectCameraTargetFromSidebarTables(
                        tapX,
                        tapY,
                        sidebarX,
                        sidebarWidth,
                        hudHeight);
            }
            return;
        }

        hudTouchPoint.set(
                Gdx.input.getX(pointer),
                Gdx.input.getY(pointer),
                0f);
        hudViewport.unproject(hudTouchPoint);
        float scrollDelta = sidebarTablesDragGesture.drag(
                pointer,
                hudTouchPoint.x,
                hudTouchPoint.y,
                SIDEBAR_CONTENT_DRAG_SLOP);
        if (Math.abs(scrollDelta) > 0.0001f) {
            scrollSidebarTables(scrollDelta, sidebarX, sidebarWidth, hudHeight);
        }
    }

    private int findTouchedPointer(Rectangle bounds) {
        int maxPointers = Math.min(5, Gdx.input.getMaxPointers());
        for (int pointer = 0; pointer < maxPointers; pointer++) {
            if (!Gdx.input.isTouched(pointer)) {
                continue;
            }
            hudTouchPoint.set(
                    Gdx.input.getX(pointer),
                    Gdx.input.getY(pointer),
                    0f);
            hudViewport.unproject(hudTouchPoint);
            if (bounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
                return pointer;
            }
        }
        return -1;
    }

    private void cancelSidebarTablesPointerInput() {
        sidebarTablesScrollbarDragging = false;
        sidebarTablesScrollbarPointer = -1;
        sidebarTablesDragGesture.cancel();
    }

    private boolean selectCameraTargetFromSidebarTables(
            float touchX,
            float touchY,
            float sidebarX,
            float sidebarWidth,
            float hudHeight) {
        refreshLeaderboardEntries();
        if (leaderboardEntries.size == 0
                || !getSidebarTablesViewportBounds(sidebarX, sidebarWidth, hudHeight, sidebarTablesViewportBounds)
                || !sidebarTablesViewportBounds.contains(touchX, touchY)) {
            return false;
        }

        clampSidebarTablesScrollOffset(sidebarX, sidebarWidth, hudHeight);

        float x = sidebarX + SIDEBAR_CONTENT_MARGIN;
        float viewportTop = sidebarTablesViewportBounds.y + sidebarTablesViewportBounds.height - 2f;
        float rowStep = getSidebarCompactLeaderboardRowStep();
        float headerStep = Math.max(16f, rowStep + 1f);
        boolean overflow = getSidebarTablesMaxScroll(sidebarX, sidebarWidth, hudHeight) > 0.5f;
        float contentWidth =
                Math.max(1f, sidebarWidth - SIDEBAR_CONTENT_MARGIN * 2f - (overflow ? 12f : 0f));

        float contentY = headerStep;
        if (touchX >= x && touchX <= x + contentWidth) {
            int raceRow =
                    RacingHudLayout.sidebarTableRowAt(
                            touchY,
                            viewportTop,
                            contentY,
                            sidebarTablesScrollOffset,
                            rowStep,
                            leaderboardEntries.size);
            if (raceRow >= 0) {
                return selectPlayerCameraTarget(
                        leaderboardEntries.get(raceRow),
                        true);
            }
        }

        contentY += leaderboardEntries.size * rowStep;
        if (!shouldShowSidebarChampionshipStandings()) {
            return false;
        }

        refreshProjectedChampionshipEntries();
        contentY += SIDEBAR_MINIMAP_GAP + headerStep + rowStep;
        if (touchX < x || touchX > x + contentWidth) {
            return false;
        }
        int championshipRow =
                RacingHudLayout.sidebarTableRowAt(
                        touchY,
                        viewportTop,
                        contentY,
                        sidebarTablesScrollOffset,
                        rowStep,
                        projectedChampionshipEntries.size);
        if (championshipRow >= 0) {
            return selectPlayerCameraTarget(
                    projectedChampionshipEntries.get(championshipRow),
                    true);
        }
        return false;
    }

    private void handleSandboxSettingsPointerInput() {
        if (!sandboxMode
                || gameMode != GameMode.PLAYING
                || !hudPanelVisibility.isAnyPanelVisible()
                || !Gdx.input.justTouched()) {
            return;
        }

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        float playfieldWidth = playfieldHudWidth > 0f ? playfieldHudWidth : hudWidth;
        updateSandboxSettingsLayout(playfieldWidth, hudHeight);

        hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
        hudViewport.unproject(hudTouchPoint);
        if (!sandboxSettingsBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            return;
        }

        if (sandboxMapsButtonBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            openSandboxMapsMenu();
            return;
        }
        if (sandboxRestartBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            restartCurrentGame();
            return;
        }
        if (sandboxDebugGuidesBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            sandboxDebugGuidesVisible = !sandboxDebugGuidesVisible;
            saveMenuSettings();
            return;
        }

        if (sandboxControlPrevBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeSandboxControlMode();
            return;
        }
        if (sandboxControlNextBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeSandboxControlMode();
            return;
        }

        if (sandboxWeatherPrevBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            cycleSandboxWeather(-1);
            return;
        }
        if (sandboxWeatherNextBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            cycleSandboxWeather(1);
            return;
        }
        if (sandboxCarsPrevBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeSandboxCarCount(-1);
            return;
        }
        if (sandboxCarsNextBounds.contains(hudTouchPoint.x, hudTouchPoint.y)) {
            changeSandboxCarCount(1);
            return;
        }
    }

    private void updateSandboxSettingsLayout(float playfieldWidth, float hudHeight) {
        float width = Math.min(
                SANDBOX_SETTINGS_WIDTH,
                Math.max(230f, playfieldWidth - SANDBOX_SETTINGS_MARGIN * 2f));
        float height =
                SANDBOX_SETTINGS_HEADER_HEIGHT
                        + SANDBOX_SETTINGS_ROW_HEIGHT * SANDBOX_SETTINGS_ROW_COUNT
                        + SANDBOX_SETTINGS_RESTART_HEIGHT
                        + 16f;
        float x = playfieldHudX + SANDBOX_SETTINGS_MARGIN;
        float hudWidth = hudViewport.getWorldWidth();
        float topControlsBottom =
                hudHeight
                        - RacingHudLayout.inGameMenuButtonMargin(hudWidth, hudHeight)
                        - RacingHudLayout.inGameMenuButtonSize(hudWidth, hudHeight);
        float y = Math.max(
                playfieldHudY + SANDBOX_SETTINGS_MARGIN,
                topControlsBottom - SANDBOX_SETTINGS_TOP_GAP - height);
        sandboxSettingsBounds.set(x, y, width, height);

        float mapsWidth = 68f;
        sandboxMapsButtonBounds.set(
                x + width - mapsWidth - 8f,
                y + height - SANDBOX_SETTINGS_HEADER_HEIGHT + 5f,
                mapsWidth,
                SANDBOX_SETTINGS_HEADER_HEIGHT - 10f);

        float buttonSize = Math.min(36f, SANDBOX_SETTINGS_ROW_HEIGHT - 4f);
        float rowTop = y + height - SANDBOX_SETTINGS_HEADER_HEIGHT;
        float controlRowY =
                rowTop
                        - (SANDBOX_SETTINGS_CONTROL_ROW + 1)
                                * SANDBOX_SETTINGS_ROW_HEIGHT;
        float controlButtonY =
                controlRowY
                        + (SANDBOX_SETTINGS_ROW_HEIGHT - buttonSize) * 0.5f;
        sandboxControlPrevBounds.set(
                x + width - buttonSize * 2f - 17f,
                controlButtonY,
                buttonSize,
                buttonSize);
        sandboxControlNextBounds.set(
                x + width - buttonSize - 8f,
                controlButtonY,
                buttonSize,
                buttonSize);
        float weatherRowY =
                rowTop
                        - (SANDBOX_SETTINGS_WEATHER_ROW + 1)
                                * SANDBOX_SETTINGS_ROW_HEIGHT;
        float weatherButtonY =
                weatherRowY
                        + (SANDBOX_SETTINGS_ROW_HEIGHT - buttonSize) * 0.5f;
        sandboxWeatherPrevBounds.set(
                x + width - buttonSize * 2f - 17f,
                weatherButtonY,
                buttonSize,
                buttonSize);
        sandboxWeatherNextBounds.set(
                x + width - buttonSize - 8f,
                weatherButtonY,
                buttonSize,
                buttonSize);
        float carsRowY =
                rowTop
                        - (SANDBOX_SETTINGS_CARS_ROW + 1)
                                * SANDBOX_SETTINGS_ROW_HEIGHT;
        float carsButtonY =
                carsRowY
                        + (SANDBOX_SETTINGS_ROW_HEIGHT - buttonSize) * 0.5f;
        sandboxCarsPrevBounds.set(
                x + width - buttonSize * 2f - 17f,
                carsButtonY,
                buttonSize,
                buttonSize);
        sandboxCarsNextBounds.set(
                x + width - buttonSize - 8f,
                carsButtonY,
                buttonSize,
                buttonSize);
        float debugGuidesRowY =
                rowTop
                        - (SANDBOX_SETTINGS_DEBUG_GUIDES_ROW + 1)
                                * SANDBOX_SETTINGS_ROW_HEIGHT;
        sandboxDebugGuidesBounds.set(
                x + 7f,
                debugGuidesRowY + 2f,
                width - 14f,
                SANDBOX_SETTINGS_ROW_HEIGHT - 4f);
        sandboxRestartBounds.set(
                x + 7f,
                y + 6f,
                width - 14f,
                SANDBOX_SETTINGS_RESTART_HEIGHT);
    }

    private void handleMenuInput() {
        if (gameMode == GameMode.NEW_GAME_CAR_MENU && playerNameEditor.isEditing()) {
            if (playerNameCancelRequested
                    || Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)
                    || Gdx.input.isKeyJustPressed(Input.Keys.BACK)) {
                cancelPlayerNameEdit();
                return;
            }
            if (playerNameCommitRequested
                    || Gdx.input.isKeyJustPressed(Input.Keys.ENTER)) {
                commitPlayerNameEdit();
                return;
            }
            if (Gdx.input.justTouched()) {
                hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
                hudViewport.unproject(hudTouchPoint);
                handleMenuClick(hudTouchPoint.x, hudTouchPoint.y);
            }
            return;
        }
        if (gameMode == GameMode.OPTIONS_MENU && optionsInputSuppressionFrames > 0) {
            optionsInputSuppressionFrames--;
            return;
        }
        if (gameMode == GameMode.OPTIONS_MENU && pendingDrivingKeyBinding != null) {
            return;
        }
        if (isInGameMenuOpen() && Gdx.input.isKeyJustPressed(Input.Keys.C)) {
            openRogueliteCollection(gameMode);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)
                || Gdx.input.isKeyJustPressed(Input.Keys.BACK)) {
            if (gameMode == GameMode.OPTIONS_MENU) {
                closeOptionsMenu();
                return;
            }
            if (gameMode == GameMode.NEW_GAME_TIER_MENU) {
                closeNewGameTierMenu();
                return;
            }
            if (gameMode == GameMode.CUSTOM_GAME_MENU) {
                openNewGameTierMenu();
                return;
            }
            if (gameMode == GameMode.NEW_GAME_CAR_MENU) {
                openPreviousNewGameMenu();
                return;
            }
            if (gameMode == GameMode.MAPS_MENU) {
                closeMapsMenu();
                return;
            }
            if (gameMode == GameMode.PAUSE_MENU) {
                resumeGame();
                return;
            }
            Gdx.app.exit();
            return;
        }

        if (gameMode == GameMode.MAIN_MENU) {
            handleMainMenuInput();
        } else if (gameMode == GameMode.NEW_GAME_TIER_MENU) {
            handleNewGameTierMenuInput();
        } else if (gameMode == GameMode.CUSTOM_GAME_MENU) {
            handleCustomGameMenuInput();
            handleCustomGameMenuPointerInput();
        } else if (gameMode == GameMode.NEW_GAME_CAR_MENU) {
            handleNewGameCarMenuInput();
        } else if (gameMode == GameMode.MAPS_MENU) {
            handleMapsMenuInput();
        } else if (gameMode == GameMode.PAUSE_MENU) {
            handlePauseMenuInput();
        } else if (gameMode == GameMode.OPTIONS_MENU) {
            handleOptionsMenuInput();
        }

        if (gameMode != GameMode.CUSTOM_GAME_MENU && Gdx.input.justTouched()) {
            hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
            hudViewport.unproject(hudTouchPoint);
            handleMenuClick(hudTouchPoint.x, hudTouchPoint.y);
        }
    }

    private void handleMainMenuInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.UP)
                || Gdx.input.isKeyJustPressed(Input.Keys.W)) {
            changeMainMenuSelection(-1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.DOWN)
                || Gdx.input.isKeyJustPressed(Input.Keys.S)) {
            changeMainMenuSelection(1);
        }
        if (mainMenuSelection == MAIN_MENU_THEME_SELECTION) {
            if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
                cycleTheme(-1);
            }
            if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
                cycleTheme(1);
            }
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.O)) {
            openOptionsMenu(false);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            if (mainMenuSelection == MAIN_MENU_THEME_SELECTION) {
                cycleTheme(1);
            } else if (mainMenuSelection == MAIN_MENU_NEW_GAME_SELECTION) {
                openNewGameTierMenu();
            } else if (mainMenuSelection == MAIN_MENU_CONTINUE_SELECTION) {
                continueSavedGame();
            } else if (mainMenuSelection == MAIN_MENU_SANDBOX_SELECTION) {
                startSandboxGame();
            } else if (mainMenuSelection == MAIN_MENU_OPTIONS_SELECTION) {
                openOptionsMenu(false);
            } else {
                Gdx.app.exit();
            }
        }
    }

    private void handleMapsMenuInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
            changeSandboxMapSelection(-1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
            changeSandboxMapSelection(1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            closeMapsMenu();
        }
    }

    private void handleNewGameTierMenuInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.UP)
                || Gdx.input.isKeyJustPressed(Input.Keys.W)) {
            newGameMenuSelection = Math.max(0, newGameMenuSelection - 1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.DOWN)
                || Gdx.input.isKeyJustPressed(Input.Keys.S)) {
            newGameMenuSelection =
                    Math.min(
                            NEW_GAME_TIER_BACK_SELECTION,
                            newGameMenuSelection + 1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            if (newGameMenuSelection < NEW_GAME_CUSTOM_SELECTION) {
                selectedCompetitionMode = RogueliteCompetitionMode.CHAMPIONSHIP;
                selectedStartingTier = newGameMenuSelection + 1;
                openNewGameCarMenu();
            } else if (newGameMenuSelection == NEW_GAME_CUSTOM_SELECTION) {
                openCustomGameMenu();
            } else {
                closeNewGameTierMenu();
            }
        }
    }

    private void handleNewGameCarMenuInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
            changePlayerCar(-1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
            changePlayerCar(1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.UP)
                || Gdx.input.isKeyJustPressed(Input.Keys.W)) {
            newGameCarMenuSelection =
                    Math.max(NEW_GAME_CAR_NAME_SELECTION, newGameCarMenuSelection - 1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.DOWN)
                || Gdx.input.isKeyJustPressed(Input.Keys.S)) {
            newGameCarMenuSelection =
                    Math.min(NEW_GAME_CAR_BACK_SELECTION, newGameCarMenuSelection + 1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            if (newGameCarMenuSelection == NEW_GAME_CAR_NAME_SELECTION) {
                editPlayerName();
            } else if (newGameCarMenuSelection == NEW_GAME_CAR_START_SELECTION) {
                startNewGame();
            } else {
                openPreviousNewGameMenu();
            }
        }
    }

    private void handleCustomGameMenuInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.UP)
                || Gdx.input.isKeyJustPressed(Input.Keys.W)) {
            scrollCustomGameMenu(-64f);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.DOWN)
                || Gdx.input.isKeyJustPressed(Input.Keys.S)) {
            scrollCustomGameMenu(64f);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            startCustomGameSelection();
        }
    }

    private void handleCustomGameMenuPointerInput() {
        updateCustomMenuScrollbarBounds();
        boolean hasScrollbar = customMenuScrollbarBounds.width > 0f;

        if (Gdx.input.justTouched()
                && !customMenuScrollbarDragging
                && !customMenuDragGesture.isActive()) {
            int pointer = findTouchedPointer(customMenuScrollViewportBounds);
            if (pointer < 0) {
                hudTouchPoint.set(Gdx.input.getX(), Gdx.input.getY(), 0f);
                hudViewport.unproject(hudTouchPoint);
                handleCustomGameMenuClick(hudTouchPoint.x, hudTouchPoint.y);
                return;
            }
            hudTouchPoint.set(
                    Gdx.input.getX(pointer),
                    Gdx.input.getY(pointer),
                    0f);
            hudViewport.unproject(hudTouchPoint);
            if (hasScrollbar
                    && customMenuScrollbarBounds.contains(
                            hudTouchPoint.x,
                            hudTouchPoint.y)) {
                customMenuScrollbarDragging = true;
                customMenuScrollbarPointer = pointer;
                customMenuScrollbarGrabOffsetY =
                        hudTouchPoint.y - customMenuScrollbarBounds.y;
                return;
            }
            customMenuDragGesture.begin(pointer, hudTouchPoint.x, hudTouchPoint.y);
            return;
        }

        if (customMenuScrollbarDragging) {
            if (customMenuScrollbarPointer < 0
                    || !Gdx.input.isTouched(customMenuScrollbarPointer)) {
                customMenuScrollbarDragging = false;
                customMenuScrollbarPointer = -1;
                return;
            }
            hudTouchPoint.set(
                    Gdx.input.getX(customMenuScrollbarPointer),
                    Gdx.input.getY(customMenuScrollbarPointer),
                    0f);
            hudViewport.unproject(hudTouchPoint);
            setCustomMenuScrollFromThumb(
                    hudTouchPoint.y - customMenuScrollbarGrabOffsetY);
            return;
        }

        if (!customMenuDragGesture.isActive()) {
            return;
        }
        int pointer = customMenuDragGesture.getPointer();
        if (!Gdx.input.isTouched(pointer)) {
            float tapX = customMenuDragGesture.getStartX();
            float tapY = customMenuDragGesture.getStartY();
            if (customMenuDragGesture.end(pointer)) {
                handleCustomGameMenuClick(tapX, tapY);
            }
            return;
        }

        hudTouchPoint.set(
                Gdx.input.getX(pointer),
                Gdx.input.getY(pointer),
                0f);
        hudViewport.unproject(hudTouchPoint);
        float scrollDelta = customMenuDragGesture.drag(
                pointer,
                hudTouchPoint.x,
                hudTouchPoint.y,
                SIDEBAR_CONTENT_DRAG_SLOP);
        if (Math.abs(scrollDelta) > 0.0001f) {
            scrollCustomGameMenu(scrollDelta);
        }
    }

    private void cancelCustomGameMenuPointerInput() {
        customMenuScrollbarDragging = false;
        customMenuScrollbarPointer = -1;
        if (customMenuDragGesture != null) {
            customMenuDragGesture.cancel();
        }
    }

    private float getCustomMenuMaxScroll() {
        return Math.max(
                0f,
                customMenuContentHeight - customMenuScrollViewportBounds.height);
    }

    private void scrollCustomGameMenu(float amount) {
        customMenuScrollOffset = MathUtils.clamp(
                customMenuScrollOffset + amount,
                0f,
                getCustomMenuMaxScroll());
        updateCustomMenuScrollbarBounds();
    }

    private void updateCustomMenuScrollbarBounds() {
        float maxScroll = getCustomMenuMaxScroll();
        if (maxScroll <= 0.5f || customMenuScrollViewportBounds.height <= 0f) {
            customMenuScrollbarTrackBounds.set(0f, 0f, 0f, 0f);
            customMenuScrollbarBounds.set(0f, 0f, 0f, 0f);
            customMenuScrollOffset = 0f;
            return;
        }
        float trackWidth = 14f;
        customMenuScrollbarTrackBounds.set(
                customMenuScrollViewportBounds.x
                        + customMenuScrollViewportBounds.width
                        - trackWidth,
                customMenuScrollViewportBounds.y,
                trackWidth,
                customMenuScrollViewportBounds.height);
        float thumbHeight = Math.max(
                32f,
                customMenuScrollViewportBounds.height
                        * customMenuScrollViewportBounds.height
                        / customMenuContentHeight);
        float maxThumbTravel = Math.max(
                1f,
                customMenuScrollViewportBounds.height - thumbHeight);
        float scrollRatio = MathUtils.clamp(customMenuScrollOffset / maxScroll, 0f, 1f);
        float thumbY = customMenuScrollViewportBounds.y
                + customMenuScrollViewportBounds.height
                - thumbHeight
                - scrollRatio * maxThumbTravel;
        customMenuScrollbarBounds.set(
                customMenuScrollbarTrackBounds.x,
                thumbY,
                trackWidth,
                thumbHeight);
    }

    private void setCustomMenuScrollFromThumb(float thumbY) {
        float maxScroll = getCustomMenuMaxScroll();
        if (maxScroll <= 0f) {
            customMenuScrollOffset = 0f;
            return;
        }
        float thumbHeight = customMenuScrollbarBounds.height;
        float maxThumbTravel = Math.max(
                1f,
                customMenuScrollViewportBounds.height - thumbHeight);
        float clampedY = MathUtils.clamp(
                thumbY,
                customMenuScrollViewportBounds.y,
                customMenuScrollViewportBounds.y
                        + customMenuScrollViewportBounds.height
                        - thumbHeight);
        float scrollRatio =
                (customMenuScrollViewportBounds.y
                                + customMenuScrollViewportBounds.height
                                - thumbHeight
                                - clampedY)
                        / maxThumbTravel;
        customMenuScrollOffset = MathUtils.clamp(scrollRatio * maxScroll, 0f, maxScroll);
        updateCustomMenuScrollbarBounds();
    }

    private void handleCustomGameMenuClick(float x, float y) {
        if (customStartBounds.contains(x, y)) {
            startCustomGameSelection();
            return;
        }
        if (customBackBounds.contains(x, y)) {
            openNewGameTierMenu();
            return;
        }
        if (!customMenuScrollViewportBounds.contains(x, y)) {
            return;
        }
        RogueliteSlotType[] cardTypes = RogueliteSlotType.values();
        for (int tier = 1; tier <= RogueliteCardCatalog.MAX_CARD_TIER; tier++) {
            for (int typeIndex = 0; typeIndex < cardTypes.length; typeIndex++) {
                int index = customTierCardTypeIndex(tier, typeIndex);
                if (customTierCardTypeBounds[index].contains(x, y)) {
                    customGameRules.toggleTierCardType(tier, cardTypes[typeIndex]);
                    return;
                }
            }
            if (customTierUnlockDownBounds[tier - 1].contains(x, y)) {
                customGameRules.setTierUnlockLevel(
                        tier,
                        customGameRules.getTierUnlockLevel(tier)
                                - CUSTOM_TIER_UNLOCK_LEVEL_STEP);
                return;
            }
            if (customTierUnlockUpBounds[tier - 1].contains(x, y)) {
                customGameRules.setTierUnlockLevel(
                        tier,
                        customGameRules.getTierUnlockLevel(tier)
                                + CUSTOM_TIER_UNLOCK_LEVEL_STEP);
                return;
            }
        }
        WeatherType[] weatherTypes = WeatherType.values();
        for (int i = 0; i < customWeatherBounds.length; i++) {
            if (customWeatherBounds[i].contains(x, y)) {
                customGameRules.toggleWeather(weatherTypes[i]);
                return;
            }
        }
        for (int i = 0; i < customMapBounds.size; i++) {
            if (customMapBounds.get(i).contains(x, y)) {
                customGameRules.toggleMap(customGameMenuMaps.get(i).getId());
                return;
            }
        }
        if (customLapsDownBounds.contains(x, y)) {
            customGameRules.setLaps(customGameRules.getLaps() - 1);
        } else if (customLapsUpBounds.contains(x, y)) {
            customGameRules.setLaps(customGameRules.getLaps() + 1);
        } else if (customXpDownBounds.contains(x, y)) {
            customGameRules.setLevelXpIncrement(
                    customGameRules.getLevelXpIncrement()
                            - CUSTOM_XP_INCREMENT_STEP);
        } else if (customXpUpBounds.contains(x, y)) {
            customGameRules.setLevelXpIncrement(
                    customGameRules.getLevelXpIncrement()
                            + CUSTOM_XP_INCREMENT_STEP);
        } else if (customLapXpCapDownBounds.contains(x, y)) {
            customGameRules.setRacecraftXpPerLapCap(
                    customGameRules.getRacecraftXpPerLapCap()
                            - CUSTOM_LAP_XP_CAP_STEP);
        } else if (customLapXpCapUpBounds.contains(x, y)) {
            customGameRules.setRacecraftXpPerLapCap(
                    customGameRules.getRacecraftXpPerLapCap()
                            + CUSTOM_LAP_XP_CAP_STEP);
        } else if (handleCustomRacecraftXpClick(x, y)) {
            return;
        }
    }

    private static int customTierCardTypeIndex(int tier, int typeIndex) {
        return (tier - 1) * RogueliteSlotType.values().length + typeIndex;
    }

    private boolean handleCustomRacecraftXpClick(float x, float y) {
        for (int i = 0; i < CUSTOM_RACECRAFT_XP_REASONS.length; i++) {
            Reason reason = CUSTOM_RACECRAFT_XP_REASONS[i];
            if (customRacecraftXpDownBounds[i].contains(x, y)) {
                customGameRules.setRacecraftXpAward(
                        reason,
                        customGameRules.getRacecraftXpAward(reason)
                                - CUSTOM_RACECRAFT_XP_STEP);
                return true;
            }
            if (customRacecraftXpUpBounds[i].contains(x, y)) {
                customGameRules.setRacecraftXpAward(
                        reason,
                        customGameRules.getRacecraftXpAward(reason)
                                + CUSTOM_RACECRAFT_XP_STEP);
                return true;
            }
        }
        return false;
    }

    private void refreshCustomGameMenuMaps() {
        customGameMenuMaps.clear();
        customGameMenuMaps.addAll(ArenaMaps.createDefaultCatalog());
        while (customMapBounds.size < customGameMenuMaps.size) {
            customMapBounds.add(new Rectangle());
        }
        while (customMapBounds.size > customGameMenuMaps.size) {
            customMapBounds.pop();
        }
    }

    private List<String> getCustomGameAvailableMapIds() {
        List<String> ids = new ArrayList<String>(customGameMenuMaps.size);
        for (int i = 0; i < customGameMenuMaps.size; i++) {
            ids.add(customGameMenuMaps.get(i).getId());
        }
        return ids;
    }

    private void changeMainMenuSelection(int direction) {
        int selection = MathUtils.clamp(
                mainMenuSelection + direction,
                MAIN_MENU_CONTINUE_SELECTION,
                MAIN_MENU_EXIT_SELECTION);
        if (!continueAvailable && selection == MAIN_MENU_CONTINUE_SELECTION) {
            selection = MAIN_MENU_NEW_GAME_SELECTION;
        }
        mainMenuSelection = selection;
    }

    private void handlePauseMenuInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.UP)
                || Gdx.input.isKeyJustPressed(Input.Keys.W)) {
            pauseMenuSelection = Math.max(0, pauseMenuSelection - 1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.DOWN)
                || Gdx.input.isKeyJustPressed(Input.Keys.S)) {
            pauseMenuSelection = Math.min(PAUSE_MENU_EXIT_SELECTION, pauseMenuSelection + 1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.O)) {
            openOptionsMenu(true);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            if (pauseMenuSelection == PAUSE_MENU_CONTINUE_SELECTION) {
                resumeGame();
            } else if (pauseMenuSelection == PAUSE_MENU_OPTIONS_SELECTION) {
                openOptionsMenu(true);
            } else if (pauseMenuSelection == PAUSE_MENU_MAIN_MENU_SELECTION) {
                returnToMainMenu();
            } else {
                Gdx.app.exit();
            }
        }
    }

    private void handleOptionsMenuInput() {
        ensureEnabledOptionsSelection();
        if (Gdx.input.isKeyJustPressed(Input.Keys.UP)
                || Gdx.input.isKeyJustPressed(Input.Keys.W)) {
            changeOptionsMenuSelection(-1);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.DOWN)
                || Gdx.input.isKeyJustPressed(Input.Keys.S)) {
            changeOptionsMenuSelection(1);
        }

        if (optionsMenuSelection == OPTIONS_DISPLAY_SELECTION) {
            if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.A)
                    || Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
                toggleDisplayMode();
            }
        } else if (optionsMenuSelection == OPTIONS_MUSIC_SELECTION) {
            if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
                changeMusicVolume(-1);
            }
            if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
                changeMusicVolume(1);
            }
        } else if (optionsMenuSelection == OPTIONS_SOUND_EFFECTS_SELECTION) {
            if (Gdx.input.isKeyJustPressed(Input.Keys.LEFT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.A)) {
                changeSoundEffectsVolume(-1);
            }
            if (Gdx.input.isKeyJustPressed(Input.Keys.RIGHT)
                    || Gdx.input.isKeyJustPressed(Input.Keys.D)) {
                changeSoundEffectsVolume(1);
            }
        }

        if (Gdx.input.isKeyJustPressed(Input.Keys.ENTER)
                || Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) {
            if (optionsMenuSelection == OPTIONS_DISPLAY_SELECTION) {
                toggleDisplayMode();
            } else if (optionsMenuSelection == OPTIONS_MUSIC_SELECTION) {
                changeMusicVolume(1);
            } else if (optionsMenuSelection == OPTIONS_SOUND_EFFECTS_SELECTION) {
                changeSoundEffectsVolume(1);
            } else if (optionsMenuSelection >= OPTIONS_LEFT_KEY_SELECTION
                    && optionsMenuSelection <= OPTIONS_RIGHT_KEY_SELECTION) {
                beginDrivingKeyBinding(actionForOptionsSelection(optionsMenuSelection));
            } else {
                closeOptionsMenu();
            }
        }
    }

    private void openPauseMenu() {
        clearPlayerInput();
        pauseMenuSelection = PAUSE_MENU_CONTINUE_SELECTION;
        optionsOpenedFromPause = false;
        gameMode = GameMode.PAUSE_MENU;
    }

    private void resumeGame() {
        clearPlayerInput();
        optionsOpenedFromPause = false;
        gameMode = GameMode.PLAYING;
    }

    private void restartCurrentGame() {
        clearPlayerInput();
        optionsOpenedFromPause = false;
        if (sandboxMode) {
            beginGameLoading(
                    true,
                    null,
                    1,
                    true,
                    RogueliteCompetitionMode.CHAMPIONSHIP);
        } else {
            startNewGame(
                    false,
                    rogueliteRun.getStartingTier(),
                    competitionMode);
        }
    }

    private void returnToMainMenu() {
        clearPlayerInput();
        persistCurrentRogueliteState();
        optionsOpenedFromPause = false;
        mainMenuSelection = MAIN_MENU_NEW_GAME_SELECTION;
        disposeGameSounds();
        disposeArenaSurfaceTextures();
        disposeRacePresentationTextures();
        releaseGameplayMaps();
        releaseSandboxMenuPreview();
        gameMode = GameMode.MAIN_MENU;
        loadMenuMusic();
        resize(Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
    }

    private void openOptionsMenu(boolean fromPause) {
        optionsOpenedFromPause = fromPause;
        pendingDrivingKeyBinding = null;
        optionsInputSuppressionFrames = 0;
        gameMode = GameMode.OPTIONS_MENU;
        optionsMenuSelection = OPTIONS_DISPLAY_SELECTION;
        ensureEnabledOptionsSelection();
    }

    private void editPlayerName() {
        playerNameEditor.begin(playerName);
        playerNameCommitRequested = false;
        playerNameCancelRequested = false;
        Gdx.input.setOnscreenKeyboardVisible(true);
    }

    private void commitPlayerNameEdit() {
        playerName = playerNameEditor.commit();
        playerNameCommitRequested = false;
        playerNameCancelRequested = false;
        Gdx.input.setOnscreenKeyboardVisible(false);
        saveMenuSettings();
    }

    private void cancelPlayerNameEdit() {
        playerNameEditor.cancel();
        playerNameCommitRequested = false;
        playerNameCancelRequested = false;
        Gdx.input.setOnscreenKeyboardVisible(false);
    }

    private void openNewGameTierMenu() {
        newGameMenuSelection =
                selectedCompetitionMode.isCustom()
                                ? NEW_GAME_CUSTOM_SELECTION
                                : MathUtils.clamp(
                                        selectedStartingTier - 1,
                                        0,
                                        NEW_GAME_TIER_OPTION_COUNT - 1);
        gameMode = GameMode.NEW_GAME_TIER_MENU;
    }

    private void openPreviousNewGameMenu() {
        if (playerNameEditor.isEditing()) {
            cancelPlayerNameEdit();
        }
        if (selectedCompetitionMode.isCustom()) {
            gameMode = GameMode.CUSTOM_GAME_MENU;
        } else {
            openNewGameTierMenu();
        }
    }

    private void openCustomGameMenu() {
        refreshCustomGameMenuMaps();
        List<String> availableMapIds = getCustomGameAvailableMapIds();
        if (!customGameRulesInitialized) {
            customGameRules.resetMaps(availableMapIds);
            customGameRulesInitialized = true;
        } else {
            customGameRules.reconcileMaps(availableMapIds);
        }
        customMenuScrollOffset = 0f;
        cancelCustomGameMenuPointerInput();
        selectedCompetitionMode = RogueliteCompetitionMode.CUSTOM;
        gameMode = GameMode.CUSTOM_GAME_MENU;
    }

    private void startCustomGameSelection() {
        selectedCompetitionMode = RogueliteCompetitionMode.CUSTOM;
        selectedStartingTier = 1;
        openNewGameCarMenu();
    }

    private void openNewGameCarMenu() {
        ensureMenuCarPreviewLoaded();
        newGameCarMenuSelection = NEW_GAME_CAR_START_SELECTION;
        gameMode = GameMode.NEW_GAME_CAR_MENU;
    }

    private void openSandboxMapsMenu() {
        refreshSandboxMenuMaps();
        mapsMenuReturnMode = GameMode.PLAYING;
        gameMode = GameMode.MAPS_MENU;
    }

    private void closeMapsMenu() {
        releaseSandboxMenuPreview();
        gameMode = mapsMenuReturnMode;
    }

    private void closeNewGameTierMenu() {
        gameMode = GameMode.MAIN_MENU;
        mainMenuSelection = MAIN_MENU_NEW_GAME_SELECTION;
    }

    private void closeOptionsMenu() {
        pendingDrivingKeyBinding = null;
        if (optionsOpenedFromPause) {
            optionsOpenedFromPause = false;
            gameMode = GameMode.PAUSE_MENU;
            pauseMenuSelection = PAUSE_MENU_OPTIONS_SELECTION;
        } else {
            gameMode = GameMode.MAIN_MENU;
            mainMenuSelection = MAIN_MENU_OPTIONS_SELECTION;
        }
    }

    private void clearPlayerInput() {
        frameThrottleInput = 0f;
        frameTurnInput = 0f;
        frameTurnOverrideActive = false;
        frameLeftInputActive = false;
        frameRightInputActive = false;
        touchThrottleInput = 0f;
        touchTurnInput = 0f;
        touchThrottleOverrideActive = false;
        touchTurnOverrideActive = false;
        touchRestartPressed = false;
        touchRestartJustPressed = false;
    }

    private void ensureEnabledOptionsSelection() {
        if (isOptionSelectionEnabled(optionsMenuSelection)) {
            return;
        }

        for (int selection = 0; selection <= OPTIONS_BACK_SELECTION; selection++) {
            if (isOptionSelectionEnabled(selection)) {
                optionsMenuSelection = selection;
                return;
            }
        }
        optionsMenuSelection = OPTIONS_BACK_SELECTION;
    }

    private void changeOptionsMenuSelection(int direction) {
        int selection = optionsMenuSelection;
        for (int i = 0; i <= OPTIONS_BACK_SELECTION; i++) {
            selection += direction;
            if (selection < 0) {
                selection = OPTIONS_BACK_SELECTION;
            } else if (selection > OPTIONS_BACK_SELECTION) {
                selection = 0;
            }

            if (isOptionSelectionEnabled(selection)) {
                optionsMenuSelection = selection;
                return;
            }
        }
    }

    private boolean isOptionSelectionEnabled(int selection) {
        if (selection == OPTIONS_DISPLAY_SELECTION) {
            return isDesktopDisplayOptionAvailable();
        }
        if (selection >= OPTIONS_LEFT_KEY_SELECTION
                && selection <= OPTIONS_RIGHT_KEY_SELECTION) {
            return isDesktopDisplayOptionAvailable();
        }
        return true;
    }

    private void beginDrivingKeyBinding(Action action) {
        if (action != null && isDesktopDisplayOptionAvailable()) {
            pendingDrivingKeyBinding = action;
        }
    }

    private static Action actionForOptionsSelection(int selection) {
        switch (selection) {
            case OPTIONS_LEFT_KEY_SELECTION:
                return Action.LEFT;
            case OPTIONS_RIGHT_KEY_SELECTION:
                return Action.RIGHT;
            default:
                return null;
        }
    }

    private void handleMenuClick(float x, float y) {
        if (gameMode == GameMode.MAIN_MENU) {
            for (int i = 0; i < menuLanguageFlagBounds.length; i++) {
                if (menuLanguageFlagBounds[i].contains(x, y)) {
                    selectLanguage(GameLanguage.values()[i]);
                    return;
                }
            }
            if (menuThemePrevBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_THEME_SELECTION;
                cycleTheme(-1);
            } else if (menuThemeNextBounds.contains(x, y)
                    || menuThemeBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_THEME_SELECTION;
                cycleTheme(1);
            } else if (menuNewGameBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_NEW_GAME_SELECTION;
                openNewGameTierMenu();
            } else if (continueAvailable && menuContinueBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_CONTINUE_SELECTION;
                continueSavedGame();
            } else if (menuSandboxBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_SANDBOX_SELECTION;
                startSandboxGame();
            } else if (menuOptionsBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_OPTIONS_SELECTION;
                openOptionsMenu(false);
            } else if (menuExitBounds.contains(x, y)) {
                mainMenuSelection = MAIN_MENU_EXIT_SELECTION;
                Gdx.app.exit();
            }
            return;
        }

        if (gameMode == GameMode.MAPS_MENU) {
            if (mapDebugPrevBounds.contains(x, y)) {
                changeSandboxMapSelection(-1);
            } else if (mapDebugNextBounds.contains(x, y)) {
                changeSandboxMapSelection(1);
            } else if (mapDebugBackBounds.contains(x, y)) {
                closeMapsMenu();
            }
            return;
        }

        if (gameMode == GameMode.NEW_GAME_TIER_MENU) {
            for (int i = 0; i < newGameTierBounds.length; i++) {
                if (newGameTierBounds[i].contains(x, y)) {
                    newGameMenuSelection = i;
                    selectedCompetitionMode = RogueliteCompetitionMode.CHAMPIONSHIP;
                    selectedStartingTier = i + 1;
                    openNewGameCarMenu();
                    return;
                }
            }
            if (newGameCustomBounds.contains(x, y)) {
                newGameMenuSelection = NEW_GAME_CUSTOM_SELECTION;
                openCustomGameMenu();
                return;
            }
            if (newGameTierBackBounds.contains(x, y)) {
                newGameMenuSelection = NEW_GAME_TIER_BACK_SELECTION;
                closeNewGameTierMenu();
            }
            return;
        }

        if (gameMode == GameMode.CUSTOM_GAME_MENU) {
            handleCustomGameMenuClick(x, y);
            return;
        }

        if (gameMode == GameMode.NEW_GAME_CAR_MENU) {
            if (playerNameEditor.isEditing()) {
                if (newGamePlayerNameBounds.contains(x, y)) {
                    return;
                }
                commitPlayerNameEdit();
            }
            if (newGamePlayerNameBounds.contains(x, y)) {
                newGameCarMenuSelection = NEW_GAME_CAR_NAME_SELECTION;
                editPlayerName();
            } else if (newGameCarPrevBounds.contains(x, y)) {
                changePlayerCar(-1);
            } else if (newGameCarNextBounds.contains(x, y)) {
                changePlayerCar(1);
            } else if (newGameCarStartBounds.contains(x, y)) {
                newGameCarMenuSelection = NEW_GAME_CAR_START_SELECTION;
                startNewGame();
            } else if (newGameCarBackBounds.contains(x, y)) {
                newGameCarMenuSelection = NEW_GAME_CAR_BACK_SELECTION;
                openPreviousNewGameMenu();
            }
            return;
        }

        if (gameMode == GameMode.PAUSE_MENU) {
            if (pauseContinueBounds.contains(x, y)) {
                pauseMenuSelection = PAUSE_MENU_CONTINUE_SELECTION;
                resumeGame();
            } else if (pauseOptionsBounds.contains(x, y)) {
                pauseMenuSelection = PAUSE_MENU_OPTIONS_SELECTION;
                openOptionsMenu(true);
            } else if (pauseMainMenuBounds.contains(x, y)) {
                pauseMenuSelection = PAUSE_MENU_MAIN_MENU_SELECTION;
                returnToMainMenu();
            } else if (pauseExitBounds.contains(x, y)) {
                pauseMenuSelection = PAUSE_MENU_EXIT_SELECTION;
                Gdx.app.exit();
            }
            return;
        }

        if (isDesktopDisplayOptionAvailable()
                && optionsDisplayBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_DISPLAY_SELECTION;
            toggleDisplayMode();
        } else if (optionsMusicDownBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_MUSIC_SELECTION;
            changeMusicVolume(-1);
        } else if (optionsMusicUpBounds.contains(x, y) || optionsMusicBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_MUSIC_SELECTION;
            changeMusicVolume(1);
        } else if (optionsSoundEffectsDownBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_SOUND_EFFECTS_SELECTION;
            changeSoundEffectsVolume(-1);
        } else if (optionsSoundEffectsUpBounds.contains(x, y)
                || optionsSoundEffectsBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_SOUND_EFFECTS_SELECTION;
            changeSoundEffectsVolume(1);
        } else if (isDesktopDisplayOptionAvailable()
                && optionsLeftKeyBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_LEFT_KEY_SELECTION;
            beginDrivingKeyBinding(Action.LEFT);
        } else if (isDesktopDisplayOptionAvailable()
                && optionsRightKeyBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_RIGHT_KEY_SELECTION;
            beginDrivingKeyBinding(Action.RIGHT);
        } else if (optionsBackBounds.contains(x, y)) {
            optionsMenuSelection = OPTIONS_BACK_SELECTION;
            closeOptionsMenu();
        }
    }

    private void updateMenuLayout(float hudWidth, float hudHeight) {
        float width = Math.max(1f, hudWidth);
        float height = Math.max(1f, hudHeight);
        float centerX = width * 0.5f;
        float availableWidth = Math.max(1f, width - MENU_MIN_SIDE_MARGIN * 2f);
        float minimumTouchTarget =
                RogueliteResponsiveCardLayout.minimumTouchTarget(width, height);
        boolean shortScreenLandscape =
                RogueliteResponsiveCardLayout.isShortLandscape(width, height);
        float mainMenuMargin =
                MathUtils.clamp(Math.min(width, height) * 0.045f, MENU_MIN_SIDE_MARGIN, 58f);
        float mainMenuBottom = shortScreenLandscape ? 8f : mainMenuMargin;
        float buttonWidth =
                Math.min(
                        availableWidth,
                        Math.min(MENU_BUTTON_WIDTH, Math.max(280f, width * 0.72f)));
        float menuButtonHeight =
                RogueliteResponsiveCardLayout.mainMenuButtonHeight(height);
        float menuButtonGap =
                shortScreenLandscape
                        ? 3f
                        : Math.min(MENU_BUTTON_GAP, Math.max(8f, height * 0.025f));
        float buttonX = width - mainMenuMargin - buttonWidth;
        float centeredButtonX = centerX - buttonWidth * 0.5f;
        float menuRowStride = menuButtonHeight + menuButtonGap;
        if (shortScreenLandscape) {
            float commandColumnGap = Math.max(8f, menuButtonGap * 2f);
            float commandButtonWidth = (buttonWidth - commandColumnGap) * 0.5f;
            float topY = mainMenuBottom + menuRowStride * 3f;
            float rightColumnX = buttonX + commandButtonWidth + commandColumnGap;
            menuContinueBounds.set(buttonX, topY, buttonWidth, menuButtonHeight);
            menuNewGameBounds.set(
                    buttonX,
                    topY - menuRowStride,
                    commandButtonWidth,
                    menuButtonHeight);
            menuSandboxBounds.set(
                    rightColumnX,
                    topY - menuRowStride,
                    commandButtonWidth,
                    menuButtonHeight);
            menuOptionsBounds.set(
                    buttonX,
                    topY - menuRowStride * 2f,
                    buttonWidth,
                    menuButtonHeight);
            menuThemeBounds.set(
                    buttonX,
                    topY - menuRowStride * 3f,
                    commandButtonWidth,
                    menuButtonHeight);
            menuExitBounds.set(
                    rightColumnX,
                    topY - menuRowStride * 3f,
                    commandButtonWidth,
                    menuButtonHeight);
        } else {
            float topY = mainMenuBottom + menuRowStride * 5f;
            menuContinueBounds.set(buttonX, topY, buttonWidth, menuButtonHeight);
            menuNewGameBounds.set(
                    buttonX,
                    topY - menuRowStride,
                    buttonWidth,
                    menuButtonHeight);
            menuSandboxBounds.set(
                    buttonX,
                    topY - menuRowStride * 2f,
                    buttonWidth,
                    menuButtonHeight);
            menuOptionsBounds.set(
                    buttonX,
                    topY - menuRowStride * 3f,
                    buttonWidth,
                    menuButtonHeight);
            menuThemeBounds.set(
                    buttonX,
                    topY - menuRowStride * 4f,
                    buttonWidth,
                    menuButtonHeight);
            menuExitBounds.set(
                    buttonX,
                    topY - menuRowStride * 5f,
                    buttonWidth,
                    menuButtonHeight);
        }
        float themeStepWidth = Math.min(menuThemeBounds.width * 0.24f, menuButtonHeight);
        menuThemePrevBounds.set(
                menuThemeBounds.x,
                menuThemeBounds.y,
                themeStepWidth,
                menuThemeBounds.height);
        menuThemeNextBounds.set(
                menuThemeBounds.x + menuThemeBounds.width - themeStepWidth,
                menuThemeBounds.y,
                themeStepWidth,
                menuThemeBounds.height);

        float languageButtonHeight =
                Math.max(minimumTouchTarget, MathUtils.clamp(height * 0.065f, 44f, 58f));
        float languageButtonGap = MathUtils.clamp(width * 0.006f, 4f, 10f);
        float languageButtonsAvailableWidth = Math.max(1f, width - mainMenuMargin * 2f);
        float languageButtonWidth =
                Math.min(
                        languageButtonHeight * 1.38f,
                        (languageButtonsAvailableWidth
                                        - languageButtonGap
                                                * (menuLanguageFlagBounds.length - 1))
                                / menuLanguageFlagBounds.length);
        float languageButtonsWidth =
                languageButtonWidth * menuLanguageFlagBounds.length
                        + languageButtonGap * (menuLanguageFlagBounds.length - 1);
        float languageButtonsY = height - mainMenuMargin - languageButtonHeight;
        float languageButtonsX = width - mainMenuMargin - languageButtonsWidth;
        for (int i = 0; i < menuLanguageFlagBounds.length; i++) {
            menuLanguageFlagBounds[i].set(
                    languageButtonsX + i * (languageButtonWidth + languageButtonGap),
                    languageButtonsY,
                    languageButtonWidth,
                    languageButtonHeight);
        }

        float mapControlSize =
                Math.max(
                        minimumTouchTarget,
                        MathUtils.clamp(menuButtonHeight, 42f, 56f));
        float mapBackWidth = Math.min(220f, availableWidth * 0.45f);
        float mapControlGap = MathUtils.clamp(width * 0.012f, 10f, 22f);
        float mapControlsWidth = mapControlSize * 2f + mapBackWidth + mapControlGap * 2f;
        float mapControlsX = centerX - mapControlsWidth * 0.5f;
        float mapControlsY = mainMenuMargin;
        mapDebugPrevBounds.set(
                mapControlsX,
                mapControlsY,
                mapControlSize,
                mapControlSize);
        mapDebugBackBounds.set(
                mapControlsX + mapControlSize + mapControlGap,
                mapControlsY,
                mapBackWidth,
                mapControlSize);
        mapDebugNextBounds.set(
                mapDebugBackBounds.x + mapBackWidth + mapControlGap,
                mapControlsY,
                mapControlSize,
                mapControlSize);
        float mapPreviewBottom = mapControlsY + mapControlSize + 44f;
        float mapPreviewTop = height - Math.max(92f, height * 0.11f);
        float mapPreviewHeight = Math.max(120f, mapPreviewTop - mapPreviewBottom);
        float mapPreviewWidth = Math.min(width - mainMenuMargin * 2f, mapPreviewHeight * 1.7f);
        mapDebugPreviewBounds.set(
                centerX - mapPreviewWidth * 0.5f,
                mapPreviewBottom,
                mapPreviewWidth,
                mapPreviewHeight);

        float tierButtonWidth = Math.min(MENU_OPTION_ROW_WIDTH, availableWidth);
        int newGameRowCount = NEW_GAME_TIER_OPTION_COUNT + 2;
        float tierButtonGap = Math.min(10f, Math.max(4f, height * 0.010f));
        float availableTierHeight = Math.max(224f, height - 150f);
        float tierButtonHeight =
                Math.max(
                        minimumTouchTarget,
                        Math.min(
                                52f,
                                Math.max(
                                        30f,
                                        (availableTierHeight
                                                        - tierButtonGap
                                                                * (newGameRowCount - 1))
                                                / newGameRowCount)));
        float tierGroupHeight =
                tierButtonHeight * newGameRowCount
                        + tierButtonGap * (newGameRowCount - 1);
        float tierGroupBottom =
                Math.max(
                        MENU_MIN_SIDE_MARGIN,
                        (height - tierGroupHeight) * 0.38f);
        float tierButtonX = centerX - tierButtonWidth * 0.5f;
        float tierFirstY = tierGroupBottom + tierGroupHeight - tierButtonHeight;
        for (int i = 0; i < newGameTierBounds.length; i++) {
            newGameTierBounds[i].set(
                    tierButtonX,
                    tierFirstY - i * (tierButtonHeight + tierButtonGap),
                    tierButtonWidth,
                    tierButtonHeight);
        }
        newGameCustomBounds.set(
                tierButtonX,
                tierFirstY
                        - NEW_GAME_CUSTOM_SELECTION
                                * (tierButtonHeight + tierButtonGap),
                tierButtonWidth,
                tierButtonHeight);
        newGameTierBackBounds.set(
                tierButtonX,
                tierFirstY
                        - NEW_GAME_TIER_BACK_SELECTION
                                * (tierButtonHeight + tierButtonGap),
                tierButtonWidth,
                tierButtonHeight);

        updateCustomGameMenuLayout(width, height, minimumTouchTarget);

        float carControlHeight =
                Math.max(
                        minimumTouchTarget,
                        MathUtils.clamp(height * 0.055f, 42f, 56f));
        float carControlGap = MathUtils.clamp(width * 0.008f, 8f, 14f);
        float carActionsWidth = Math.min(MENU_OPTION_ROW_WIDTH, availableWidth);
        float carActionButtonWidth = (carActionsWidth - carControlGap) * 0.5f;
        float carActionX = centerX - carActionsWidth * 0.5f;
        float carActionY = MENU_MIN_SIDE_MARGIN;
        newGameCarStartBounds.set(
                carActionX,
                carActionY,
                carActionButtonWidth,
                carControlHeight);
        newGameCarBackBounds.set(
                carActionX + carActionButtonWidth + carControlGap,
                carActionY,
                carActionButtonWidth,
                carControlHeight);

        float carSelectorWidth = Math.min(MENU_OPTION_ROW_WIDTH, availableWidth);
        float carSelectorX = centerX - carSelectorWidth * 0.5f;
        float playerNameY = carActionY + carControlHeight + carControlGap;
        newGamePlayerNameBounds.set(
                carSelectorX,
                playerNameY,
                carSelectorWidth,
                carControlHeight);
        float carSelectorY = playerNameY + carControlHeight + carControlGap;
        float carStepWidth =
                Math.max(
                        minimumTouchTarget,
                        Math.min(
                                MENU_OPTION_STEP_BUTTON_WIDTH,
                                Math.max(34f, carSelectorWidth * 0.16f)));
        newGameCarPrevBounds.set(
                carSelectorX,
                carSelectorY,
                carStepWidth,
                carControlHeight);
        newGameCarNextBounds.set(
                carSelectorX + carSelectorWidth - carStepWidth,
                carSelectorY,
                carStepWidth,
                carControlHeight);
        newGameCarNameBounds.set(
                newGameCarPrevBounds.x + newGameCarPrevBounds.width + carControlGap,
                carSelectorY,
                Math.max(
                        1f,
                        carSelectorWidth
                                - carStepWidth * 2f
                                - carControlGap * 2f),
                carControlHeight);

        float carPreviewBottom = carSelectorY + carControlHeight + 18f;
        float carPreviewTop = height - Math.max(88f, height * 0.10f);
        float carPreviewHeight = Math.max(90f, carPreviewTop - carPreviewBottom);
        float carPreviewWidth =
                Math.min(
                        Math.min(620f, availableWidth * 0.72f),
                        carPreviewHeight * 0.90f);
        newGameCarPreviewBounds.set(
                centerX - carPreviewWidth * 0.5f,
                carPreviewBottom,
                carPreviewWidth,
                carPreviewHeight);

        float pauseFirstButtonY =
                Math.max(
                        height * 0.49f,
                        MENU_MIN_SIDE_MARGIN + (menuButtonHeight + menuButtonGap) * 3f);
        pauseContinueBounds.set(centeredButtonX, pauseFirstButtonY, buttonWidth, menuButtonHeight);
        pauseMainMenuBounds.set(
                centeredButtonX,
                pauseFirstButtonY - menuButtonHeight - menuButtonGap,
                buttonWidth,
                menuButtonHeight);
        pauseOptionsBounds.set(
                centeredButtonX,
                pauseFirstButtonY - (menuButtonHeight + menuButtonGap) * 2f,
                buttonWidth,
                menuButtonHeight);
        pauseExitBounds.set(
                centeredButtonX,
                pauseFirstButtonY - (menuButtonHeight + menuButtonGap) * 3f,
                buttonWidth,
                menuButtonHeight);

        boolean desktopDisplayOption = isDesktopDisplayOptionAvailable();
        int rowCount = desktopDisplayOption ? OPTIONS_BACK_SELECTION + 1 : 3;
        boolean twoColumnOptions =
                RogueliteResponsiveCardLayout.isShortLandscape(width, height);
        int optionsColumns = twoColumnOptions ? 2 : 1;
        int optionRowsPerColumn = (rowCount + optionsColumns - 1) / optionsColumns;
        float optionsTitleBand =
                twoColumnOptions ? 68f : Math.max(74f, height * 0.14f);
        float preferredRowGap = Math.min(MENU_BUTTON_GAP, Math.max(6f, height * 0.025f));
        float availableRowsHeight = Math.max(
                optionRowsPerColumn * minimumTouchTarget,
                height - MENU_MIN_SIDE_MARGIN - optionsTitleBand);
        float rowGap = Math.min(
                preferredRowGap,
                Math.max(3f, availableRowsHeight * 0.018f));
        float rowHeight =
                Math.max(
                        minimumTouchTarget,
                        Math.min(
                                MENU_OPTION_ROW_HEIGHT,
                                (availableRowsHeight
                                                - rowGap * (optionRowsPerColumn - 1))
                                        / optionRowsPerColumn));
        float rowsHeight =
                rowHeight * optionRowsPerColumn
                        + rowGap * (optionRowsPerColumn - 1);
        float columnGap = twoColumnOptions ? MathUtils.clamp(width * 0.025f, 14f, 24f) : 0f;
        float rowWidth =
                Math.min(
                        MENU_OPTION_ROW_WIDTH,
                        (availableWidth - columnGap * (optionsColumns - 1))
                                / optionsColumns);
        float gridWidth = rowWidth * optionsColumns + columnGap * (optionsColumns - 1);
        float rowX = centerX - gridWidth * 0.5f;
        float rowTopY = height - optionsTitleBand;
        rowTopY = Math.max(rowTopY, MENU_MIN_SIDE_MARGIN + rowsHeight);

        float stepButtonWidth =
                Math.max(
                        minimumTouchTarget,
                        Math.min(
                                MENU_OPTION_STEP_BUTTON_WIDTH,
                                Math.max(32f, rowWidth * 0.18f)));
        stepButtonWidth = Math.min(stepButtonWidth, rowWidth * 0.26f);

        if (desktopDisplayOption) {
            setMenuOptionRowBounds(
                    optionsDisplayBounds,
                    0,
                    rowX,
                    rowTopY,
                    rowWidth,
                    rowHeight,
                    rowGap,
                    columnGap,
                    optionRowsPerColumn);
        } else {
            optionsDisplayBounds.set(0f, 0f, 0f, 0f);
        }
        int musicRow = desktopDisplayOption ? 1 : 0;
        int soundEffectsRow = desktopDisplayOption ? 2 : 1;
        int backRow = desktopDisplayOption ? OPTIONS_BACK_SELECTION : 2;
        setMenuOptionRowBounds(
                optionsMusicBounds,
                musicRow,
                rowX,
                rowTopY,
                rowWidth,
                rowHeight,
                rowGap,
                columnGap,
                optionRowsPerColumn);
        optionsMusicDownBounds.set(
                optionsMusicBounds.x,
                optionsMusicBounds.y,
                stepButtonWidth,
                rowHeight);
        optionsMusicUpBounds.set(
                optionsMusicBounds.x + rowWidth - stepButtonWidth,
                optionsMusicBounds.y,
                stepButtonWidth,
                rowHeight);
        setMenuOptionRowBounds(
                optionsSoundEffectsBounds,
                soundEffectsRow,
                rowX,
                rowTopY,
                rowWidth,
                rowHeight,
                rowGap,
                columnGap,
                optionRowsPerColumn);
        optionsSoundEffectsDownBounds.set(
                optionsSoundEffectsBounds.x,
                optionsSoundEffectsBounds.y,
                stepButtonWidth,
                rowHeight);
        optionsSoundEffectsUpBounds.set(
                optionsSoundEffectsBounds.x + rowWidth - stepButtonWidth,
                optionsSoundEffectsBounds.y,
                stepButtonWidth,
                rowHeight);
        if (desktopDisplayOption) {
            setMenuOptionRowBounds(
                    optionsLeftKeyBounds,
                    OPTIONS_LEFT_KEY_SELECTION,
                    rowX,
                    rowTopY,
                    rowWidth,
                    rowHeight,
                    rowGap,
                    columnGap,
                    optionRowsPerColumn);
            setMenuOptionRowBounds(
                    optionsRightKeyBounds,
                    OPTIONS_RIGHT_KEY_SELECTION,
                    rowX,
                    rowTopY,
                    rowWidth,
                    rowHeight,
                    rowGap,
                    columnGap,
                    optionRowsPerColumn);
        } else {
            optionsLeftKeyBounds.set(0f, 0f, 0f, 0f);
            optionsRightKeyBounds.set(0f, 0f, 0f, 0f);
        }
        setMenuOptionRowBounds(
                optionsBackBounds,
                backRow,
                rowX,
                rowTopY,
                rowWidth,
                rowHeight,
                rowGap,
                columnGap,
                optionRowsPerColumn);
    }

    private void updateCustomGameMenuLayout(
            float width,
            float height,
            float minimumTouchTarget) {
        float margin = MathUtils.clamp(Math.min(width, height) * 0.025f, 10f, 28f);
        float contentWidth = Math.min(1120f, Math.max(1f, width - margin * 2f));
        float contentX = (width - contentWidth) * 0.5f;
        float gap = MathUtils.clamp(contentWidth * 0.009f, 6f, 12f);
        float rowHeight = Math.max(minimumTouchTarget, Math.min(48f, height * 0.067f));
        float actionY = Math.max(6f, margin * 0.5f);
        float actionWidth = (contentWidth - gap) * 0.5f;
        customStartBounds.set(contentX, actionY, actionWidth, rowHeight);
        customBackBounds.set(
                contentX + actionWidth + gap,
                actionY,
                actionWidth,
                rowHeight);

        float viewportBottom = actionY + rowHeight + gap + 4f;
        float viewportTop = height - Math.max(62f, height * 0.085f);
        customMenuScrollViewportBounds.set(
                contentX,
                viewportBottom,
                contentWidth,
                Math.max(1f, viewportTop - viewportBottom));

        float scrollbarSpace = 22f;
        float tableX = contentX;
        float tableWidth = Math.max(1f, contentWidth - scrollbarSpace);
        float topY = viewportTop + customMenuScrollOffset - 8f;
        float contentTop = topY;
        float sectionGap = 28f;

        float tierColumnWidth = MathUtils.clamp(tableWidth * 0.08f, 52f, 80f);
        float unlockColumnWidth = MathUtils.clamp(tableWidth * 0.18f, 132f, 190f);
        float typeColumnWidth =
                Math.max(
                        1f,
                        (tableWidth - tierColumnWidth - unlockColumnWidth)
                                / RogueliteSlotType.values().length);
        float cardHeaderY = topY - sectionGap - rowHeight;
        float columnX = tableX;
        customCardTableHeaderBounds[0].set(
                columnX,
                cardHeaderY,
                tierColumnWidth,
                rowHeight);
        columnX += tierColumnWidth;
        for (int typeIndex = 0;
                typeIndex < RogueliteSlotType.values().length;
                typeIndex++) {
            customCardTableHeaderBounds[typeIndex + 1].set(
                    columnX,
                    cardHeaderY,
                    typeColumnWidth,
                    rowHeight);
            columnX += typeColumnWidth;
        }
        customCardTableHeaderBounds[customCardTableHeaderBounds.length - 1].set(
                columnX,
                cardHeaderY,
                unlockColumnWidth,
                rowHeight);

        for (int tier = 1; tier <= RogueliteCardCatalog.MAX_CARD_TIER; tier++) {
            float rowY = cardHeaderY - tier * rowHeight;
            columnX = tableX;
            customTierLabelBounds[tier - 1].set(
                    columnX,
                    rowY,
                    tierColumnWidth,
                    rowHeight);
            columnX += tierColumnWidth;
            for (int typeIndex = 0;
                    typeIndex < RogueliteSlotType.values().length;
                    typeIndex++) {
                customTierCardTypeBounds[customTierCardTypeIndex(tier, typeIndex)].set(
                        columnX,
                        rowY,
                        typeColumnWidth,
                        rowHeight);
                columnX += typeColumnWidth;
            }
            setCustomTierUnlockBounds(
                    customTierUnlockBounds[tier - 1],
                    customTierUnlockDownBounds[tier - 1],
                    customTierUnlockUpBounds[tier - 1],
                    columnX,
                    rowY,
                    unlockColumnWidth,
                    rowHeight);
        }
        topY = cardHeaderY
                - RogueliteCardCatalog.MAX_CARD_TIER * rowHeight
                - sectionGap;

        layoutCustomGrid(
                customWeatherBounds,
                tableX,
                topY,
                tableWidth,
                rowHeight,
                gap,
                customWeatherBounds.length);
        topY -= rowHeight + gap + 18f;

        int numericColumns = 2;
        float numericWidth =
                (tableWidth - gap * (numericColumns - 1)) / numericColumns;
        int numericIndex = 0;
        setCustomNumericGridBounds(
                customLapsBounds,
                customLapsDownBounds,
                customLapsUpBounds,
                numericIndex++,
                numericColumns,
                tableX,
                topY,
                numericWidth,
                rowHeight,
                gap,
                minimumTouchTarget);
        setCustomNumericGridBounds(
                customXpBounds,
                customXpDownBounds,
                customXpUpBounds,
                numericIndex++,
                numericColumns,
                tableX,
                topY,
                numericWidth,
                rowHeight,
                gap,
                minimumTouchTarget);
        setCustomNumericGridBounds(
                customLapXpCapBounds,
                customLapXpCapDownBounds,
                customLapXpCapUpBounds,
                numericIndex++,
                numericColumns,
                tableX,
                topY,
                numericWidth,
                rowHeight,
                gap,
                minimumTouchTarget);
        for (int i = 0; i < CUSTOM_RACECRAFT_XP_REASONS.length; i++) {
            setCustomNumericGridBounds(
                    customRacecraftXpBounds[i],
                    customRacecraftXpDownBounds[i],
                    customRacecraftXpUpBounds[i],
                    numericIndex++,
                    numericColumns,
                    tableX,
                    topY,
                    numericWidth,
                    rowHeight,
                    gap,
                    minimumTouchTarget);
        }
        int numericRows = (numericIndex + numericColumns - 1) / numericColumns;
        topY -= numericRows * (rowHeight + gap) + 18f;

        int mapColumns = width >= 900f ? 4 : width >= 600f ? 3 : 2;
        float mapCellWidth =
                (tableWidth - gap * (mapColumns - 1)) / mapColumns;
        for (int i = 0; i < customMapBounds.size; i++) {
            int column = i % mapColumns;
            int row = i / mapColumns;
            customMapBounds.get(i).set(
                    tableX + column * (mapCellWidth + gap),
                    topY - (row + 1) * rowHeight - row * gap,
                    mapCellWidth,
                    rowHeight);
        }
        int mapRows = (customMapBounds.size + mapColumns - 1) / mapColumns;
        float contentBottom = topY - mapRows * (rowHeight + gap) - 8f;
        customMenuContentHeight = Math.max(
                customMenuScrollViewportBounds.height,
                contentTop - contentBottom);
        customMenuScrollOffset = MathUtils.clamp(
                customMenuScrollOffset,
                0f,
                getCustomMenuMaxScroll());
        updateCustomMenuScrollbarBounds();
    }

    private void setCustomTierUnlockBounds(
            Rectangle row,
            Rectangle decrease,
            Rectangle increase,
            float x,
            float y,
            float width,
            float height) {
        row.set(x, y, width, height);
        float stepWidth = Math.min(height, width * 0.30f);
        decrease.set(x, y, stepWidth, height);
        increase.set(x + width - stepWidth, y, stepWidth, height);
    }

    private void layoutCustomGrid(
            Rectangle[] bounds,
            float x,
            float topY,
            float width,
            float rowHeight,
            float gap,
            int columns) {
        int safeColumns = Math.max(1, columns);
        float cellWidth = (width - gap * (safeColumns - 1)) / safeColumns;
        for (int i = 0; i < bounds.length; i++) {
            int column = i % safeColumns;
            int row = i / safeColumns;
            bounds[i].set(
                    x + column * (cellWidth + gap),
                    topY - (row + 1) * rowHeight - row * gap,
                    cellWidth,
                    rowHeight);
        }
    }

    private void setCustomNumericBounds(
            Rectangle row,
            Rectangle decrease,
            Rectangle increase,
            float x,
            float y,
            float width,
            float height,
            float minimumTouchTarget) {
        row.set(x, y, width, height);
        float stepWidth = Math.min(width * 0.24f, Math.max(minimumTouchTarget, height));
        decrease.set(x, y, stepWidth, height);
        increase.set(x + width - stepWidth, y, stepWidth, height);
    }

    private void setCustomNumericGridBounds(
            Rectangle row,
            Rectangle decrease,
            Rectangle increase,
            int index,
            int columns,
            float x,
            float topY,
            float width,
            float height,
            float gap,
            float minimumTouchTarget) {
        int column = index % columns;
        int gridRow = index / columns;
        setCustomNumericBounds(
                row,
                decrease,
                increase,
                x + column * (width + gap),
                topY - (gridRow + 1) * height - gridRow * gap,
                width,
                height,
                minimumTouchTarget);
    }

    private void setMenuOptionRowBounds(
            Rectangle bounds,
            int index,
            float startX,
            float topY,
            float rowWidth,
            float rowHeight,
            float rowGap,
            float columnGap,
            int rowsPerColumn) {
        int column = index / rowsPerColumn;
        int row = index % rowsPerColumn;
        bounds.set(
                startX + column * (rowWidth + columnGap),
                topY - rowHeight - row * (rowHeight + rowGap),
                rowWidth,
                rowHeight);
    }

    private void cycleTheme(int direction) {
        if (themeChoices.size == 0) {
            loadThemeChoices();
        }
        if (themeChoices.size == 0) {
            return;
        }
        selectedThemeIndex = selectedThemeIndex + direction;
        if (selectedThemeIndex < 0) {
            selectedThemeIndex = themeChoices.size - 1;
        } else if (selectedThemeIndex >= themeChoices.size) {
            selectedThemeIndex = 0;
        }
        configuredThemeName = themeChoices.get(selectedThemeIndex).name;
        disposeMenuCarPreview();
        disposeMenuHeroCar();
        loadMenuMusic();
        saveMenuSettings();
    }

    private void changeCameraZoom(float direction) {
        float nextZoom =
                CameraZoomControl.step(
                        cameraZoom,
                        direction,
                        CAMERA_ZOOM_STEP,
                        MIN_CAMERA_ZOOM,
                        MAX_CAMERA_ZOOM);
        setCameraZoom(nextZoom, true);
    }

    private void scaleCameraZoom(float scale) {
        if (!Float.isFinite(scale) || scale <= 0f) {
            return;
        }
        setCameraZoom(
                CameraZoomControl.scale(
                        cameraZoom,
                        scale,
                        MIN_CAMERA_ZOOM,
                        MAX_CAMERA_ZOOM),
                false);
    }

    private void setCameraZoom(float nextZoom, boolean persist) {
        if (Math.abs(nextZoom - cameraZoom) < 0.001f) {
            return;
        }
        cameraZoom = nextZoom;
        if (persist) {
            saveMenuSettings();
        } else {
            cameraZoomGestureDirty = true;
        }
    }

    private boolean isDesktopDisplayOptionAvailable() {
        return Gdx.app != null && Gdx.app.getType() == ApplicationType.Desktop;
    }

    private void toggleDisplayMode() {
        if (!isDesktopDisplayOptionAvailable()) {
            return;
        }
        boolean requestedWindowedMode = !windowedMode;
        if (applyDisplayMode(requestedWindowedMode)) {
            windowedMode = requestedWindowedMode;
            saveMenuSettings();
        }
    }

    private void applyConfiguredDisplayMode() {
        if (!isDesktopDisplayOptionAvailable()) {
            return;
        }
        if (!applyDisplayMode(windowedMode)) {
            windowedMode = false;
        }
    }

    private boolean applyDisplayMode(boolean useWindowedMode) {
        if (Gdx.graphics == null) {
            return false;
        }
        try {
            DisplayMode displayMode = Gdx.graphics.getDisplayMode();
            if (!useWindowedMode) {
                return Gdx.graphics.setFullscreenMode(displayMode);
            }
            int width =
                    Math.max(
                            1,
                            Math.min(
                                    displayMode.width,
                                    Math.max(640, Math.round(displayMode.width * 0.80f))));
            int height =
                    Math.max(
                            1,
                            Math.min(
                                    displayMode.height,
                                    Math.max(480, Math.round(displayMode.height * 0.80f))));
            return Gdx.graphics.setWindowedMode(width, height);
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not change the desktop display mode.", exception);
            return false;
        }
    }

    private void changeMusicVolume(int direction) {
        float nextVolume = stepAudioVolume(musicVolume, direction);
        if (Math.abs(nextVolume - musicVolume) < 0.001f) {
            return;
        }
        musicVolume = nextVolume;
        applyMusicVolume();
        saveMenuSettings();
    }

    private void changeSoundEffectsVolume(int direction) {
        float nextVolume = stepAudioVolume(soundEffectsVolume, direction);
        if (Math.abs(nextVolume - soundEffectsVolume) < 0.001f) {
            return;
        }
        soundEffectsVolume = nextVolume;
        if (soundEffectsVolume <= 0f) {
            stopVehicleSounds();
        }
        saveMenuSettings();
    }

    private void selectLanguage(GameLanguage nextLanguage) {
        if (nextLanguage == gameLanguage) {
            return;
        }
        gameLanguage = nextLanguage;
        saveMenuSettings();
    }

    private static float stepAudioVolume(float volume, int direction) {
        float steppedVolume = volume + Math.signum(direction) * AUDIO_VOLUME_STEP;
        return Math.round(clampAudioVolume(steppedVolume) / AUDIO_VOLUME_STEP)
                * AUDIO_VOLUME_STEP;
    }

    private void handleCameraTargetInput() {
        if (Gdx.input.isKeyJustPressed(Input.Keys.PLUS)
                || Gdx.input.isKeyJustPressed(Input.Keys.EQUALS)
                || Gdx.input.isKeyJustPressed(Input.Keys.NUMPAD_ADD)) {
            changeCameraZoom(1f);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.MINUS)
                || Gdx.input.isKeyJustPressed(Input.Keys.NUMPAD_SUBTRACT)) {
            changeCameraZoom(-1f);
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.HOME)) {
            leaveFreeCameraForFollow();
            eventCameraSelected = false;
            resetCameraTargetToPlayer(true);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.PAGE_DOWN)) {
            changeCameraTarget(1);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.PAGE_UP)) {
            changeCameraTarget(-1);
            return;
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.TAB)) {
            boolean reverse =
                    Gdx.input.isKeyPressed(Input.Keys.SHIFT_LEFT)
                            || Gdx.input.isKeyPressed(Input.Keys.SHIFT_RIGHT);
            changeCameraTarget(reverse ? -1 : 1);
        }
    }

    private void changeCameraTarget(int direction) {
        if (direction == 0 || roster.size == 0) {
            return;
        }

        refreshLeaderboardEntries();
        if (leaderboardEntries.size == 0) {
            return;
        }

        int startIndex = findCameraTargetLeaderboardIndex();
        if (startIndex < 0) {
            startIndex = findPlayerLeaderboardIndex();
        }
        if (startIndex < 0) {
            startIndex = 0;
        }

        for (int step = 1; step <= leaderboardEntries.size; step++) {
            int nextIndex = wrapLeaderboardIndex(startIndex + direction * step);
            CarTemplate template = leaderboardEntries.get(nextIndex);
            if (template != null && isCameraFollowable(template.currentCar)) {
                selectPlayerCameraTarget(template, true);
                return;
            }
        }
    }

    private int wrapLeaderboardIndex(int index) {
        int wrapped = index % leaderboardEntries.size;
        return wrapped < 0 ? wrapped + leaderboardEntries.size : wrapped;
    }

    private void resetCameraTargetToPlayer(boolean animate) {
        int playerIndex = findPlayerRosterIndex();
        setCameraTargetRosterIndex(playerIndex >= 0 ? playerIndex : -1, animate);
    }

    private void followPlayerCarAfterSteeringTakeover() {
        boolean takeoverApplied =
                frameTurnOverrideActive
                        && playerCar != null
                        && playerCar.active
                        && playerCar.playerSteeringTakeoverApplied;
        if (!SteeringTakeoverIndicator.shouldClaimCamera(
                        isPresentationEnabled(),
                        isPlayerSteeringTakeoverModeEnabled(),
                        takeoverApplied)
                || playerCar.template == null) {
            return;
        }
        if (eventCameraSelected
                || cameraViewMode.isFree()
                || !isCameraTargetTemplate(playerCar.template)) {
            selectPlayerCameraTarget(playerCar.template, true);
        }
    }

    private boolean setCameraTargetTemplate(CarTemplate template, boolean animate) {
        if (template == null || !isCameraFollowable(template.currentCar)) {
            return false;
        }
        int rosterIndex = findRosterIndex(template);
        if (rosterIndex < 0) {
            return false;
        }
        leaveFreeCameraForFollow();
        setCameraTargetRosterIndex(rosterIndex, animate);
        return true;
    }

    private boolean selectPlayerCameraTarget(CarTemplate template, boolean animate) {
        if (!setCameraTargetTemplate(template, animate)) {
            return false;
        }
        eventCameraSelected = false;
        if (eventCameraDirector != null) {
            eventCameraDirector.reset();
        }
        return true;
    }

    private void selectEventCamera() {
        eventCameraSelected = true;
        leaveFreeCameraForFollow();
        lastAutoFollowedRaceIncidentSequence = -1L;
        eventCameraDirector.reset();
        if (isFinishWinnerCameraActive()
                && winner != null
                && winner.template != null) {
            setCameraTargetTemplate(winner.template, true);
        } else {
            updateEventCamera(0f);
        }
    }

    private void leaveFreeCameraForFollow() {
        if (!cameraViewMode.isFree()) {
            return;
        }
        cameraViewMode = CameraViewMode.TOP_DOWN;
        stopCameraGestures();
        freeCameraReturnHintTimer = 0f;
    }

    private void stopCameraGestures() {
        freeCameraDragging = false;
        freeCameraDragCandidate = false;
        freeCameraPointer = -1;
        minimapCameraPointer = -1;
        cameraPinching = false;
        cameraPinchDistance = 0f;
        finishCameraZoomGesture();
    }

    private void finishCameraZoomGesture() {
        if (!cameraZoomGestureDirty) {
            return;
        }
        cameraZoomGestureDirty = false;
        saveMenuSettings();
    }

    private void enterFreeCamera() {
        if (cameraViewMode.isFree()) {
            return;
        }
        cameraViewMode = CameraViewMode.FREE;
        eventCameraSelected = false;
        if (eventCameraDirector != null) {
            eventCameraDirector.reset();
        }
        freeCameraReturnHintTimer = FREE_CAMERA_RETURN_HINT_DURATION;
        cameraTargetTransitionTimer = 0f;
    }

    private boolean handleMinimapCameraInput() {
        if (!isPresentationEnabled()
                || gameMode != GameMode.PLAYING
                || currentMap == null) {
            minimapCameraPointer = -1;
            return false;
        }

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        float sidebarX = hudWidth - sidebarHudWidth;
        if (!getSidebarMinimapBounds(
                sidebarX,
                Math.max(0f, sidebarHudWidth),
                hudHeight,
                sidebarMinimapBounds)) {
            minimapCameraPointer = -1;
            return false;
        }

        currentMap.getBounds(mapBounds);
        if (!MinimapCameraNavigation.fitMap(
                        sidebarMinimapBounds,
                        SIDEBAR_MINIMAP_PADDING,
                        mapBounds,
                        sidebarMinimapMapBounds)) {
            minimapCameraPointer = -1;
            return false;
        }

        if (minimapCameraPointer < 0) {
            if (!Gdx.input.justTouched()) {
                return false;
            }
            int pointer = findTouchedPointer(sidebarMinimapMapBounds);
            if (pointer < 0) {
                return false;
            }
            stopCameraGestures();
            enterFreeCamera();
            minimapCameraPointer = pointer;
        } else if (!Gdx.input.isTouched(minimapCameraPointer)) {
            minimapCameraPointer = -1;
            return false;
        }

        hudTouchPoint.set(
                Gdx.input.getX(minimapCameraPointer),
                Gdx.input.getY(minimapCameraPointer),
                0f);
        hudViewport.unproject(hudTouchPoint);
        if (!MinimapCameraNavigation.worldPositionAt(
                hudTouchPoint.x,
                hudTouchPoint.y,
                sidebarMinimapMapBounds,
                mapBounds,
                cameraTargetPosition)) {
            return true;
        }

        cameraSmoothedPosition.set(cameraTargetPosition);
        cameraSmoothedForwardDirection.set(0f, 1f);
        clampCameraToArena(cameraSmoothedPosition, smoothedCameraZoom);
        cameraTargetPosition.set(cameraSmoothedPosition);
        cameraInitialized = true;
        cameraStateMap = currentMap;
        cameraTargetTransitionTimer = 0f;
        return true;
    }

    private void handleInteractiveCameraInput(boolean pointerConsumed) {
        if (!isPresentationEnabled()
                || gameMode != GameMode.PLAYING
                || worldCamera == null) {
            stopCameraGestures();
            return;
        }

        int firstPointer = pointerConsumed ? -1 : findCameraGesturePointer(-1);
        int secondPointer = firstPointer < 0 ? -1 : findCameraGesturePointer(firstPointer);
        if (secondPointer >= 0) {
            float deltaX = Gdx.input.getX(secondPointer) - Gdx.input.getX(firstPointer);
            float deltaY = Gdx.input.getY(secondPointer) - Gdx.input.getY(firstPointer);
            float pinchDistance = (float) Math.sqrt(deltaX * deltaX + deltaY * deltaY);
            if (cameraPinching && cameraPinchDistance > 1f && pinchDistance > 1f) {
                scaleCameraZoom(pinchDistance / cameraPinchDistance);
            }
            cameraPinching = true;
            cameraPinchDistance = pinchDistance;
            freeCameraDragging = false;
            freeCameraDragCandidate = false;
            freeCameraPointer = -1;
            return;
        }

        if (cameraPinching) {
            cameraPinching = false;
            cameraPinchDistance = 0f;
            finishCameraZoomGesture();
            freeCameraDragging = false;
            freeCameraDragCandidate = false;
            freeCameraPointer = -1;
            return;
        }

        if (freeCameraDragCandidate
                && freeCameraPointer >= 0
                && !Gdx.input.isTouched(freeCameraPointer)) {
            int tapScreenX = freeCameraDragStartScreenX;
            int tapScreenY = freeCameraDragStartScreenY;
            freeCameraDragCandidate = false;
            freeCameraPointer = -1;
            selectCameraTargetAtScreenPosition(tapScreenX, tapScreenY);
            return;
        }

        if (Gdx.input.justTouched()) {
            freeCameraDragging = false;
            freeCameraDragCandidate = firstPointer >= 0;
            freeCameraPointer = firstPointer;
            if (firstPointer >= 0) {
                freeCameraDragStartScreenX = Gdx.input.getX(firstPointer);
                freeCameraDragStartScreenY = Gdx.input.getY(firstPointer);
                freeCameraLastScreenX = freeCameraDragStartScreenX;
                freeCameraLastScreenY = freeCameraDragStartScreenY;
            }
        }

        if ((!freeCameraDragging && !freeCameraDragCandidate)
                || freeCameraPointer < 0
                || !Gdx.input.isTouched(freeCameraPointer)) {
            freeCameraDragging = false;
            freeCameraDragCandidate = false;
            freeCameraPointer = -1;
            return;
        }

        int screenX = Gdx.input.getX(freeCameraPointer);
        int screenY = Gdx.input.getY(freeCameraPointer);
        if (!freeCameraDragging) {
            float dragX = screenX - freeCameraDragStartScreenX;
            float dragY = screenY - freeCameraDragStartScreenY;
            if (dragX * dragX + dragY * dragY
                    < FREE_CAMERA_DRAG_THRESHOLD_PIXELS * FREE_CAMERA_DRAG_THRESHOLD_PIXELS) {
                return;
            }
            enterFreeCamera();
            freeCameraDragging = true;
            freeCameraDragCandidate = false;
        }

        int deltaX = screenX - freeCameraLastScreenX;
        int deltaY = screenY - freeCameraLastScreenY;
        freeCameraLastScreenX = screenX;
        freeCameraLastScreenY = screenY;
        if (deltaX == 0 && deltaY == 0) {
            return;
        }

        float screenWidth = Math.max(1f, worldViewport.getScreenWidth());
        float screenHeight = Math.max(1f, worldViewport.getScreenHeight());
        FreeCameraPan.applyDrag(
                cameraSmoothedPosition,
                deltaX,
                deltaY,
                worldCamera.viewportWidth,
                worldCamera.viewportHeight,
                worldCamera.zoom,
                screenWidth,
                screenHeight);
        cameraTargetPosition.set(cameraSmoothedPosition);
        clampCameraToArena(cameraSmoothedPosition, smoothedCameraZoom);
    }

    private boolean selectCameraTargetAtScreenPosition(int screenX, int screenY) {
        if (worldViewport == null || worldCamera == null) {
            return false;
        }
        worldTouchPoint.set(screenX, screenY, 0f);
        worldViewport.unproject(worldTouchPoint);

        float worldUnitsPerPixelX =
                worldCamera.viewportWidth
                        * worldCamera.zoom
                        / Math.max(1f, worldViewport.getScreenWidth());
        float worldUnitsPerPixelY =
                worldCamera.viewportHeight
                        * worldCamera.zoom
                        / Math.max(1f, worldViewport.getScreenHeight());
        float padding = CAR_CAMERA_TAP_PADDING_PIXELS
                * Math.max(worldUnitsPerPixelX, worldUnitsPerPixelY);
        Car selectedCar = null;
        float bestScore = Float.POSITIVE_INFINITY;
        for (int i = 0; i < cars.size; i++) {
            Car car = cars.get(i);
            if (!isCameraFollowable(car) || car.template == null) {
                continue;
            }
            Vector2 position = car.getRenderPosition();
            float score = CarCameraHitTest.hitScore(
                    worldTouchPoint.x,
                    worldTouchPoint.y,
                    position.x,
                    position.y,
                    car.getRenderAngleDeg() * MathUtils.degreesToRadians,
                    car.getWidth() * CAR_SPRITE_WIDTH_SCALE * 0.5f,
                    car.getHeight() * CAR_SPRITE_HEIGHT_SCALE * 0.5f,
                    padding);
            if (score < bestScore) {
                selectedCar = car;
                bestScore = score;
            }
        }
        return selectedCar != null
                && selectPlayerCameraTarget(selectedCar.template, true);
    }

    private int findCameraGesturePointer(int excludedPointer) {
        int maxPointers = Math.min(5, Gdx.input.getMaxPointers());
        for (int pointer = 0; pointer < maxPointers; pointer++) {
            if (pointer == excludedPointer || !Gdx.input.isTouched(pointer)) {
                continue;
            }
            hudTouchPoint.set(Gdx.input.getX(pointer), Gdx.input.getY(pointer), 0f);
            hudViewport.unproject(hudTouchPoint);
            if (isCameraGesturePoint(hudTouchPoint.x, hudTouchPoint.y)) {
                return pointer;
            }
        }
        return -1;
    }

    private boolean isCameraGesturePoint(float x, float y) {
        if (!isPointInPlayfield(x, y)) {
            return false;
        }
        if (touchControlsEnabled && steerPadBounds.contains(x, y)) {
            return false;
        }
        if (touchControlsEnabled
                && shouldShowTouchPedals()
                && (throttlePadBounds.contains(x, y)
                        || reversePadBounds.contains(x, y))) {
            return false;
        }
        return !sandboxMode || !sandboxSettingsBounds.contains(x, y);
    }

    private boolean isPointInPlayfield(float x, float y) {
        return x >= playfieldHudX
                && x <= playfieldHudX + playfieldHudWidth
                && y >= playfieldHudY
                && y <= playfieldHudY + playfieldHudHeight;
    }

    private void setCameraTargetRosterIndex(int rosterIndex, boolean animate) {
        if (cameraTargetRosterIndex == rosterIndex) {
            return;
        }
        cameraTargetRosterIndex = rosterIndex;
        if (animate && cameraInitialized) {
            cameraTargetTransitionStartPosition.set(cameraSmoothedPosition);
            cameraTargetTransitionStartZoom = smoothedCameraZoom;
            cameraTargetTransitionTimer = CAMERA_TARGET_SWITCH_DURATION;
        } else {
            cameraTargetTransitionTimer = 0f;
        }
    }

    private int findPlayerRosterIndex() {
        for (int i = 0; i < roster.size; i++) {
            CarTemplate template = roster.get(i);
            if (template.playerControlled) {
                return i;
            }
        }
        return -1;
    }

    private int findRosterIndex(CarTemplate target) {
        if (target == null) {
            return -1;
        }
        for (int i = 0; i < roster.size; i++) {
            if (roster.get(i) == target) {
                return i;
            }
        }
        return -1;
    }

    private int findCameraTargetLeaderboardIndex() {
        Car cameraTarget = getCameraTargetCar();
        if (cameraTarget == null || cameraTarget.template == null) {
            return -1;
        }
        return findLeaderboardIndex(cameraTarget.template);
    }

    private int findPlayerLeaderboardIndex() {
        for (int i = 0; i < leaderboardEntries.size; i++) {
            CarTemplate template = leaderboardEntries.get(i);
            if (template.playerControlled) {
                return i;
            }
        }
        return -1;
    }

    private int findLeaderboardIndex(CarTemplate target) {
        if (target == null) {
            return -1;
        }
        for (int i = 0; i < leaderboardEntries.size; i++) {
            if (leaderboardEntries.get(i) == target) {
                return i;
            }
        }
        return -1;
    }

    private Car getCameraTargetCar() {
        if (cameraTargetRosterIndex >= 0 && cameraTargetRosterIndex < roster.size) {
            Car car = roster.get(cameraTargetRosterIndex).currentCar;
            if (isCameraFollowable(car)) {
                return car;
            }
        }
        if (isCameraFollowable(playerCar)) {
            return playerCar;
        }
        for (int i = 0; i < roster.size; i++) {
            Car car = roster.get(i).currentCar;
            if (isCameraFollowable(car)) {
                return car;
            }
        }
        return null;
    }

    private CarTemplate getCameraTargetTemplate() {
        Car target = getCameraTargetCar();
        if (target != null && target.template != null) {
            return target.template;
        }
        return roster.size == 0 ? null : roster.first();
    }

    private boolean isCameraFollowable(Car car) {
        return car != null
                && car.active
                && car.body != null
                && car.hasFiniteMotionAndRenderTransform();
    }

    private boolean isCameraTargetTemplate(CarTemplate template) {
        Car target = getCameraTargetCar();
        return target != null && target.template == template;
    }

    private void changeSandboxCarCount(int delta) {
        selectedSandboxCarCount = clampCarCount(selectedSandboxCarCount + delta);
        saveMenuSettings();
    }

    private void changePlayerCar(int delta) {
        ensureMenuCarPreviewLoaded();
        int carCount = getMenuSelectableCarCount();
        if (carCount <= 0) {
            return;
        }

        selectedPlayerCarIndex += delta;
        while (selectedPlayerCarIndex < 0) {
            selectedPlayerCarIndex += carCount;
        }
        while (selectedPlayerCarIndex >= carCount) {
            selectedPlayerCarIndex -= carCount;
        }
        disposeMenuHeroCar();
        saveMenuSettings();
    }

    private void changeSandboxControlMode() {
        sandboxLoadoutConfiguration.cycleControlMode();
        if (sandboxLoadoutConfiguration.isAutomatic()) {
            touchThrottleInput = 0f;
            touchTurnInput = 0f;
            selectEventCamera();
        } else {
            eventCameraSelected = false;
            eventCameraDirector.reset();
            resetCameraTargetToPlayer(true);
        }
        applySandboxConfigurationToCars();
    }

    private void renderMenu() {
        hudViewport.apply();
        clearPresentationArea(0.045f, 0.055f, 0.065f, 1f);
        shapeRenderer.setProjectionMatrix(hudCamera.combined);
        spriteBatch.setProjectionMatrix(hudCamera.combined);

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        drawMenuBackdrop(hudWidth, hudHeight);

        if (gameMode == GameMode.MAIN_MENU) {
            drawMainMenu(hudWidth, hudHeight);
        } else if (gameMode == GameMode.NEW_GAME_TIER_MENU) {
            drawNewGameTierMenu(hudWidth, hudHeight);
        } else if (gameMode == GameMode.CUSTOM_GAME_MENU) {
            drawCustomGameMenu(hudWidth, hudHeight);
        } else if (gameMode == GameMode.NEW_GAME_CAR_MENU) {
            drawNewGameCarMenu(hudWidth, hudHeight);
        } else if (gameMode == GameMode.MAPS_MENU) {
            drawMapsMenu(hudWidth, hudHeight);
        } else {
            drawOptionsMenu(hudWidth, hudHeight);
        }
    }

    private void renderLoadingScreen() {
        hudViewport.apply();
        clearPresentationArea(0.045f, 0.055f, 0.065f, 1f);
        shapeRenderer.setProjectionMatrix(hudCamera.combined);
        spriteBatch.setProjectionMatrix(hudCamera.combined);

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        drawMenuBackdrop(hudWidth, hudHeight);

        float trackWidth = Math.min(360f, Math.max(180f, hudWidth * 0.42f));
        float trackHeight = Math.min(10f, Math.max(6f, hudHeight * 0.012f));
        float trackX = (hudWidth - trackWidth) * 0.5f;
        float trackY = hudHeight * 0.40f;
        float filledWidth = trackWidth * MathUtils.clamp(loadingDisplayedProgress, 0f, 1f);

        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        shapeRenderer.setColor(0.12f, 0.15f, 0.18f, 1f);
        shapeRenderer.rect(trackX, trackY, trackWidth, trackHeight);
        if (filledWidth > 0f) {
            shapeRenderer.setColor(0.95f, 0.74f, 0.27f, 1f);
            shapeRenderer.rect(trackX, trackY, filledWidth, trackHeight);
        }
        shapeRenderer.end();

        spriteBatch.begin();
        titleFont.setColor(0.98f, 0.92f, 0.76f, 1f);
        drawTextCentered(
                titleFont,
                gameMode == GameMode.STARTUP_LOADING
                        ? "Loading Rogue Circuit"
                        : loadingMapTransition
                                ? "Loading Circuit"
                                : loadingSandboxMode ? "Loading Sandbox" : "Loading Race",
                hudWidth * 0.5f,
                hudHeight * 0.58f);
        hudFont.setColor(0.72f, 0.78f, 0.82f, 1f);
        drawTextCentered(
                hudFont,
                loadingStatus,
                hudWidth * 0.5f,
                hudHeight * 0.49f);
        hudFont.setColor(0.98f, 0.92f, 0.76f, 1f);
        drawTextCentered(
                hudFont,
                Math.round(loadingDisplayedProgress * 100f) + "%",
                hudWidth * 0.5f,
                trackY - Math.max(18f, hudHeight * 0.025f));
        spriteBatch.end();
    }

    private void renderInGameMenuOverlay() {
        hudViewport.apply();
        shapeRenderer.setProjectionMatrix(hudCamera.combined);
        spriteBatch.setProjectionMatrix(hudCamera.combined);

        float hudWidth = hudViewport.getWorldWidth();
        float hudHeight = hudViewport.getWorldHeight();
        drawMenuDimOverlay(hudWidth, hudHeight);

        if (gameMode == GameMode.PAUSE_MENU) {
            drawPauseMenu(hudWidth, hudHeight);
        } else {
            drawOptionsMenu(hudWidth, hudHeight);
        }
    }

    private void drawMenuDimOverlay(float hudWidth, float hudHeight) {
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        shapeRenderer.setColor(0.02f, 0.025f, 0.03f, 0.72f);
        shapeRenderer.rect(0f, 0f, hudWidth, hudHeight);
        shapeRenderer.end();
        Gdx.gl.glDisable(GL20.GL_BLEND);
    }

    private void drawMenuBackdrop(float hudWidth, float hudHeight) {
        Texture background = getMenuBackgroundTexture();
        if (background != null) {
            drawMenuBackgroundImage(background, hudWidth, hudHeight);
            return;
        }

        boolean showHeroCar =
                gameMode == GameMode.MAIN_MENU
                        || gameMode == GameMode.NEW_GAME_TIER_MENU
                        || gameMode == GameMode.CUSTOM_GAME_MENU
                        || gameMode == GameMode.NEW_GAME_CAR_MENU;
        if (showHeroCar) {
            ensureMenuHeroCarLoaded();
        }

        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);

        float pulse = 0.5f + 0.5f * MathUtils.sin(effectClock * 1.5f);
        shapeRenderer.setColor(0.035f, 0.045f, 0.055f, 1f);
        shapeRenderer.rect(0f, 0f, hudWidth, hudHeight);

        float roadAngle = 51f;
        float roadLength = (float) Math.sqrt(hudWidth * hudWidth + hudHeight * hudHeight) * 1.18f;
        float roadWidth = Math.max(hudWidth * 0.40f, hudHeight * 0.48f);
        float roadCenterX = hudWidth * 0.58f;
        float roadCenterY = hudHeight * 0.46f;
        drawRotatedRect(
                roadCenterX,
                roadCenterY,
                roadLength,
                roadWidth + 24f,
                roadAngle,
                0.72f,
                0.20f,
                0.16f,
                0.44f);
        drawRotatedRect(
                roadCenterX,
                roadCenterY,
                roadLength,
                roadWidth,
                roadAngle,
                0.12f,
                0.14f,
                0.16f,
                1f);

        float roadCos = MathUtils.cosDeg(roadAngle);
        float roadSin = MathUtils.sinDeg(roadAngle);
        for (int i = -6; i <= 6; i++) {
            float distance = i * roadLength / 11f;
            drawRotatedRect(
                    roadCenterX + roadCos * distance,
                    roadCenterY + roadSin * distance,
                    roadLength * 0.045f,
                    4f,
                    roadAngle,
                    0.94f,
                    0.77f,
                    0.30f,
                    0.24f + pulse * 0.08f);
        }

        for (int i = 0; i < 5; i++) {
            float laneOffset = roadWidth * (0.60f + i * 0.10f);
            drawRotatedRect(
                    roadCenterX - roadSin * laneOffset,
                    roadCenterY + roadCos * laneOffset,
                    roadLength * (0.42f + i * 0.08f),
                    2f,
                    roadAngle,
                    0.17f,
                    0.70f,
                    0.76f,
                    0.09f + pulse * 0.03f);
        }

        shapeRenderer.setColor(0.015f, 0.020f, 0.026f, showHeroCar ? 0.20f : 0.34f);
        shapeRenderer.rect(0f, 0f, hudWidth, hudHeight);

        shapeRenderer.end();

        if (showHeroCar && menuHeroCarTexture != null) {
            float carHeight = Math.min(330f, Math.max(150f, hudHeight * 0.34f));
            float carWidth = carHeight
                    * menuHeroCarTexture.getWidth()
                    / Math.max(1f, menuHeroCarTexture.getHeight());
            float carX = hudWidth * 0.80f - carWidth * 0.5f;
            float carY = hudHeight * 0.28f - carHeight * 0.5f;

            spriteBatch.begin();
            spriteBatch.setColor(1f, 1f, 1f, 0.94f);
            spriteBatch.draw(
                    menuHeroCarTexture,
                    carX,
                    carY,
                    carWidth * 0.5f,
                    carHeight * 0.5f,
                    carWidth,
                    carHeight,
                    1f,
                    1f,
                    CAR_SPRITE_ROTATION_OFFSET_DEG - 39f,
                    0,
                    0,
                    menuHeroCarTexture.getWidth(),
                    menuHeroCarTexture.getHeight(),
                    false,
                    false);
            spriteBatch.setColor(1f, 1f, 1f, 1f);
            spriteBatch.end();
        }

        Gdx.gl.glDisable(GL20.GL_BLEND);
    }

    private Texture getMenuBackgroundTexture() {
        String themeName = configuredThemeName == null ? "" : configuredThemeName;
        if (!themeName.equals(menuBackgroundThemeName)) {
            disposeTexture(menuBackgroundTexture);
            menuBackgroundTexture = null;
            menuBackgroundLoadAttempted = false;
            menuBackgroundThemeName = themeName;
        }
        if (!menuBackgroundLoadAttempted) {
            menuBackgroundLoadAttempted = true;
            menuBackgroundTexture = loadTexture(MENU_BACKGROUND_PATH);
            if (menuBackgroundTexture != null) {
                menuBackgroundTexture.setFilter(
                        Texture.TextureFilter.Linear,
                        Texture.TextureFilter.Linear);
            }
        }
        return menuBackgroundTexture;
    }

    private void drawMenuBackgroundImage(
            Texture texture,
            float hudWidth,
            float hudHeight) {
        float destinationAspect = hudWidth / Math.max(1f, hudHeight);
        float sourceAspect = texture.getWidth() / (float) Math.max(1, texture.getHeight());
        int sourceX = 0;
        int sourceY = 0;
        int sourceWidth = texture.getWidth();
        int sourceHeight = texture.getHeight();
        if (sourceAspect > destinationAspect) {
            sourceWidth = Math.max(1, Math.round(sourceHeight * destinationAspect));
            sourceX = (texture.getWidth() - sourceWidth) / 2;
        } else if (sourceAspect < destinationAspect) {
            sourceHeight = Math.max(1, Math.round(sourceWidth / destinationAspect));
            sourceY = (texture.getHeight() - sourceHeight) / 2;
        }

        spriteBatch.begin();
        spriteBatch.setColor(1f, 1f, 1f, 1f);
        spriteBatch.draw(
                texture,
                0f,
                0f,
                hudWidth,
                hudHeight,
                sourceX,
                sourceY,
                sourceWidth,
                sourceHeight,
                false,
                false);
        spriteBatch.end();

        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        shapeRenderer.setColor(0.01f, 0.012f, 0.016f, 0.20f);
        shapeRenderer.rect(0f, 0f, hudWidth, hudHeight);
        shapeRenderer.end();
        Gdx.gl.glDisable(GL20.GL_BLEND);
    }

    private void ensureMenuHeroCarLoaded() {
        int visualIndex = Math.max(0, selectedPlayerCarIndex);
        String key = configuredThemeName + ":" + visualIndex;
        if (key.equals(menuHeroCarKey)) {
            return;
        }

        disposeMenuHeroCar();
        menuHeroCarKey = key;
        menuHeroCarTexture = loadTexture(buildThemeCarFilePath(visualIndex));
        if (menuHeroCarTexture != null) {
            menuHeroCarTexture.setFilter(Texture.TextureFilter.Linear, Texture.TextureFilter.Linear);
        }
    }

    private void disposeMenuHeroCar() {
        disposeTexture(menuHeroCarTexture);
        menuHeroCarTexture = null;
        menuHeroCarKey = "";
    }

