    private void drawMapDebugPreview(ArenaMap map) {
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        shapeRenderer.setColor(0.025f, 0.032f, 0.040f, 0.96f);
        shapeRenderer.rect(
                mapDebugPreviewBounds.x,
                mapDebugPreviewBounds.y,
                mapDebugPreviewBounds.width,
                mapDebugPreviewBounds.height);
        shapeRenderer.end();

        shapeRenderer.begin(ShapeRenderer.ShapeType.Line);
        shapeRenderer.setColor(0.62f, 0.70f, 0.75f, 0.45f);
        shapeRenderer.rect(
                mapDebugPreviewBounds.x,
                mapDebugPreviewBounds.y,
                mapDebugPreviewBounds.width,
                mapDebugPreviewBounds.height);
        shapeRenderer.end();

        if (map == null) {
            Gdx.gl.glDisable(GL20.GL_BLEND);
            return;
        }

        Texture maskTexture = getOrCreateMapDebugMaskTexture(map);
        calculateMapDebugImageBounds(maskTexture);
        if (maskTexture != null) {
            spriteBatch.begin();
            spriteBatch.setColor(1f, 1f, 1f, 1f);
            spriteBatch.draw(
                    maskTexture,
                    mapDebugImageBounds.x,
                    mapDebugImageBounds.y,
                    mapDebugImageBounds.width,
                    mapDebugImageBounds.height);
            spriteBatch.end();
        }

        map.getBounds(mapDebugMapBounds);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        drawMapDebugRoute(map);
        drawMapDebugCheckpoints(map);
        drawMapDebugSpawns(map);
        shapeRenderer.end();

        spriteBatch.begin();
        drawMapDebugLabels(map);
        spriteBatch.end();
        Gdx.gl.glDisable(GL20.GL_BLEND);
    }

    private void calculateMapDebugImageBounds(Texture texture) {
        float padding = Math.max(8f, Math.min(mapDebugPreviewBounds.width, mapDebugPreviewBounds.height) * 0.025f);
        float availableWidth = Math.max(1f, mapDebugPreviewBounds.width - padding * 2f);
        float availableHeight = Math.max(1f, mapDebugPreviewBounds.height - padding * 2f);
        float aspect = texture == null ? 1f : texture.getWidth() / (float) texture.getHeight();
        float width = availableWidth;
        float height = width / aspect;
        if (height > availableHeight) {
            height = availableHeight;
            width = height * aspect;
        }
        mapDebugImageBounds.set(
                mapDebugPreviewBounds.x + (mapDebugPreviewBounds.width - width) * 0.5f,
                mapDebugPreviewBounds.y + (mapDebugPreviewBounds.height - height) * 0.5f,
                width,
                height);
    }

    private Texture getOrCreateMapDebugMaskTexture(ArenaMap map) {
        if (map == null || Gdx.gl == null) {
            return null;
        }
        String path = getMapMaskPath(map);
        if (path == null || path.length() == 0) {
            return null;
        }
        if (path.equals(mapDebugMaskTexturePath)) {
            return mapDebugMaskTexture;
        }
        disposeMapDebugMaskTextures();
        mapDebugMaskTexturePath = path;

        FileHandle handle = resolveMapMaskHandle(path, map.getId());
        if (handle == null || !handle.exists()) {
            return null;
        }
        try {
            mapDebugMaskTexture = new Texture(handle);
            mapDebugMaskTexture.setFilter(
                    Texture.TextureFilter.Nearest,
                    Texture.TextureFilter.Nearest);
            return mapDebugMaskTexture;
        } catch (RuntimeException exception) {
            Gdx.app.error("RatassGame", "Could not load map debug mask " + handle.path(), exception);
            return null;
        }
    }

    private String getMapMaskPath(ArenaMap map) {
        if (map == null) {
            return "";
        }
        String surfacePath = map.getSurfaceImagePath();
        if (surfacePath != null && surfacePath.length() > 0) {
            if (surfacePath.endsWith("_mask.png")) {
                return surfacePath;
            }
            if (surfacePath.endsWith(".png")) {
                return surfacePath.substring(0, surfacePath.length() - ".png".length())
                        + "_mask.png";
            }
        }
        String mapId = map.getId();
        return mapId == null || mapId.length() == 0 ? "" : "assets/maps/" + mapId + "_mask.png";
    }

    private FileHandle resolveMapMaskHandle(String path, String mapId) {
        if (path != null && path.length() > 0) {
            FileHandle handle = Gdx.files.internal(path);
            if (handle != null && handle.exists()) {
                return handle;
            }
            handle = Gdx.files.local(path);
            if (handle != null && handle.exists()) {
                return handle;
            }
        }
        if (mapId != null && mapId.length() > 0) {
            FileHandle handle = Gdx.files.local("assets/maps/" + mapId + "_mask.png");
            if (handle.exists()) {
                return handle;
            }
            handle = Gdx.files.local("tools/rl/trainingMaps/" + mapId + "_mask.png");
            if (handle.exists()) {
                return handle;
            }
            handle = Gdx.files.internal("maps/" + mapId + "_mask.png");
            if (handle.exists()) {
                return handle;
            }
        }
        return null;
    }

    private void drawMapDebugRoute(ArenaMap map) {
        if (map == null || !map.hasRoute()) {
            return;
        }
        float routeLength = map.getRouteLength();
        if (routeLength <= 0.001f) {
            return;
        }
        float sampleStep = Math.max(0.10f, MENU_MAP_DEBUG_SAMPLE_STEP);
        int sampleCount = MathUtils.clamp(MathUtils.ceil(routeLength / sampleStep), 12, 2200);
        float lineWidth =
                MathUtils.clamp(
                        Math.min(mapDebugImageBounds.width, mapDebugImageBounds.height) * 0.0048f,
                        MENU_MAP_DEBUG_MIN_LINE_WIDTH,
                        MENU_MAP_DEBUG_MAX_LINE_WIDTH);

        float previousX = 0f;
        float previousY = 0f;
        for (int i = 0; i <= sampleCount; i++) {
            float progress = routeLength * i / sampleCount;
            map.findRoutePoint(progress, mapDebugPoint);
            float x = mapDebugWorldToHudX(mapDebugPoint.x);
            float y = mapDebugWorldToHudY(mapDebugPoint.y);
            if (i > 0) {
                drawMapDebugSegment(previousX, previousY, x, y, lineWidth + 3.0f, 0.02f, 0.02f, 0.025f, 0.92f);
                drawMapDebugSegment(previousX, previousY, x, y, lineWidth, 1.00f, 0.00f, 0.86f, 0.96f);
            }
            previousX = x;
            previousY = y;
        }
        map.findRoutePoint(0f, mapDebugPoint);
        float firstX = mapDebugWorldToHudX(mapDebugPoint.x);
        float firstY = mapDebugWorldToHudY(mapDebugPoint.y);
        drawMapDebugSegment(previousX, previousY, firstX, firstY, lineWidth + 3.0f, 0.02f, 0.02f, 0.025f, 0.92f);
        drawMapDebugSegment(previousX, previousY, firstX, firstY, lineWidth, 1.00f, 0.00f, 0.86f, 0.96f);

        float arrowStep = Math.max(3f, MENU_MAP_DEBUG_ARROW_STEP);
        for (float progress = 0f; progress < routeLength; progress += arrowStep) {
            map.findRoutePoint(progress, mapDebugPoint);
            map.findRouteTangent(progress, mapDebugTangent);
            drawMapDebugArrow(
                    mapDebugWorldToHudX(mapDebugPoint.x),
                    mapDebugWorldToHudY(mapDebugPoint.y),
                    mapDebugTangent.x,
                    mapDebugTangent.y,
                    lineWidth * 2.8f);
        }

        drawMapDebugUnsafeRouteMarkerSegments(map, routeLength, sampleStep, lineWidth);
    }

    private void drawMapDebugUnsafeRouteMarkerSegments(
            ArenaMap map,
            float routeLength,
            float sampleStep,
            float lineWidth) {
        int markerCount = map.getRouteMarkerPointCount();
        if (markerCount < 2 || routeLength <= 0.001f) {
            return;
        }
        for (int i = 0; i < markerCount; i++) {
            float startProgress = map.getRouteMarkerProgress(i);
            float endProgress = map.getRouteMarkerProgress((i + 1) % markerCount);
            float delta = endProgress - startProgress;
            if (i == markerCount - 1 || delta <= 0.001f) {
                delta += routeLength;
            }
            if (delta <= 0.001f || delta > routeLength + 0.001f) {
                continue;
            }
            if (!routeMarkerIntervalCutsOffRoad(map, startProgress, delta, sampleStep)) {
                continue;
            }
            drawMapDebugRouteProgressSegment(
                    map,
                    startProgress,
                    delta,
                    Math.max(2f, sampleStep * 0.55f),
                    lineWidth + 5.0f,
                    0.02f,
                    0.02f,
                    0.025f,
                    0.96f);
            drawMapDebugRouteProgressSegment(
                    map,
                    startProgress,
                    delta,
                    Math.max(2f, sampleStep * 0.55f),
                    lineWidth + 2.0f,
                    1.00f,
                    0.06f,
                    0.03f,
                    0.98f);
        }
    }

    private boolean routeMarkerIntervalCutsOffRoad(
            ArenaMap map,
            float startProgress,
            float delta,
            float sampleStep) {
        float detectionStep = Math.max(0.08f, Math.min(0.25f, sampleStep * 0.5f));
        int sampleCount = MathUtils.clamp(MathUtils.ceil(delta / detectionStep), 2, 2400);
        for (int sample = 0; sample <= sampleCount; sample++) {
            float progress = startProgress + delta * sample / sampleCount;
            map.findRoutePoint(progress, mapDebugPoint);
            if (!map.approximateSupports(mapDebugPoint.x, mapDebugPoint.y)) {
                return true;
            }
        }
        return false;
    }

    private void drawMapDebugRouteProgressSegment(
            ArenaMap map,
            float startProgress,
            float delta,
            float sampleStep,
            float lineWidth,
            float red,
            float green,
            float blue,
            float alpha) {
        int sampleCount = MathUtils.clamp(MathUtils.ceil(delta / Math.max(0.08f, sampleStep)), 2, 1800);
        float previousX = 0f;
        float previousY = 0f;
        for (int sample = 0; sample <= sampleCount; sample++) {
            float progress = startProgress + delta * sample / sampleCount;
            map.findRoutePoint(progress, mapDebugPoint);
            float x = mapDebugWorldToHudX(mapDebugPoint.x);
            float y = mapDebugWorldToHudY(mapDebugPoint.y);
            if (sample > 0) {
                drawMapDebugSegment(previousX, previousY, x, y, lineWidth, red, green, blue, alpha);
            }
            previousX = x;
            previousY = y;
        }
    }

    private void drawMapDebugSegment(
            float x1,
            float y1,
            float x2,
            float y2,
            float width,
            float red,
            float green,
            float blue,
            float alpha) {
        float dx = x2 - x1;
        float dy = y2 - y1;
        float length = (float) Math.sqrt(dx * dx + dy * dy);
        if (length <= 0.001f) {
            return;
        }
        drawRotatedRect(
                (x1 + x2) * 0.5f,
                (y1 + y2) * 0.5f,
                length,
                width,
                MathUtils.atan2(dy, dx) * MathUtils.radiansToDegrees,
                red,
                green,
                blue,
                alpha);
    }

    private void drawMapDebugArrow(float x, float y, float tangentX, float tangentY, float size) {
        float length = (float) Math.sqrt(tangentX * tangentX + tangentY * tangentY);
        if (length <= 0.0001f) {
            return;
        }
        float tx = tangentX / length;
        float ty = tangentY / length;
        float nx = -ty;
        float ny = tx;
        shapeRenderer.setColor(0.00f, 0.86f, 1.00f, 0.92f);
        shapeRenderer.triangle(
                x + tx * size,
                y + ty * size,
                x - tx * size * 0.55f + nx * size * 0.42f,
                y - ty * size * 0.55f + ny * size * 0.42f,
                x - tx * size * 0.55f - nx * size * 0.42f,
                y - ty * size * 0.55f - ny * size * 0.42f);
    }

    private void drawMapDebugSpawns(ArenaMap map) {
        if (map == null) {
            return;
        }
        for (int i = 0; i < map.getSpawnCount(); i++) {
            SpawnPoint spawn = map.getSpawn(i);
            float x = mapDebugWorldToHudX(spawn.x);
            float y = mapDebugWorldToHudY(spawn.y);
            float forwardX = -MathUtils.sin(spawn.angleRad);
            float forwardY = MathUtils.cos(spawn.angleRad);
            shapeRenderer.setColor(0.08f, 0.88f, 0.24f, 0.98f);
            shapeRenderer.circle(x, y, 3.8f, 14);
            drawMapDebugArrow(x, y, forwardX, forwardY, 8.5f);
        }
    }

    private void drawMapDebugCheckpoints(ArenaMap map) {
        if (map == null) {
            return;
        }
        for (int i = 0; i < map.getCheckpointCount(); i++) {
            SpawnPoint checkpoint = map.getCheckpoint(i);
            float x = mapDebugWorldToHudX(checkpoint.x);
            float y = mapDebugWorldToHudY(checkpoint.y);
            shapeRenderer.setColor(0.12f, 0.82f, 0.34f, 0.96f);
            if (checkpoint.hasGate) {
                drawMapDebugSegment(
                        mapDebugWorldToHudX(checkpoint.gateStartX),
                        mapDebugWorldToHudY(checkpoint.gateStartY),
                        mapDebugWorldToHudX(checkpoint.gateEndX),
                        mapDebugWorldToHudY(checkpoint.gateEndY),
                        3.2f,
                        0.12f,
                        0.82f,
                        0.34f,
                        0.96f);
            }
            shapeRenderer.circle(x, y, 4.4f, 18);
        }
    }

    private void drawMapDebugLabels(ArenaMap map) {
        if (map == null) {
            return;
        }
        labelFont.setColor(1f, 1f, 1f, 1f);
        for (int i = 0; i < map.getCheckpointCount(); i++) {
            SpawnPoint checkpoint = map.getCheckpoint(i);
            drawTextWithShadow(
                    labelFont,
                    String.valueOf(i + 1),
                    mapDebugWorldToHudX(checkpoint.x) + 6f,
                    mapDebugWorldToHudY(checkpoint.y) + 8f);
        }
        labelFont.setColor(1.00f, 0.66f, 0.08f, 1f);
        for (int i = 0; i < map.getRouteMarkerPointCount(); i++) {
            map.getRouteMarkerPoint(i, mapDebugPoint);
            drawTextWithShadow(
                    labelFont,
                    String.valueOf(i + 1),
                    mapDebugWorldToHudX(mapDebugPoint.x) + 5f,
                    mapDebugWorldToHudY(mapDebugPoint.y) + 5f);
        }
        if (map.hasRoute()) {
            labelFont.setColor(1f, 1f, 1f, 1f);
            float routeLength = map.getRouteLength();
            for (int i = 0; i < 10; i++) {
                float progress = routeLength * i / 10f;
                map.findRoutePoint(progress, mapDebugPoint);
                drawTextWithShadow(
                        labelFont,
                        i == 0 ? "0%" : (i * 10) + "%",
                        mapDebugWorldToHudX(mapDebugPoint.x) + 7f,
                        mapDebugWorldToHudY(mapDebugPoint.y) - 7f);
            }
        }
        hudFont.setColor(0.96f, 0.90f, 0.72f, 1f);
        String info =
                "spawns=" + map.getSpawnCount()
                        + "  goals=" + map.getCheckpointCount()
                        + "  markers=" + map.getRouteMarkerPointCount()
                        + "  route=" + TextFormat.fixed(map.getRouteLength(), 1);
        drawTextWithShadow(
                hudFont,
                info,
                mapDebugPreviewBounds.x + 12f,
                mapDebugPreviewBounds.y + mapDebugPreviewBounds.height - 14f);
    }

    private float mapDebugWorldToHudX(float worldX) {
        if (mapDebugMapBounds.width <= 0.0001f) {
            return mapDebugImageBounds.x;
        }
        return mapDebugImageBounds.x
                + (worldX - mapDebugMapBounds.x) * mapDebugImageBounds.width / mapDebugMapBounds.width;
    }

    private float mapDebugWorldToHudY(float worldY) {
        if (mapDebugMapBounds.height <= 0.0001f) {
            return mapDebugImageBounds.y;
        }
        return mapDebugImageBounds.y
                + (worldY - mapDebugMapBounds.y) * mapDebugImageBounds.height / mapDebugMapBounds.height;
    }

    private void drawPauseMenu(float hudWidth, float hudHeight) {
        drawMenuButton(
                pauseContinueBounds,
                "Continue",
                pauseMenuSelection == PAUSE_MENU_CONTINUE_SELECTION);
        drawMenuButton(
                pauseMainMenuBounds,
                "Main Menu",
                pauseMenuSelection == PAUSE_MENU_MAIN_MENU_SELECTION);
        drawMenuButton(
                pauseOptionsBounds,
                "Options",
                pauseMenuSelection == PAUSE_MENU_OPTIONS_SELECTION);
        drawMenuButton(
                pauseExitBounds,
                "Exit",
                pauseMenuSelection == PAUSE_MENU_EXIT_SELECTION);

        spriteBatch.begin();
        titleFont.setColor(0.98f, 0.92f, 0.76f, 1f);
        float titleBaseline =
                Math.min(
                        hudHeight - 30f,
                        Math.max(
                                hudHeight * 0.73f,
                                pauseContinueBounds.y
                                        + pauseContinueBounds.height
                                        + Math.max(34f, hudHeight * 0.045f)));
        drawTextCentered(titleFont, "Paused", hudWidth * 0.5f, titleBaseline);
        spriteBatch.end();
    }

    private void drawOptionsMenu(float hudWidth, float hudHeight) {
        if (isDesktopDisplayOptionAvailable()) {
            drawOptionRow(
                    optionsDisplayBounds,
                    optionsMenuSelection == OPTIONS_DISPLAY_SELECTION,
                    true);
        }
        drawOptionRow(optionsMusicBounds, optionsMenuSelection == OPTIONS_MUSIC_SELECTION, true);
        drawOptionRow(
                optionsSoundEffectsBounds,
                optionsMenuSelection == OPTIONS_SOUND_EFFECTS_SELECTION,
                true);
        if (isDesktopDisplayOptionAvailable()) {
            drawOptionRow(
                    optionsLeftKeyBounds,
                    optionsMenuSelection == OPTIONS_LEFT_KEY_SELECTION,
                    true);
            drawOptionRow(
                    optionsRightKeyBounds,
                    optionsMenuSelection == OPTIONS_RIGHT_KEY_SELECTION,
                    true);
        }
        drawMenuButton(optionsBackBounds, "Back", optionsMenuSelection == OPTIONS_BACK_SELECTION);

        drawMenuStepButton(optionsMusicDownBounds, "-", optionsMenuSelection == OPTIONS_MUSIC_SELECTION);
        drawMenuStepButton(optionsMusicUpBounds, "+", optionsMenuSelection == OPTIONS_MUSIC_SELECTION);
        drawMenuStepButton(
                optionsSoundEffectsDownBounds,
                "-",
                optionsMenuSelection == OPTIONS_SOUND_EFFECTS_SELECTION);
        drawMenuStepButton(
                optionsSoundEffectsUpBounds,
                "+",
                optionsMenuSelection == OPTIONS_SOUND_EFFECTS_SELECTION);

        spriteBatch.begin();
        titleFont.setColor(0.98f, 0.92f, 0.76f, 1f);
        drawTextCentered(titleFont, "Options", hudWidth * 0.5f, getOptionsTitleBaseline(hudHeight));

        if (isDesktopDisplayOptionAvailable()) {
            drawOptionKeyValue(
                    optionsDisplayBounds,
                    "Display",
                    windowedMode ? "Windowed" : "Fullscreen",
                    true,
                    0f,
                    0f);
        }

        drawOptionKeyValue(
                optionsMusicBounds,
                "Music",
                buildAudioVolumeMenuValue(musicVolume),
                true,
                optionsMusicDownBounds.width,
                optionsMusicUpBounds.width);
        drawOptionKeyValue(
                optionsSoundEffectsBounds,
                "Sound FX",
                buildAudioVolumeMenuValue(soundEffectsVolume),
                true,
                optionsSoundEffectsDownBounds.width,
                optionsSoundEffectsUpBounds.width);
        if (isDesktopDisplayOptionAvailable()) {
            drawDrivingKeyOption(optionsLeftKeyBounds, "Left", Action.LEFT);
            drawDrivingKeyOption(optionsRightKeyBounds, "Right", Action.RIGHT);
        }
        spriteBatch.end();
    }

    private void drawDrivingKeyOption(Rectangle bounds, String label, Action action) {
        String value =
                pendingDrivingKeyBinding == action
                        ? "Press a key"
                        : drivingKeyBindings.displayName(action);
        drawOptionKeyValue(bounds, label, value, true, 0f, 0f);
    }

    private void drawLanguageFlag(Rectangle buttonBounds, GameLanguage language) {
        float flagWidth = Math.min(buttonBounds.width * 0.72f, buttonBounds.height * 1.12f);
        float flagHeight = Math.min(buttonBounds.height * 0.58f, flagWidth * 0.62f);
        float x = buttonBounds.x + (buttonBounds.width - flagWidth) * 0.5f;
        float y = buttonBounds.y + (buttonBounds.height - flagHeight) * 0.5f;

        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        if (language == GameLanguage.SPANISH) {
            shapeRenderer.setColor(0.68f, 0.02f, 0.04f, 1f);
            shapeRenderer.rect(x, y, flagWidth, flagHeight);
            shapeRenderer.setColor(1f, 0.78f, 0.05f, 1f);
            shapeRenderer.rect(x, y + flagHeight * 0.25f, flagWidth, flagHeight * 0.5f);
        } else if (language == GameLanguage.ENGLISH) {
            shapeRenderer.setColor(0.05f, 0.16f, 0.39f, 1f);
            shapeRenderer.rect(x, y, flagWidth, flagHeight);
            float centerX = x + flagWidth * 0.5f;
            float centerY = y + flagHeight * 0.5f;
            float diagonal = (float) Math.sqrt(flagWidth * flagWidth + flagHeight * flagHeight);
            float angle = MathUtils.atan2(flagHeight, flagWidth) * MathUtils.radiansToDegrees;
            drawRotatedRect(centerX, centerY, diagonal, flagHeight * 0.16f, angle, 1f, 1f, 1f, 1f);
            drawRotatedRect(centerX, centerY, diagonal, flagHeight * 0.16f, -angle, 1f, 1f, 1f, 1f);
            drawRotatedRect(centerX, centerY, diagonal, flagHeight * 0.07f, angle, 0.78f, 0.04f, 0.08f, 1f);
            drawRotatedRect(centerX, centerY, diagonal, flagHeight * 0.07f, -angle, 0.78f, 0.04f, 0.08f, 1f);
            shapeRenderer.setColor(1f, 1f, 1f, 1f);
            shapeRenderer.rect(x, centerY - flagHeight * 0.13f, flagWidth, flagHeight * 0.26f);
            shapeRenderer.rect(centerX - flagHeight * 0.13f, y, flagHeight * 0.26f, flagHeight);
            shapeRenderer.setColor(0.78f, 0.04f, 0.08f, 1f);
            shapeRenderer.rect(x, centerY - flagHeight * 0.07f, flagWidth, flagHeight * 0.14f);
            shapeRenderer.rect(centerX - flagHeight * 0.07f, y, flagHeight * 0.14f, flagHeight);
        } else if (language == GameLanguage.FRENCH) {
            float stripeWidth = flagWidth / 3f;
            shapeRenderer.setColor(0.02f, 0.18f, 0.48f, 1f);
            shapeRenderer.rect(x, y, stripeWidth, flagHeight);
            shapeRenderer.setColor(0.97f, 0.97f, 0.95f, 1f);
            shapeRenderer.rect(x + stripeWidth, y, stripeWidth, flagHeight);
            shapeRenderer.setColor(0.83f, 0.04f, 0.10f, 1f);
            shapeRenderer.rect(x + stripeWidth * 2f, y, stripeWidth, flagHeight);
        } else if (language == GameLanguage.GERMAN) {
            float stripeHeight = flagHeight / 3f;
            shapeRenderer.setColor(0.03f, 0.03f, 0.03f, 1f);
            shapeRenderer.rect(x, y + stripeHeight * 2f, flagWidth, stripeHeight);
            shapeRenderer.setColor(0.82f, 0.02f, 0.05f, 1f);
            shapeRenderer.rect(x, y + stripeHeight, flagWidth, stripeHeight);
            shapeRenderer.setColor(0.98f, 0.78f, 0.04f, 1f);
            shapeRenderer.rect(x, y, flagWidth, stripeHeight);
        } else {
            float stripeWidth = flagWidth / 3f;
            shapeRenderer.setColor(0.02f, 0.48f, 0.22f, 1f);
            shapeRenderer.rect(x, y, stripeWidth, flagHeight);
            shapeRenderer.setColor(0.98f, 0.98f, 0.96f, 1f);
            shapeRenderer.rect(x + stripeWidth, y, stripeWidth, flagHeight);
            shapeRenderer.setColor(0.82f, 0.03f, 0.08f, 1f);
            shapeRenderer.rect(x + stripeWidth * 2f, y, stripeWidth, flagHeight);
        }
        shapeRenderer.end();
        shapeRenderer.begin(ShapeRenderer.ShapeType.Line);
        shapeRenderer.setColor(0.93f, 0.93f, 0.88f, 0.90f);
        shapeRenderer.rect(x, y, flagWidth, flagHeight);
        shapeRenderer.end();
    }

    private void drawOptionKeyValue(
            Rectangle bounds,
            String label,
            String value,
            boolean enabled,
            float reservedLeft,
            float reservedRight) {
        float insetX = ButtonTextLayout.horizontalInset(bounds.width, bounds.height);
        float contentLeft = bounds.x + Math.max(insetX, reservedLeft + 12f);
        float contentRight =
                bounds.x + bounds.width - Math.max(insetX, reservedRight + 12f);
        float centerX = bounds.x + bounds.width * 0.5f;
        float gap = MathUtils.clamp(bounds.width * 0.035f, 12f, 24f);
        float leftWidth = Math.max(1f, centerX - gap * 0.5f - contentLeft);
        float rightX = centerX + gap * 0.5f;
        float rightWidth = Math.max(1f, contentRight - rightX);
        float preferredScale = ButtonTextLayout.preferredTextScale(bounds.height);
        float baseline =
                ButtonTextLayout.centeredBaseline(
                        bounds.y,
                        bounds.height,
                        hudFont.getCapHeight(),
                        preferredScale);
        float contentHeight = ButtonTextLayout.contentHeight(bounds.height);

        tint.set(
                enabled ? 0.86f : 0.50f,
                enabled ? 0.91f : 0.56f,
                enabled ? 0.94f : 0.60f,
                1f);
        drawFittedTextWithShadow(
                hudFont,
                label,
                contentLeft,
                baseline,
                leftWidth,
                contentHeight,
                tint,
                preferredScale,
                0.82f,
                Align.right);
        tint.set(
                enabled ? 0.98f : 0.58f,
                enabled ? 0.92f : 0.60f,
                enabled ? 0.76f : 0.62f,
                1f);
        drawFittedTextWithShadow(
                hudFont,
                value,
                rightX,
                baseline,
                rightWidth,
                contentHeight,
                tint,
                preferredScale,
                0.82f,
                Align.left);
    }

    private float getOptionsTitleBaseline(float hudHeight) {
        Rectangle firstRow =
                isDesktopDisplayOptionAvailable()
                        ? optionsDisplayBounds
                        : optionsMusicBounds;
        float contentTop = firstRow.y + firstRow.height;
        return Math.min(hudHeight - 30f, contentTop + Math.max(34f, hudHeight * 0.045f));
    }

    private String buildDisplayedPlayerName() {
        String displayedPlayerName =
                playerNameEditor.isEditing() ? playerNameEditor.getDraft() : playerName;
        if (playerNameEditor.isEditing()
                && displayedPlayerName.length() < PlayerDisplayName.MAX_LENGTH) {
            displayedPlayerName += "|";
        }
        return displayedPlayerName;
    }

    private String buildPlayerCarMenuLabel() {
        int carCount = getMenuSelectableCarCount();
        if (carCount <= 0) {
            return "Car " + (selectedPlayerCarIndex + 1);
        }
        int carIndex = clampPlayerCarIndex(selectedPlayerCarIndex, carCount);
        String carName = getCarPerformance(carIndex).name;
        return carName + "   " + (carIndex + 1) + "/" + carCount;
    }

    private String buildAudioVolumeMenuValue(float volume) {
        return Math.round(volume * 100f) + "%";
    }

    private void drawFrameEdges(float x, float y, float width, float height, float thickness) {
        if (width <= 0f || height <= 0f || thickness <= 0f) {
            return;
        }
        shapeRenderer.rect(x, y, width, thickness);
        shapeRenderer.rect(x, y + height - thickness, width, thickness);
        shapeRenderer.rect(x, y, thickness, height);
        shapeRenderer.rect(x + width - thickness, y, thickness, height);
    }

