    private void drawRogueliteFittedText(
            BitmapFont font,
            String text,
            float x,
            float topY,
            float width,
            float maxHeight,
            int alignment,
            boolean wrap,
            float preferredScale,
            float minimumScale) {
        text = ui(text);
        if (text == null
                || text.length() == 0
                || width <= 0f
                || maxHeight <= 0f) {
            return;
        }

        BitmapFont.BitmapFontData data = font.getData();
        float originalScaleX = data.scaleX;
        float originalScaleY = data.scaleY;
        float scale = Math.max(minimumScale, preferredScale);
        String fittedText = text;
        try {
            for (int attempt = 0; attempt < 6; attempt++) {
                data.setScale(originalScaleX * scale, originalScaleY * scale);
                glyphLayout.setText(
                        font,
                        text,
                        font.getColor(),
                        width,
                        alignment,
                        wrap);
                boolean widthFits = wrap || glyphLayout.width <= width + 0.25f;
                boolean heightFits = glyphLayout.height <= maxHeight + 0.25f;
                if (widthFits && heightFits) {
                    break;
                }

                float widthRatio =
                        wrap || glyphLayout.width <= 0f
                                ? 1f
                                : width / glyphLayout.width;
                float heightRatio =
                        glyphLayout.height <= 0f
                                ? 1f
                                : maxHeight / glyphLayout.height;
                float nextScale =
                        Math.max(
                                minimumScale,
                                scale * Math.min(widthRatio, heightRatio) * 0.96f);
                if (nextScale >= scale - 0.002f) {
                    break;
                }
                scale = nextScale;
            }

            data.setScale(originalScaleX * scale, originalScaleY * scale);
            fittedText = fitRogueliteTextToBounds(
                    font,
                    text,
                    width,
                    maxHeight,
                    alignment,
                    wrap);
            font.draw(
                    spriteBatch,
                    fittedText,
                    x,
                    topY,
                    width,
                    alignment,
                    wrap);
        } finally {
            data.setScale(originalScaleX, originalScaleY);
        }
    }

    private String fitRogueliteTextToBounds(
            BitmapFont font,
            String text,
            float width,
            float maxHeight,
            int alignment,
            boolean wrap) {
        glyphLayout.setText(
                font,
                text,
                font.getColor(),
                width,
                alignment,
                wrap);
        if ((wrap || glyphLayout.width <= width + 0.25f)
                && glyphLayout.height <= maxHeight + 0.25f) {
            return text;
        }

        for (int end = text.length() - 1; end > 0; end--) {
            String candidate = text.substring(0, end).trim() + "...";
            glyphLayout.setText(
                    font,
                    candidate,
                    font.getColor(),
                    width,
                    alignment,
                    wrap);
            if ((wrap || glyphLayout.width <= width + 0.25f)
                    && glyphLayout.height <= maxHeight + 0.25f) {
                return candidate;
            }
        }
        return "";
    }

    private void drawRogueliteCardBackgrounds(
            Rectangle[] bounds,
            int count,
            int selectedIndex,
            RogueliteSlotType[] slotTypes) {
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Filled);
        for (int i = 0; i < count; i++) {
            Rectangle cardBounds = bounds[i];
            if (!isVisibleRogueliteBounds(cardBounds)) {
                continue;
            }
            RogueliteSlotType slotType =
                    slotTypes != null && i < slotTypes.length
                            ? slotTypes[i]
                            : null;
            float padding = getRogueliteCardPadding(cardBounds);
            boolean horizontal = isHorizontalRogueliteCard(cardBounds);
            float imageSize;
            float imageX;
            float imageY;
            if (horizontal) {
                imageSize = getHorizontalRogueliteArtworkSize(cardBounds);
                imageX = cardBounds.x + padding;
                imageY = getHorizontalRogueliteBodyBottom(cardBounds)
                        + (getHorizontalRogueliteBodyHeight(cardBounds) - imageSize) * 0.5f;
            } else {
                float preferredImageHeight =
                        slotType == RogueliteSlotType.DRIVER
                                ? getRogueliteDriverImageHeight(cardBounds)
                                : getRogueliteCardImageHeight(cardBounds);
                imageSize =
                        RogueliteCardSkinAtlas.fitSquareArtwork(
                                cardBounds.width - padding * 2f,
                                preferredImageHeight);
                imageX = cardBounds.x + (cardBounds.width - imageSize) * 0.5f;
                imageY = getRogueliteCardImageY(cardBounds, imageSize);
            }
            shapeRenderer.setColor(0.015f, 0.020f, 0.027f, 0.58f);
            shapeRenderer.rect(
                    cardBounds.x + 5f,
                    cardBounds.y - 6f,
                    cardBounds.width,
                    cardBounds.height);
            if (i == selectedIndex) {
                shapeRenderer.setColor(0.15f, 0.13f, 0.075f, 0.98f);
            } else {
                shapeRenderer.setColor(0.055f, 0.068f, 0.082f, 0.98f);
            }
            shapeRenderer.rect(
                    cardBounds.x,
                    cardBounds.y,
                    cardBounds.width,
                    cardBounds.height);
            setRogueliteSlotShapeColor(
                    slotType,
                    i == selectedIndex ? 1f : 0.72f);
            shapeRenderer.rect(
                    cardBounds.x,
                    cardBounds.y + cardBounds.height - 5f,
                    cardBounds.width,
                    5f);
            shapeRenderer.rect(
                    cardBounds.x,
                    cardBounds.y,
                    cardBounds.width,
                    getRogueliteTypeBandHeight(cardBounds));
            shapeRenderer.setColor(0.025f, 0.034f, 0.044f, 1f);
            shapeRenderer.rect(
                    imageX,
                    imageY,
                    imageSize,
                    imageSize);
            shapeRenderer.setColor(0.22f, 0.25f, 0.28f, 0.42f);
            float roadY = imageY + imageSize * 0.49f;
            shapeRenderer.rect(
                    imageX,
                    roadY,
                    imageSize,
                    Math.max(2f, imageSize * 0.025f));
        }
        shapeRenderer.end();
        Gdx.gl.glDisable(GL20.GL_BLEND);
        drawRogueliteCardSkins(bounds, count, selectedIndex, slotTypes);
    }

    private void drawRogueliteCardOutlines(
            Rectangle[] bounds,
            int count,
            int selectedIndex,
            RogueliteSlotType[] slotTypes) {
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        shapeRenderer.begin(ShapeRenderer.ShapeType.Line);
        for (int i = 0; i < count; i++) {
            Rectangle cardBounds = bounds[i];
            if (!isVisibleRogueliteBounds(cardBounds)) {
                continue;
            }
            RogueliteSlotType slotType =
                    slotTypes != null && i < slotTypes.length
                            ? slotTypes[i]
                            : null;
            setRogueliteSlotShapeColor(
                    slotType,
                    i == selectedIndex ? 1f : 0.68f);
            shapeRenderer.rect(
                    cardBounds.x,
                    cardBounds.y,
                    cardBounds.width,
                    cardBounds.height);
        }
        shapeRenderer.end();
        Gdx.gl.glDisable(GL20.GL_BLEND);
    }

    private void drawRogueliteCardContent(
            Rectangle bounds,
            RogueliteCardDefinition card) {
        if (!isVisibleRogueliteBounds(bounds)) {
            return;
        }
        if (isHorizontalRogueliteCard(bounds)) {
            drawHorizontalRogueliteCardContent(bounds, card);
            return;
        }
        float padding = getRogueliteCardPadding(bounds);
        float contentWidth = Math.max(1f, bounds.width - padding * 2f);
        float imageSize =
                RogueliteCardSkinAtlas.fitSquareArtwork(
                        contentWidth,
                        getRogueliteCardImageHeight(bounds));
        float imageX = bounds.x + (bounds.width - imageSize) * 0.5f;
        float imageY = getRogueliteCardImageY(bounds, imageSize);
        drawRogueliteCardArtwork(
                card,
                imageX,
                imageY,
                imageSize,
                imageSize);

        drawRogueliteCardHeader(
                bounds,
                card.getTier(),
                card.getSlotType(),
                card.getTitle());

        float informationBottom = getRogueliteInformationPanelBottom(bounds);
        float informationTop = getRogueliteInformationPanelTop(bounds);
        float verticalInset = MathUtils.clamp(bounds.height * 0.012f, 4f, 7f);
        float effectTop = informationTop - verticalInset;
        float detailsHeight = Math.max(
                1f,
                effectTop - informationBottom - verticalInset);

        leaderboardFont.setColor(1f, 0.88f, 0.52f, 1f);
        drawRoguelitePreferredFittedText(
                leaderboardFont,
                card.getEffectText(),
                bounds.x + padding,
                effectTop,
                contentWidth,
                detailsHeight,
                Align.center,
                true,
                1.12f,
                ROGUELITE_EFFECT_MIN_TEXT_SCALE);
        drawRogueliteSlotTypeLabel(bounds, card.getSlotType());
    }

    private void drawHorizontalRogueliteCardContent(
            Rectangle bounds,
            RogueliteCardDefinition card) {
        float imageSize = getHorizontalRogueliteArtworkSize(bounds);
        float imageX = bounds.x + getRogueliteCardPadding(bounds);
        float imageY =
                getHorizontalRogueliteBodyBottom(bounds)
                        + (getHorizontalRogueliteBodyHeight(bounds) - imageSize) * 0.5f;
        drawRogueliteCardArtwork(card, imageX, imageY, imageSize, imageSize);
        drawRogueliteCardHeader(
                bounds,
                card.getTier(),
                card.getSlotType(),
                card.getTitle());

        float textX = getHorizontalRogueliteContentX(bounds);
        float textWidth = getHorizontalRogueliteContentWidth(bounds);
        float contentTop = getHorizontalRogueliteBodyTop(bounds) - 3f;
        float contentBottom = getHorizontalRogueliteBodyBottom(bounds) + 3f;
        float contentHeight = Math.max(1f, contentTop - contentBottom);
        leaderboardFont.setColor(1f, 0.88f, 0.52f, 1f);
        drawRoguelitePreferredFittedText(
                leaderboardFont,
                card.getEffectText(),
                textX,
                contentTop,
                textWidth,
                contentHeight,
                Align.left,
                true,
                1.12f,
                ROGUELITE_EFFECT_MIN_TEXT_SCALE);
        drawRogueliteSlotTypeLabel(bounds, card.getSlotType());
    }

