    private final class ImpactContactListener implements ContactListener {
        @Override
        public void beginContact(Contact contact) {
            if (beginMapWallContact(contact)) {
                return;
            }
            Car carA = contactCar(contact.getFixtureA());
            Car carB = contactCar(contact.getFixtureB());
            if (carA == null || carB == null) {
                return;
            }
            if (carA.isInvisible() || carB.isInvisible()) {
                return;
            }
            carA.beginCarContact(carB);
            carB.beginCarContact(carA);
        }

        @Override
        public void endContact(Contact contact) {
            Car carA = contactCar(contact.getFixtureA());
            Car carB = contactCar(contact.getFixtureB());
            if (carA == null || carB == null) {
                return;
            }
            carA.endCarContact(carB);
            carB.endCarContact(carA);
        }

        @Override
        public void preSolve(Contact contact, Manifold oldManifold) {
            Car carA = contactCar(contact.getFixtureA());
            Car carB = contactCar(contact.getFixtureB());
            if (carA == null || carB == null) {
                return;
            }

            if (carA.isInvisible() || carB.isInvisible()) {
                contact.setEnabled(false);
                return;
            }

            contact.setFriction(Car.CAR_CONTACT_FRICTION);
        }

        @Override
        public void postSolve(Contact contact, ContactImpulse impulse) {
            Object userDataA = contact.getFixtureA().getBody().getUserData();
            Object userDataB = contact.getFixtureB().getBody().getUserData();
            if (!(userDataA instanceof Car) || !(userDataB instanceof Car)) {
                return;
            }

            Car carA = (Car) userDataA;
            Car carB = (Car) userDataB;
            if (!carA.active || !carB.active || carA.body == null || carB.body == null) {
                return;
            }

            Vector2 normal = contact.getWorldManifold().getNormal();
            if (normal.isZero(0.0001f)) {
                return;
            }

            float totalNormalImpulse = 0f;
            float[] normalImpulses = impulse.getNormalImpulses();
            for (int i = 0; i < normalImpulses.length; i++) {
                totalNormalImpulse += Math.abs(normalImpulses[i]);
            }

            if (totalNormalImpulse < Car.MIN_COLLISION_RESPONSE_IMPULSE) {
                return;
            }

            Vector2 velocityA = carA.body.getLinearVelocity();
            Vector2 velocityB = carB.body.getLinearVelocity();
            float closingSpeed = Math.max(
                    0f,
                    -((velocityB.x - velocityA.x) * normal.x
                            + (velocityB.y - velocityA.y) * normal.y));
            if (closingSpeed < Car.MIN_COLLISION_RESPONSE_SPEED) {
                return;
            }

            float speedIntoCollisionA = Math.max(0f, velocityA.dot(normal));
            float speedIntoCollisionB = Math.max(0f, -velocityB.dot(normal));

            float impactStrength = totalNormalImpulse + closingSpeed * Car.IMPACT_STRENGTH_SPEED_FACTOR;
            if (!roundOver && preRoundCountdownTimer <= 0f) {
                playImpactSound(impactStrength);
                if (isPresentationEnabled()) {
                    Vector2 positionA = carA.body.getPosition();
                    Vector2 positionB = carB.body.getPosition();
                    raceParticleEffects.emitImpact(
                            (positionA.x + positionB.x) * 0.5f,
                            (positionA.y + positionB.y) * 0.5f,
                            normal.x,
                            normal.y,
                            impactStrength,
                            (carA.color.r + carB.color.r) * 0.5f,
                            (carA.color.g + carB.color.g) * 0.5f,
                            (carA.color.b + carB.color.b) * 0.5f);
                }
            }

            boolean carADominant = speedIntoCollisionA > speedIntoCollisionB + 0.24f;
            boolean carBDominant = speedIntoCollisionB > speedIntoCollisionA + 0.24f;
            boolean carARamHit = carADominant && carA.hasRamCharge();
            boolean carBRamHit = carBDominant && carB.hasRamCharge();
            boolean carAEmpoweredHit = carARamHit || (carADominant && carA.hasGrowthBoost());
            boolean carBEmpoweredHit = carBRamHit || (carBDominant && carB.hasGrowthBoost());

            if (!roundOver && preRoundCountdownTimer <= 0f) {
                if (carADominant) {
                    activateCrownBreakerReturnHit(carA, carB);
                } else if (carBDominant) {
                    activateCrownBreakerReturnHit(carB, carA);
                }
            }

            if (!roundOver && preRoundCountdownTimer <= 0f) {
                if (carADominant) {
                    registerQualifiedRevengeHit(carB, carA, impactStrength);
                    recordRevengeHit(carB, carA);
                } else if (carBDominant) {
                    registerQualifiedRevengeHit(carA, carB, impactStrength);
                    recordRevengeHit(carA, carB);
                } else {
                    registerQualifiedRevengeHit(carA, carB, impactStrength);
                    registerQualifiedRevengeHit(carB, carA, impactStrength);
                    recordRevengeHit(carA, carB);
                    recordRevengeHit(carB, carA);
                }
            }

            carA.absorbCollision(
                    normal,
                    -1f,
                    impactStrength,
                    speedIntoCollisionB,
                    carA.getCollisionReboundMultiplierAgainst(carB));
            carA.receiveCombatHit(
                    carB,
                    currentMap,
                    impactStrength,
                    speedIntoCollisionB,
                    carBEmpoweredHit);
            carB.absorbCollision(
                    normal,
                    1f,
                    impactStrength,
                    speedIntoCollisionA,
                    carB.getCollisionReboundMultiplierAgainst(carA));
            carB.receiveCombatHit(
                    carA,
                    currentMap,
                    impactStrength,
                    speedIntoCollisionA,
                    carAEmpoweredHit);
            carA.recordCarHit();
            carB.recordCarHit();

            if (carARamHit) {
                carA.consumeRamCharge();
            }
            if (carBRamHit) {
                carB.consumeRamCharge();
            }

        }

        private Car contactCar(Fixture fixture) {
            if (fixture == null || fixture.getBody() == null) {
                return null;
            }
            Object userData = fixture.getBody().getUserData();
            return userData instanceof Car ? (Car) userData : null;
        }

        private boolean beginMapWallContact(Contact contact) {
            Fixture fixtureA = contact.getFixtureA();
            Fixture fixtureB = contact.getFixtureB();
            Car carA = contactCar(fixtureA);
            Car carB = contactCar(fixtureB);
            boolean wallA = fixtureA != null
                    && fixtureA.getUserData() == MAP_WALL_FIXTURE_USER_DATA;
            boolean wallB = fixtureB != null
                    && fixtureB.getUserData() == MAP_WALL_FIXTURE_USER_DATA;
            if ((carA == null || !wallB) && (carB == null || !wallA)) {
                return false;
            }

            Vector2 normal = contact.getWorldManifold().getNormal();
            if (normal.isZero(0.0001f)) {
                return true;
            }
            if (carA != null && wallB) {
                if (carA.queueMapWallBounce(-normal.x, -normal.y)
                        && isPresentationEnabled()) {
                    carA.automaticRecoveryExplosionVisualPending = true;
                }
            } else {
                if (carB.queueMapWallBounce(normal.x, normal.y)
                        && isPresentationEnabled()) {
                    carB.automaticRecoveryExplosionVisualPending = true;
                }
            }
            return true;
        }
    }

    private static final class CarPerformance {
        private static final float BASE_WEIGHT_KG_PER_MASS_MULTIPLIER = 1040f;

        private final String name;
        private final int horsePower;
        private final int weightKg;
        private final int topSpeedKph;
        private final float brakeForce;
        private final float steeringTorque;
        private final float wheelGrip;
        private final float aeroDrag;
        private final CarPhysics physics;

        private CarPerformance(
                String name,
                int horsePower,
                int weightKg,
                int topSpeedKph,
                float brakeForce,
                float steeringTorque,
                float wheelGrip,
                float aeroDrag) {
            this.name = name;
            this.horsePower = horsePower;
            this.weightKg = weightKg;
            this.topSpeedKph = topSpeedKph;
            this.brakeForce = brakeForce;
            this.steeringTorque = steeringTorque;
            this.wheelGrip = wheelGrip;
            this.aeroDrag = aeroDrag;
            physics =
                    CarPhysics.DEFAULT.withPerformanceTuning(
                            weightKg / BASE_WEIGHT_KG_PER_MASS_MULTIPLIER,
                            horsePower,
                            brakeForce,
                            steeringTorque,
                            wheelGrip,
                            aeroDrag,
                            topSpeedKph / 3.6f);
        }

    }

